window.STUDY[2]=[
/* 2-0 مقدمة */
{s:`### الطاقة الداخلية
- جزيئات المادة تمتلك طاقة حركية (انتقالية واهتزازية) وطاقة وضع (تجاذب) وطاقات أخرى.
- **الطاقة الداخلية** = مجموع كل أنواع الطاقة التي تمتلكها جزيئات المادة.
### درجة الحرارة وكمية الحرارة
- عندما تكتسب المادة حرارة تزيد طاقتها الداخلية فترتفع درجة حرارتها، والعكس.
- **درجة الحرارة** تحدد اتجاه انتقال الحرارة بين جسمين متلامسين (من الأعلى إلى الأقل).
- **كمية الحرارة** هي الطاقة المنتقلة نفسها، وتقاس بالجول.
### ما ستتعلمه
- مقاييس درجة الحرارة والتحويل بينها، الحرارة النوعية والسعة الحرارية، الحرارة الكامنة، الاتزان الحراري، طرق انتقال الحرارة.`,
ex:{q:`كوب ماء ساخن \`70°C\` وحوض ماء بارد \`20°C\` كبير جدًا. أيهما له طاقة داخلية أكبر؟ وفي أي اتجاه تنتقل الحرارة إذا تلامسا؟`,
st:[`الطاقة الداخلية تعتمد على كمية المادة ودرجة حرارتها معًا.`,`الحوض يحتوي جزيئات أكثر بكثير، فقد تكون طاقته الداخلية الكلية أكبر رغم برودته.`,`لكن اتجاه انتقال الحرارة تحدده **درجة الحرارة** فقط.`],
a:`الحرارة تنتقل من الكوب (70°C) إلى الحوض (20°C) مهما كان حجمهما.`},
qz:[
{q:`الطاقة الداخلية للمادة هي:`,o:[`طاقة الحركة فقط`,`مجموع جميع أنواع الطاقة لجزيئاتها`,`درجة حرارتها`,`وزنها`],a:1,w:`تعريف الطاقة الداخلية.`},
{q:`الخاصية التي تحدد اتجاه انتقال الحرارة بين جسمين:`,o:[`الكتلة`,`الحجم`,`درجة الحرارة`,`الطاقة الداخلية`],a:2,w:`الحرارة تنتقل من الدرجة الأعلى إلى الأقل.`},
{q:`عندما تفقد المادة حرارة فإن درجة حرارتها:`,o:[`ترتفع`,`تنخفض`,`لا تتغير أبدًا`,`تتضاعف`],a:1,w:`تقل طاقتها الداخلية فتنخفض درجة حرارتها (ما لم يحدث تغير حالة).`},
{q:`العلاقة الصحيحة بين كمية الحرارة ودرجة الحرارة:`,o:[`هما الشيء نفسه`,`كمية الحرارة طاقة تقاس بالجول، ودرجة الحرارة مقياس لمتوسط طاقة حركة الجزيئات`,`درجة الحرارة طاقة تقاس بالجول`,`كمية الحرارة تقاس بالكلفن`],a:1,w:`كمية الحرارة طاقة (J)، ودرجة الحرارة مقياس (°C أو K).`}
]},
/* 2-1 الحرارة */
{s:`### الحرارة (كمية الحرارة)
- شكل من أشكال الطاقة (طاقة حرارية).
- تنتقل **تلقائيًا** من الجسم الساخن إلى البارد حتى يحدث **الاتزان الحراري**.
- وحدتها في SI: **الجول J** (نسبة للعالم جيمس جول)، ووحدة أخرى شائعة: **السُّعر cal**.
- \`1 cal ≈ 4.186 J\`
### مصادر الطاقة الحرارية
- الشمس، باطن الأرض، التفاعلات الكيميائية (الاحتراق)، الطاقة النووية، الاحتكاك، الكهرباء.`,
ex:{q:`حوّل \`500 cal\` إلى جول.`,
st:[`\`1 cal ≈ 4.186 J\``,`\`500 × 4.186 = 2093 J\``],
a:`\`≈ 2093 J\``},
qz:[
{q:`وحدة قياس كمية الحرارة في النظام الدولي:`,o:[`الكلفن`,`الجول`,`الدرجة المئوية`,`الواط`],a:1,w:`الحرارة طاقة، فوحدتها الجول.`},
{q:`تنتقل الحرارة تلقائيًا:`,o:[`من البارد إلى الساخن`,`من الساخن إلى البارد`,`لا تنتقل`,`في الاتجاهين بالتساوي`],a:1,w:`حتى تتساوى درجتا الحرارة.`},
{q:`فرك اليدين يدفئهما. مصدر الحرارة هنا:`,o:[`الشمس`,`الاحتكاك`,`التفاعل النووي`,`الكهرباء`],a:1,w:`الاحتكاك يحول الشغل إلى حرارة.`},
{q:`\`1 cal\` يساوي تقريبًا:`,o:[`1 J`,`4.186 J`,`1000 J`,`0.24 J`],a:1,w:`المكافئ الميكانيكي للحرارة.`}
]},
/* 2-2 درجة الحرارة ومقاييسها */
{s:`### درجة الحرارة
- مقياس لمتوسط طاقة حركة جزيئات المادة، وتقاس بالترمومتر (الميزان الحراري).
### المقاييس الثلاثة (تجمد الماء ← غليانه)
- **المئوي (سلسيوس):** \`0°C\` ← \`100°C\` (100 قسم)
- **الكلفن (المطلق):** \`273 K\` ← \`373 K\` (100 قسم)
- **الفهرنهايت:** \`32°F\` ← \`212°F\` (180 قسمًا)
### قوانين التحويل
- \`K = C + 273\`
- \`F = 1.8·C + 32\`
- \`C = (F − 32) / 1.8\`
- يتساوى المئوي والفهرنهايت عند \`−40\`.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: تحويل درجة جسم ساخن من المئوي إلى الكلفن
- **السؤال:** درجة حرارة جسم ساخن \`300°C\` فما هي على المقياس المطلق (الكلفن)؟
- **المعطيات:** \`C = 300°C\`
- **المطلوب:** درجة الحرارة بالكلفن \`K\`.
- **لماذا هذا القانون؟** المقياس المئوي والكلفن لهما الحجم نفسه للدرجة الواحدة (كلاهما 100 قسم بين التجمد والغليان)، والفرق الوحيد هو نقطة البداية: الماء يتجمد عند \`0°C\` أي عند \`273 K\`. لذلك يكفي إزاحة القراءة بمقدار 273.
- **القانون:** \`K = C + 273\` حيث \`K\` درجة الحرارة بالكلفن و \`C\` درجة الحرارة بالسلسيوس.
- **الحل:** نعوّض بالقيمة المئوية: \`K = 300 + 273\`
- **الحل:** نجمع: \`K = 573 K\`
- **النتيجة:** درجة حرارة الجسم \`573 K\` ✓
### مثال ٢: تحويل درجة حرارة الغرفة من الفهرنهايت إلى المئوي
- **السؤال:** درجة حرارة الغرفة \`72°F\` فما هي درجة حرارتها على مقياس سلسيوس؟
- **المعطيات:** \`F = 72°F\`
- **المطلوب:** درجة الحرارة بالمئوي \`C\`.
- **لماذا هذا القانون؟** مقياس فهرنهايت يبدأ تجمد الماء عنده من \`32\` لا من الصفر، فنطرح 32 أولًا لنحسب عدد الأقسام فوق نقطة التجمد. ثم إن المسافة بين التجمد والغليان تساوي 180 قسمًا فهرنهايت مقابل 100 قسم مئوي، أي أن كل درجة مئوية تساوي \`180 ÷ 100 = 1.8\` درجة فهرنهايت، فنقسم على 1.8.
- **القانون:** \`C = (F − 32) / 1.8\`
- **الحل:** نطرح أولًا (ما بين القوسين): \`F − 32 = 72 − 32 = 40\`
- **الحل:** نقسم الناتج على 1.8: \`C = 40 / 1.8 = 22.2°C\`
- **النتيجة:** درجة حرارة الغرفة تقريبًا \`22.2°C\` (أي نحو \`22°C\`) ✓
- **ملاحظة:** كُتب التعويض في الحل الأصلي بالشكل \`C = 72 − 32/1.8\` دون أقواس، وهذا يعطي قيمة خاطئة لو حُسب حرفيًا؛ الصحيح وضع الطرح بين قوسين \`(72 − 32) / 1.8\`، والناتج الدقيق \`22.2\` قُرّب في الحل الأصلي إلى \`22\`.
### مثال ٣: تحويل درجة جسم ساخن من المئوي إلى الفهرنهايت
- **السؤال:** درجة حرارة جسم ساخن \`300°C\` فما هي درجة حرارته على المقياس الفهرنهايت؟
- **المعطيات:** \`C = 300°C\`
- **المطلوب:** درجة الحرارة بالفهرنهايت \`F\`.
- **لماذا هذا القانون؟** هو القانون السابق نفسه بعد عكسه: نضرب في 1.8 لتحويل عدد الدرجات المئوية إلى عدد أقسام فهرنهايت، ثم نضيف 32 لأن الفهرنهايت يبدأ من 32 عند تجمد الماء.
- **القانون:** \`F = 1.8·C + 32\` (أو بالصيغة المكافئة \`C = (F − 32) / 1.8\`)
- **الحل:** نضرب أولًا: \`1.8 × 300 = 540\`
- **الحل:** نضيف 32: \`F = 540 + 32 = 572°F\`
- **الحل (طريقة الحل الأصلي):** \`300 = (F − 32) / 1.8\` ← نضرب الطرفين في 1.8: \`540 = F − 32\` ← \`F = 572\`
- **النتيجة:** \`F = 572°F\` ✓
### مثال ٤: متى تتساوى قراءة الفهرنهايت والسلسيوس
- **السؤال:** متى تتساوى درجة الحرارة بين الفهرنهايت والسلسيوس؟
- **المعطيات:** نبحث عن درجة يكون عندها \`F = C\`، ونسميها \`x\`.
- **المطلوب:** قيمة \`x\`.
- **القانون:** \`F = 1.8·C + 32\`
- **الحل:** نعوّض \`F = x\` و \`C = x\`: \`x = 1.8x + 32\`
- **الحل:** ننقل الحدود التي فيها \`x\` إلى طرف واحد: \`x − 1.8x = 32\` ← \`−0.8x = 32\`
- **الحل:** نقسم على \`−0.8\`: \`x = 32 / (−0.8) = −40\`
- **التحقق:** \`F = 1.8 × (−40) + 32 = −72 + 32 = −40\` ✓
- **النتيجة:** يتساوى المقياسان عند الدرجة \`−40\`، أي \`−40°C = −40°F\` ✓
### مثال ٥: متى تتساوى قراءة الفهرنهايت والكلفن
- **السؤال:** متى تتساوى درجة الحرارة بين الفهرنهايت والكلفن؟
- **المعطيات:** نبحث عن درجة يكون عندها \`F = K\`، ونسميها \`x\`.
- **المطلوب:** قيمة \`x\`.
- **لماذا نجمع قانونين؟** لا يوجد قانون مباشر بين F و K، لذلك نمر عبر المقياس المئوي: من \`K = C + 273\` نحصل على \`C = K − 273\`، ثم نعوّضها في \`F = 1.8·C + 32\`.
- **القانون:** \`F = 1.8·(K − 273) + 32\`
- **الحل:** نعوّض \`F = x\` و \`K = x\`: \`x = 1.8(x − 273) + 32\`
- **الحل:** نفك القوس: \`x = 1.8x − 491.4 + 32 = 1.8x − 459.4\`
- **الحل:** نرتب: \`459.4 = 1.8x − x = 0.8x\`
- **الحل:** نقسم على 0.8: \`x = 459.4 / 0.8 = 574.25\`
- **التحقق:** \`C = 574.25 − 273 = 301.25°C\` ← \`F = 1.8 × 301.25 + 32 = 542.25 + 32 = 574.25°F\` ✓
- **النتيجة:** يتساوى المقياسان عند \`574.25\` تقريبًا، أي \`574.25 K = 574.25°F\` ✓
`,
ex:{q:`حرارة الجو في الرياض صيفًا \`42°C\`. حوّلها إلى فهرنهايت وكلفن.`,
st:[`\`F = 1.8 × 42 + 32\``,`\`F = 75.6 + 32 = 107.6°F\``,`\`K = 42 + 273 = 315 K\``],
a:`\`107.6°F\` و \`315 K\``},
qz:[
{q:`حوّل \`30°C\` إلى فهرنهايت:`,o:[`86°F`,`56°F`,`62°F`,`54°F`],a:0,w:`1.8 × 30 + 32 = 86°F.`},
{q:`حوّل \`20°C\` إلى كلفن:`,o:[`253 K`,`293 K`,`273 K`,`20 K`],a:1,w:`20 + 273 = 293 K.`},
{q:`\`95°F\` تساوي بالمئوي:`,o:[`35°C`,`42°C`,`27°C`,`63°C`],a:0,w:`(95 − 32)/1.8 = 63/1.8 = 35°C.`},
{q:`\`32°F\` على مقياس فهرنهايت تمثل:`,o:[`درجة تجمد الماء`,`درجة غليان الماء`,`الصفر المطلق`,`درجة حرارة الجسم`],a:0,w:`تقابل 0°C.`},
{q:`يتساوى المقياسان المئوي والفهرنهايت عند:`,o:[`0`,`100`,`−40`,`32`],a:2,w:`−40°C = 1.8(−40) + 32 = −40°F.`}
]},
/* 2-3 الحرارة النوعية */
{s:`### الحرارة النوعية c
- كمية الحرارة اللازمة لرفع درجة حرارة **1 kg** من المادة **درجة واحدة**.
- \`Q = m·c·ΔT\` ← الوحدة \`J/(kg·°C)\` أو \`J/(kg·K)\`
- للماء: \`c ≈ 4180 J/(kg·°C)\` — قيمة كبيرة، لذلك يسخن ويبرد ببطء.
### السعة الحرارية C
- كمية الحرارة اللازمة لرفع درجة حرارة **الجسم كله** درجة واحدة.
- \`C = m·c\` ← الوحدة \`J/°C\`
### تنبيه
- حوّل الكتلة إلى kg دائمًا: \`100 g = 0.1 kg\`.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: الطاقة اللازمة لتسخين كمية من الماء
- **السؤال:** أوجد قيمة الطاقة الحرارية التي تحتاجها لتسخين \`100 g\` من الماء من \`10°C\` إلى \`30°C\` علمًا بأن الحرارة النوعية للماء \`4180 J/kg·°C\`.
- **المعطيات:** \`m = 100 g = 100 ÷ 1000 = 0.1 kg\` · \`c = 4180 J/kg·°C\` · \`T₁ = 10°C\` · \`T₂ = 30°C\`
- **المطلوب:** كمية الحرارة \`Q\`.
- **لماذا هذا القانون؟** المادة هنا تبقى ماءً سائلًا (لا يتغير طورها)، فكل الحرارة المكتسبة تذهب إلى رفع درجة الحرارة؛ وكمية الحرارة تتناسب طرديًا مع الكتلة ومع الحرارة النوعية ومع مقدار التغير في درجة الحرارة.
- **القانون:** \`Q = m·c·ΔT\` حيث \`Q\` كمية الحرارة (J)، \`m\` الكتلة (kg)، \`c\` الحرارة النوعية (J/kg·°C)، \`ΔT\` التغير في درجة الحرارة (°C).
- **الحل:** نحسب التغير في درجة الحرارة (النهائية ناقص الابتدائية): \`ΔT = 30 − 10 = 20°C\`
- **الحل:** نعوّض: \`Q = 0.1 × 4180 × 20\`
- **الحل:** \`0.1 × 4180 = 418\` ثم \`418 × 20 = 8360 J\`
- **النتيجة:** \`Q = 8360 J\`، والإشارة موجبة لأن الماء اكتسب حرارة ✓
### مثال ٢: السعة الحرارية وكمية الحرارة لقطعة نحاس
- **السؤال:** قطعة من النحاس كتلتها \`20 g\` سُخّنت من \`20°C\` إلى \`100°C\` علمًا بأن الحرارة النوعية للنحاس \`400 J/kg·°C\`. أوجد كلًّا من: السعة الحرارية، وكمية الحرارة.
- **المعطيات:** \`m = 20 g = 20 ÷ 1000 = 0.02 kg\` · \`c = 400 J/kg·°C\` · \`T₁ = 20°C\` · \`T₂ = 100°C\`
- **المطلوب:** أولًا السعة الحرارية \`C\`، ثانيًا كمية الحرارة \`Q\`.
- **الفرق بين المفهومين:** الحرارة النوعية \`c\` خاصية للمادة (لكل 1 kg)، أما السعة الحرارية \`C\` فخاصية للجسم كله بكتلته الفعلية: كم جولًا يلزمه ليرتفع درجة واحدة.
- **القانون (أولًا):** \`C = m·c\`
- **الحل:** \`C = 0.02 × 400 = 8 J/°C\`
- **القانون (ثانيًا):** \`Q = m·c·ΔT\` أو بصورة مختصرة \`Q = C·ΔT\`
- **الحل:** التغير في درجة الحرارة: \`ΔT = 100 − 20 = 80°C\`
- **الحل:** \`Q = 0.02 × 400 × 80 = 8 × 80 = 640 J\`
- **النتيجة:** السعة الحرارية \`C = 8 J/°C\`، وكمية الحرارة \`Q = 640 J\` ✓
- **ملاحظة:** كُتبت وحدة السعة الحرارية في الحل الأصلي \`J/kg·°C\`، والصحيح \`J/°C\` لأن الكتلة ضُربت في الحرارة النوعية فاختُصرت وحدة kg.
`,
ex:{q:`احسب الحرارة اللازمة لتسخين \`0.5 kg\` ماء من \`20°C\` إلى \`80°C\` (\`c = 4180\`). ثم احسب السعة الحرارية لقطعة حديد \`0.5 kg\` (\`c = 500\`).`,
st:[`\`ΔT = 80 − 20 = 60°C\``,`\`Q = 0.5 × 4180 × 60 = 125400 J\``,`السعة الحرارية للحديد: \`C = 0.5 × 500 = 250 J/°C\``],
a:`\`Q = 125400 J ≈ 125 kJ\` و \`C = 250 J/°C\``},
qz:[
{q:`الحرارة اللازمة لتسخين \`0.1 kg\` ماء بمقدار \`20°C\` (c = 4180):`,o:[`8360 J`,`836 J`,`83600 J`,`418 J`],a:0,w:`0.1 × 4180 × 20 = 8360 J.`},
{q:`وحدة السعة الحرارية:`,o:[`J/(kg·°C)`,`J/°C`,`J/kg`,`°C/J`],a:1,w:`C = m·c ← kg × J/(kg·°C) = J/°C.`},
{q:`نحاس \`0.02 kg\` امتص \`600 J\` فارتفعت حرارته \`80°C\`، حرارته النوعية:`,o:[`375 J/(kg·°C)`,`480 J/(kg·°C)`,`960 J/(kg·°C)`,`7.5 J/(kg·°C)`],a:0,w:`c = Q/(mΔT) = 600/(0.02 × 80) = 600/1.6 = 375.`},
{q:`وعاء ألمنيوم سعته الحرارية \`270 J/°C\` وحرارته النوعية \`900\`، كتلته:`,o:[`0.3 kg`,`3.3 kg`,`243 kg`,`0.03 kg`],a:0,w:`m = C/c = 270/900 = 0.3 kg.`}
]},
/* 2-4 الحرارة الكامنة */
{s:`### الحرارة الكامنة للانصهار
- الطاقة اللازمة لتحويل **1 kg** من المادة الصلبة إلى سائلة **عند درجة انصهارها** دون تغير في درجة حرارتها.
- \`Q = m·H\` ← \`H = Q/m\` ← الوحدة \`J/kg\`
- للجليد: \`H ≈ 336000 J/kg\`
### لماذا لا ترتفع درجة الحرارة أثناء الانصهار؟
- لأن الطاقة تُستهلك في فك الروابط بين الجزيئات وليس في زيادة سرعتها.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: حساب الحرارة الكامنة لانصهار الجليد
- **السؤال:** إذا كانت الطاقة الحرارية \`1344000 J\` لازمة لصهر \`4 kg\` من الجليد عند درجة حرارة \`0°C\`، احسب الحرارة الكامنة لانصهار الجليد.
- **المعطيات:** \`Q = 1344000 J\` · \`m = 4 kg\` · درجة الحرارة ثابتة عند \`0°C\`
- **المطلوب:** الحرارة الكامنة للانصهار \`H\`.
- **لماذا هذا القانون؟** الجليد عند \`0°C\` في نقطة انصهاره، فالطاقة المكتسبة لا ترفع درجة حرارته (لا يوجد \`ΔT\`) بل تُستهلك في تفكيك الروابط وتحويله من صلب إلى سائل؛ لذلك لا نستخدم \`Q = mcΔT\` بل قانون الحرارة الكامنة.
- **القانون:** \`Q = m·H\` حيث \`Q\` الحرارة اللازمة للصهر (J)، \`m\` كتلة المادة الصلبة (kg)، \`H\` الحرارة الكامنة للانصهار (J/kg).
- **الحل:** نجعل \`H\` موضوع القانون بقسمة الطرفين على \`m\`: \`H = Q / m\`
- **الحل:** نعوّض: \`H = 1344000 / 4\`
- **الحل:** \`H = 336000 J/kg\`
- **النتيجة:** الحرارة الكامنة لانصهار الجليد \`H = 336000 J/kg = 3.36 × 10⁵ J/kg\`، أي أن كل 1 kg من الجليد يحتاج \`336000 J\` ليذوب ✓
`,
ex:{q:`احسب الحرارة اللازمة لصهر \`200 g\` من الجليد عند \`0°C\`.`,
st:[`\`m = 200 g = 0.2 kg\``,`\`Q = m·H = 0.2 × 336000\``,`\`Q = 67200 J\``],
a:`\`Q = 67200 J\``},
qz:[
{q:`صهر \`4 kg\` جليد احتاج \`1344000 J\`، الحرارة الكامنة:`,o:[`336000 J/kg`,`5376000 J/kg`,`134400 J/kg`,`3360 J/kg`],a:0,w:`H = 1344000/4 = 336000 J/kg.`},
{q:`أثناء انصهار الجليد فإن درجة حرارته:`,o:[`ترتفع`,`تنخفض`,`تبقى ثابتة`,`تتذبذب`],a:2,w:`الطاقة تذهب لتغيير الحالة.`},
{q:`الحرارة اللازمة لصهر \`20 g\` جليد:`,o:[`6720 J`,`672 J`,`67200 J`,`16800 J`],a:0,w:`0.02 × 336000 = 6720 J.`},
{q:`اسم العملية التي يتحول فيها الثلج إلى ماء:`,o:[`التبخر`,`الانصهار`,`التكثف`,`التجمد`],a:1,w:`صلب ← سائل = انصهار.`}
]},
/* 2-5 الاتزان الحراري */
{s:`### الاتزان الحراري
- وصول جسمين مختلفين في درجة الحرارة إلى **درجة واحدة** عند تلامسهما.
- الحرارة المفقودة من الساخن = الحرارة المكتسبة للبارد.
- \`Q₁ + Q₂ = 0\` أو \`m₁c₁(T₁ − T_f) = m₂c₂(T_f − T₂)\`
### خطوات الحل
1. احسب الحرارة المكتسبة للجسم البارد.
2. ساوِها بالحرارة المفقودة من الساخن.
3. حلّ المعادلة للمجهول.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: إيجاد درجة الحرارة الابتدائية لقطعة ألمنيوم
- **السؤال:** سُخّنت قطعة من الألمنيوم كتلتها \`0.05 kg\` إلى درجة حرارة غير معروفة، ثم أُلقيت في وعاء يحتوي على \`0.15 kg\` من الماء عند درجة حرارة ابتدائية \`21°C\`، ووصلت درجة الحرارة للقطعة والماء إلى \`25°C\`. إذا كانت الحرارة النوعية للألمنيوم \`899 J/kg·°C\` والحرارة النوعية للماء \`4186 J/kg·°C\`، فما درجة الحرارة الابتدائية لقطعة الألمنيوم؟ (مع إهمال الحرارة التي يكتسبها الوعاء)
- **المعطيات:** الألمنيوم: \`m₁ = 0.05 kg\` · \`c₁ = 899 J/kg·°C\` · \`T₁ = ?\` — الماء: \`m₂ = 0.15 kg\` · \`c₂ = 4186 J/kg·°C\` · \`T₂ = 21°C\` — درجة الاتزان: \`Tf = 25°C\`
- **المطلوب:** درجة الحرارة الابتدائية للألمنيوم \`T₁\`.
- **تحديد اتجاه انتقال الحرارة:** درجة حرارة الماء ارتفعت من \`21°C\` إلى \`25°C\`، فالماء هو الجسم البارد الذي اكتسب حرارة؛ إذن الألمنيوم هو الجسم الساخن الذي فقدها، ودرجته الابتدائية يجب أن تكون أكبر من \`25°C\`.
- **لماذا هذا القانون؟** بإهمال الوعاء والوسط المحيط تكون الطاقة محفوظة: كل جول فقده الألمنيوم اكتسبه الماء، حتى تتساوى درجتا حرارتهما (الاتزان الحراري).
- **القانون:** الحرارة المفقودة = الحرارة المكتسبة: \`m₁·c₁·(T₁ − Tf) = m₂·c₂·(Tf − T₂)\`
- **الحل:** نحسب أولًا الحرارة التي اكتسبها الماء: \`ΔT الماء = 25 − 21 = 4°C\`
- **الحل:** \`Q الماء = 0.15 × 4186 × 4 = 2511.6 J\`
- **الحل:** نحسب حاصل ضرب كتلة الألمنيوم في حرارته النوعية: \`m₁·c₁ = 0.05 × 899 = 44.95 J/°C\`
- **الحل:** نساوي: \`44.95 × (T₁ − 25) = 2511.6\`
- **الحل:** نقسم على 44.95: \`T₁ − 25 = 2511.6 / 44.95 = 55.88°C\`
- **الحل:** نضيف 25: \`T₁ = 55.88 + 25 = 80.88°C\`
- **التحقق:** \`0.05 × 899 × (80.88 − 25) ≈ 2511.6 J\` وهي تساوي ما اكتسبه الماء ✓
- **النتيجة:** درجة الحرارة الابتدائية لقطعة الألمنيوم تقريبًا \`T₁ ≈ 80.9°C\` ✓
`,
ex:{q:`(مثال الحقيبة) قطعة ألمنيوم \`0.05 kg\` (\`c = 899\`) أُلقيت في \`0.15 kg\` ماء عند \`21°C\` (\`c = 4186\`) فوصل الجميع إلى \`25°C\`. ما درجة الحرارة الابتدائية للألمنيوم؟`,
st:[`حرارة اكتسبها الماء: \`Q = 0.15 × 4186 × (25 − 21)\``,`\`Q = 0.15 × 4186 × 4 = 2511.6 J\``,`حرارة فقدها الألمنيوم: \`0.05 × 899 × (T − 25) = 2511.6\``,`\`44.95 × (T − 25) = 2511.6\` ← \`T − 25 ≈ 55.9\``,`\`T ≈ 80.9°C\``],
a:`\`T ≈ 81°C\``},
qz:[
{q:`في الاتزان الحراري تكون الحرارة المفقودة:`,o:[`أكبر من المكتسبة`,`أقل من المكتسبة`,`مساوية للمكتسبة`,`صفرًا`],a:2,w:`بإهمال الفقد إلى الوسط المحيط.`},
{q:`الحالة التي يصل إليها خليط ماء ساخن وبارد تسمى:`,o:[`الانصهار`,`الاتزان الحراري`,`الحمل`,`الغليان`],a:1,w:`يصلان لدرجة حرارة واحدة.`},
{q:`مُزج \`1 kg\` ماء عند \`80°C\` مع \`1 kg\` ماء عند \`20°C\`، درجة الخليط:`,o:[`50°C`,`60°C`,`100°C`,`40°C`],a:0,w:`الكتلتان والحرارتان النوعيتان متساويتان ← المتوسط (80 + 20)/2 = 50°C.`},
{q:`يعتبر الماء سائلًا مثاليًا للتبريد والتسخين لأن:`,o:[`حرارته النوعية كبيرة`,`حرارته النوعية صغيرة`,`لا يتمدد`,`لونه شفاف`],a:0,w:`يخزن كمية كبيرة من الحرارة مع تغير صغير في درجته.`}
]},
/* 2-6 طرق انتقال الحرارة */
{s:`### طرق انتقال الحرارة
- **التوصيل:** انتقال الحرارة خلال المادة بالتلامس، من جزيء لآخر دون انتقال المادة نفسها (ملعقة معدنية في شاي ساخن).
- **الحمل:** في السوائل والغازات؛ المائع الساخن يتمدد وتقل كثافته فيرتفع، ويحل محله البارد (تسخين الماء، المنطاد، المكيف).
- **الإشعاع:** انتقال الطاقة على شكل موجات كهرومغناطيسية، ولا يحتاج وسطًا ماديًا (حرارة الشمس).`,
ex:{q:`حدّد طريقة انتقال الحرارة: (أ) دفء الشمس على وجهك، (ب) سخونة مقبض قدر معدني، (ج) تدفئة غرفة كاملة بمدفأة في زاويتها.`,
st:[`(أ) عبر الفراغ بين الشمس والأرض ← إشعاع.`,`(ب) خلال المعدن الصلب ← توصيل.`,`(ج) الهواء الساخن يرتفع ويدور في الغرفة ← حمل.`],
a:`(أ) إشعاع، (ب) توصيل، (ج) حمل.`},
qz:[
{q:`انتقال الحرارة بواسطة الأشعة:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`الانصهار`],a:2,w:`لا يحتاج وسطًا.`},
{q:`المنطاد الهوائي مثال على انتقال الحرارة بـ:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`لا شيء مما سبق`],a:1,w:`الهواء الساخن أقل كثافة فيرتفع.`},
{q:`الطريقة الوحيدة التي تنقل الحرارة في الفراغ:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`كلها`],a:2,w:`التوصيل والحمل يحتاجان مادة.`},
{q:`انتقال الحرارة خلال قضيب معدني:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`التبخر`],a:0,w:`عبر تلامس الجزيئات في المادة الصلبة.`}
]},
/* 2-7 ورقة عمل */
{s:`### ما تحتاجه لحل ورقة العمل
- التحويل: \`K = C + 273\` · \`F = 1.8C + 32\` · \`C = (F − 32)/1.8\`
- الحرارة: \`Q = m·c·ΔT\` (الكتلة بالكيلوجرام!)
- السعة الحرارية: \`C = m·c\` ← \`m = C/c\`
- الحرارة النوعية من التجربة: \`c = Q/(m·ΔT)\`
- الانصهار: \`Q = m·H\` (للجليد \`336000 J/kg\`)
- مسائل الحديد على الجليد: حرارة يفقدها الحديد حتى \`0°C\` = \`m·H\` لكتلة الجليد المنصهر.

### حل ورقة العمل

### سؤال ١: عرّف كلًّا مما يلي
- **١ – الطاقة الداخلية:** مجموع طاقات الحركة وطاقات الوضع لجميع جزيئات الجسم.
- **٢ – كمية الحرارة:** الطاقة التي تنتقل من جسم إلى آخر بسبب الفرق في درجة الحرارة بينهما، وتقاس بالجول \`J\`.
- **٣ – درجة الحرارة:** مقياس لمتوسط الطاقة الحركية لجزيئات الجسم، وتحدد اتجاه انتقال الحرارة بين الأجسام (من الأسخن إلى الأبرد).
- **٤ – الحرارة النوعية:** كمية الحرارة اللازمة لرفع درجة حرارة \`1 kg\` من المادة درجة سلزيوس واحدة، ووحدتها \`J/kg·°C\`، وتعطى بالعلاقة \`c = Q ÷ (m · ΔT)\`.
- **٥ – السعة الحرارية:** كمية الحرارة اللازمة لرفع درجة حرارة الجسم كله درجة سلزيوس واحدة، ووحدتها \`J/°C\`، وتعطى بالعلاقة \`C = m · c\`.

### سؤال ٢: درجة حرارة جسم ساخن 200 °C، ما درجة حرارته بالكلفن؟
- **المعطيات:** \`T_C = 200 °C\`
- **المطلوب:** درجة الحرارة المطلقة \`T_K\`
- **القانون:** \`T_K = T_C + 273\`
- **الحل:** \`T_K = 200 + 273\`
- **الحل:** \`T_K = 473 K\`
- **النتيجة:** درجة الحرارة المطلقة \`473 K\` ✓

### سؤال ٣: درجة حرارة جسم 150 °C، ما درجة حرارته على مقياس فهرنهايت؟
- **المعطيات:** \`T_C = 150 °C\`
- **المطلوب:** \`T_F\`
- **القانون:** \`T_F = (9 ÷ 5) × T_C + 32\`
- **الحل:** \`T_F = 1.8 × 150 + 32\`
- **الحل:** \`T_F = 270 + 32 = 302 °F\`
- **النتيجة:** \`T_F = 302 °F\` ✓

### سؤال ٤: درجة حرارة 80 °F، ما درجة حرارتها على مقياس سلزيوس؟
- **المعطيات:** \`T_F = 80 °F\`
- **المطلوب:** \`T_C\`
- **القانون:** \`T_C = (5 ÷ 9) × (T_F − 32)\`
- **الحل:** \`T_C = (5 ÷ 9) × (80 − 32)\`
- **الحل:** \`T_C = (5 ÷ 9) × 48 = 240 ÷ 9\`
- **الحل:** \`T_C ≈ 26.67 °C\`
- **النتيجة:** \`T_C ≈ 26.67 °C\` ✓

### سؤال ٥: ما الحرارة اللازمة لتسخين 20 g من الماء من 30 °C إلى 90 °C؟
- **المعطيات:** \`m = 20 g\` · \`T₁ = 30 °C\` · \`T₂ = 90 °C\` · \`c = 4180 J/kg·°C\`
- **المطلوب:** كمية الحرارة \`Q\`
- **القانون:** \`Q = m · c · ΔT\`
- **الحل:** تحويل الكتلة \`m = 20 ÷ 1000 = 0.02 kg\`
- **الحل:** \`ΔT = T₂ − T₁ = 90 − 30 = 60 °C\`
- **الحل:** \`Q = 0.02 × 4180 × 60\`
- **الحل:** \`Q = 5016 J\`
- **النتيجة:** كمية الحرارة اللازمة \`Q = 5016 J\` ✓

### سؤال ٦: احسب السعة الحرارية لقطعة من الحديد كتلتها 0.5 kg وحرارتها النوعية 500 J/kg·°C
- **المعطيات:** \`m = 0.5 kg\` · \`c = 500 J/kg·°C\`
- **المطلوب:** السعة الحرارية \`C\`
- **القانون:** \`C = m · c\`
- **الحل:** \`C = 0.5 × 500\`
- **الحل:** \`C = 250 J/°C\`
- **النتيجة:** السعة الحرارية \`C = 250 J/°C\` ✓

### سؤال ٧: احسب كمية الحرارة اللازمة لصهر 20 g من الجليد عند 0 °C
- **المعطيات:** \`m = 20 g\` · \`L = 336000 J/kg\`
- **المطلوب:** كمية الحرارة \`Q\`
- **القانون:** \`Q = m · L\`
- **الحل:** تحويل الكتلة \`m = 20 ÷ 1000 = 0.02 kg\`
- **الحل:** \`Q = 0.02 × 336000\`
- **الحل:** \`Q = 6720 J\`
- **النتيجة:** كمية الحرارة اللازمة للصهر \`Q = 6720 J\` ✓

### سؤال ٨: قطعة حديد كتلتها 3 kg عند 560 °C أُلقيت على لوح جليد كتلته 3 kg عند 0 °C فانصهر جزء منه
- **المعطيات:** \`m_Fe = 3 kg\` · \`T₁ = 560 °C\` · \`T₂ = 0 °C\` · \`c_Fe = 460 J/kg·°C\` · \`m_ice = 3 kg\` · \`L = 336000 J/kg\`
- **المطلوب:** ١) كتلة الجليد المنصهر ٢) كتلة الجليد المتبقي ٣) الحرارة اللازمة لصهر بقية الجليد
- **القانون:** \`Q_Fe = m · c · ΔT\` · \`Q_ice = m · L\` · الحرارة المفقودة = الحرارة المكتسبة
- **الحل:** الحرارة التي يفقدها الحديد حتى يبرد إلى \`0 °C\`: \`ΔT = 560 − 0 = 560 °C\`
- **الحل:** \`Q_Fe = 3 × 460 × 560 = 772800 J\`
- **الحل:** ١) كتلة الجليد المنصهر: \`m_melt = Q_Fe ÷ L = 772800 ÷ 336000\`
- **الحل:** \`m_melt = 2.3 kg\`
- **الحل:** ٢) كتلة الجليد المتبقي: \`m_rest = 3 − 2.3 = 0.7 kg\`
- **الحل:** ٣) الحرارة اللازمة لصهر الباقي: \`Q = m_rest · L = 0.7 × 336000\`
- **الحل:** \`Q = 235200 J\`
- **النتيجة:** ١) \`2.3 kg\` ٢) \`0.7 kg\` ٣) \`235200 J\` ✓

### سؤال ٩: قطعة نحاس كتلتها 20 g اكتسبت 600 J فتغيرت درجة حرارتها 80 °C، أوجد الحرارة النوعية للنحاس
- **المعطيات:** \`m = 20 g\` · \`Q = 600 J\` · \`ΔT = 80 °C\`
- **المطلوب:** الحرارة النوعية \`c\`
- **القانون:** \`c = Q ÷ (m · ΔT)\`
- **الحل:** تحويل الكتلة \`m = 20 ÷ 1000 = 0.02 kg\`
- **الحل:** \`c = 600 ÷ (0.02 × 80)\`
- **الحل:** \`c = 600 ÷ 1.6\`
- **الحل:** \`c = 375 J/kg·°C\`
- **النتيجة:** الحرارة النوعية للنحاس \`c = 375 J/kg·°C\` ✓

### سؤال ١٠: السعة الحرارية لوعاء ألمنيوم 270 J/°C والحرارة النوعية للألمنيوم 900 J/kg·°C، أوجد كتلة الوعاء
- **المعطيات:** \`C = 270 J/°C\` · \`c = 900 J/kg·°C\`
- **المطلوب:** الكتلة \`m\`
- **القانون:** \`C = m · c\` ومنه \`m = C ÷ c\`
- **الحل:** \`m = 270 ÷ 900\`
- **الحل:** \`m = 0.3 kg\`
- **النتيجة:** كتلة الوعاء \`m = 0.3 kg\` (أي \`300 g\`) ✓
`,
ex:{q:`(مثال مشابه) قطعة نحاس \`1 kg\` عند \`300°C\` (\`c = 390\`) وُضعت على جليد عند \`0°C\`. ما كتلة الجليد التي تنصهر؟`,
st:[`الحرارة التي يفقدها النحاس حتى يبرد إلى \`0°C\`: \`Q = 1 × 390 × 300 = 117000 J\``,`هذه الحرارة تصهر جليدًا: \`m = Q/H = 117000/336000\``,`\`m ≈ 0.348 kg\``],
a:`ينصهر نحو \`0.35 kg\` من الجليد.`},
qz:[
{q:`\`200°C\` بالكلفن:`,o:[`73 K`,`473 K`,`392 K`,`200 K`],a:1,w:`200 + 273 = 473 K.`},
{q:`\`150°C\` بالفهرنهايت:`,o:[`302°F`,`270°F`,`182°F`,`118°F`],a:0,w:`1.8 × 150 + 32 = 302°F.`},
{q:`\`80°F\` بالمئوي تقريبًا:`,o:[`26.7°C`,`44.4°C`,`48°C`,`112°C`],a:0,w:`(80 − 32)/1.8 = 48/1.8 ≈ 26.7°C.`},
{q:`السعة الحرارية لحديد \`0.5 kg\` (c = 500):`,o:[`1000 J/°C`,`250 J/°C`,`500.5 J/°C`,`0.001 J/°C`],a:1,w:`0.5 × 500 = 250 J/°C.`}
]},
/* 2-8 تمارين الوحدة */
{s:`### مراجعة الوحدة الثالثة
- **درجة الحرارة:** مقياس لمتوسط طاقة حركة الجزيئات · **الحرارة:** طاقة منتقلة (J).
- **التحويل:** \`K = C + 273\` · \`F = 1.8C + 32\`
- **الحرارة النوعية:** \`Q = mcΔT\` · **السعة الحرارية:** \`C = mc\` · **الانصهار:** \`Q = mH\`
- **الاتزان:** المفقود = المكتسب.
- **الانتقال:** توصيل (صلب)، حمل (موائع)، إشعاع (موجات، يعمل في الفراغ).
- **الترمومتر الزئبقي:** يعتمد على تمدد السائل بالحرارة.
### مسألة سخان كهربائي
- الطاقة من السخان: \`E = P·t\` ← وتساوي \`Q = mcΔT\` ← \`t = mcΔT / P\`
### تمارين الوحدة محلولة
### سؤال ١: انتقال الحرارة خلال مادة
- **السؤال:** هو انتقال الحرارة خلال مادة ما: (التوصيل – الحمل – الإشعاع)
- **الإجابة:** **التوصيل**
- **التفسير:** في التوصيل تنتقل الطاقة من جزيء إلى الجزيء المجاور له عبر المادة نفسها بالتلامس، دون أن تنتقل جزيئات المادة من مكانها (مثل ملعقة معدنية في شاي ساخن).
### سؤال ٢: انتقال الحرارة خلال مادة مسخنة
- **السؤال:** هو انتقال الحرارة خلال مادة مسخنة: (التوصيل – الحمل – الإشعاع)
- **الإجابة:** **الحمل**
- **التفسير:** في الحمل تتحرك المادة المسخنة نفسها (سائل أو غاز): الجزء الساخن يتمدد وتقل كثافته فيرتفع حاملًا الحرارة معه، ويحل محله الجزء البارد.
### سؤال ٣: انتقال الحرارة بواسطة الأشعة
- **السؤال:** هو انتقال الحرارة بواسطة الأشعة: (التوصيل – الحمل – الإشعاع)
- **الإجابة:** **الإشعاع**
- **التفسير:** الإشعاع انتقال للطاقة على شكل موجات كهرومغناطيسية لا تحتاج وسطًا ماديًا، ولذلك تصلنا حرارة الشمس عبر الفراغ.
### سؤال ٤: درجة حرارة الرياض بالفهرنهايت
- **السؤال:** إذا كانت درجة الحرارة في مدينة الرياض \`30°C\` فكم تعادل على مقياس فهرنهايت؟ (\`86°F\` – \`56°F\` – \`26°F\`)
- **المعطيات:** \`C = 30°C\`
- **القانون:** \`F = 1.8·C + 32\` (نضرب في 1.8 لأن الدرجة المئوية تساوي 1.8 درجة فهرنهايت، ونضيف 32 لأن تجمد الماء عند \`32°F\`)
- **الحل:** \`1.8 × 30 = 54\`
- **الحل:** \`F = 54 + 32 = 86°F\`
- **النتيجة:** **\`F = 86°F\`** ✓
### سؤال ٥: تحويل درجة من الكلفن إلى الفهرنهايت
- **السؤال:** إذا علمت أن درجة الحرارة على مقياس كلفن تساوي \`300\`، فكم تساوي على مقياس فهرنهايت؟ (\`86°F\` – \`56°F\` – \`80.6°F\`)
- **المعطيات:** \`K = 300 K\`
- **فكرة الحل:** لا يوجد قانون مباشر بين الكلفن والفهرنهايت، فنحوّل أولًا إلى المئوي ثم إلى الفهرنهايت.
- **القانون:** \`C = K − 273\` ثم \`F = 1.8·C + 32\`
- **الحل:** \`C = 300 − 273 = 27°C\`
- **الحل:** \`1.8 × 27 = 48.6\`
- **الحل:** \`F = 48.6 + 32 = 80.6°F\`
- **النتيجة:** **\`F = 80.6°F\`** ✓
### سؤال ٦: تحويل درجة من المئوي إلى الكلفن
- **السؤال:** نتيجة تحويل \`20°C\` إلى الكلفن هي: (\`273 K\` – \`293 K\` – \`300 K\`)
- **القانون:** \`K = C + 273\`
- **الحل:** \`K = 20 + 273 = 293 K\`
- **النتيجة:** **\`293 K\`** ✓
- **ملاحظة:** وحدة الكلفن تُكتب \`K\` فقط دون رمز الدرجة \`°\`.
### سؤال ٧: تحويل درجة من الفهرنهايت إلى المئوي
- **السؤال:** إذا كانت درجة الحرارة في المقياس الفهرنهايت \`95°F\` فإنها تكون على المقياس المئوي: (\`35°C\` – \`42°C\` – \`27°C\`)
- **القانون:** \`C = (F − 32) / 1.8\`
- **الحل:** نطرح أولًا: \`95 − 32 = 63\`
- **الحل:** نقسم: \`C = 63 / 1.8 = 35°C\`
- **النتيجة:** **\`35°C\`** ✓
### سؤال ٨: درجة حرارة الصيف في الرياض بالفهرنهايت
- **السؤال:** درجة حرارة الجو في الرياض في فصل الصيف \`42°C\` فإنها تكون بالفهرنهايت: (\`107.6°F\` – \`117°F\` – \`95°F\`)
- **القانون:** \`F = 1.8·C + 32\`
- **الحل:** \`1.8 × 42 = 75.6\`
- **الحل:** \`F = 75.6 + 32 = 107.6°F\`
- **النتيجة:** **\`107.6°F\`** ✓
### سؤال ٩: مبدأ عمل الترمومتر الزئبقي
- **السؤال:** المبدأ العلمي الذي يقوم عليه صنع الترمومتر الزئبقي: (تغير كتلة السائل بالحرارة – تمدد السائل بالحرارة – تمدد الغازات بالحرارة)
- **الإجابة:** **تمدد السائل بالحرارة**
- **التفسير:** الزئبق سائل يتمدد بانتظام عند ارتفاع درجة الحرارة فيرتفع في الأنبوب الشعري، أما الكتلة فلا تتغير بالتسخين.
### سؤال ١٠: معنى القراءة الفهرنهايتية لتجمد الماء
- **السؤال:** \`32°F\` تمثل على مقياس فهرنهايت: (درجة تجمد الماء – درجة غليان الماء – درجة انصهار الزئبق)
- **الإجابة:** **درجة تجمد الماء**
- **التفسير:** \`C = (32 − 32) / 1.8 = 0°C\`، وهي درجة تجمد الماء، أما غليانه فعند \`212°F\`.
### سؤال ١١: زمن تسخين الماء بسخان كهربائي
- **السؤال:** سخان كهربائي صغير قدرته \`200 W\` غُمر في وعاء يحتوي على \`100 g\` من الماء لتحضير القهوة السريعة، فإن الزمن اللازم لتسخين هذه الكمية من الماء من درجة حرارة ابتدائية \`23°C\` وصولًا إلى درجة حرارة الغليان، إذا كانت الحرارة النوعية للماء \`4187 J/kg·K\`، يساوي: (\`161.2 s\` – \`120 s\` – \`50 s\`)
- **المعطيات:** \`P = 200 W = 200 J/s\` · \`m = 100 g = 100 ÷ 1000 = 0.1 kg\` · \`T₁ = 23°C\` · \`T₂ = 100°C\` (درجة غليان الماء) · \`c = 4187 J/kg·K\`
- **المطلوب:** الزمن \`t\`.
- **لماذا هذان القانونان؟** القدرة \`P\` هي الطاقة التي يعطيها السخان في كل ثانية، فالطاقة الكلية بعد زمن \`t\` هي \`E = P·t\`. وبافتراض أن كل هذه الطاقة يمتصها الماء، فهي تساوي الحرارة اللازمة لرفع درجة حرارته \`Q = m·c·ΔT\`.
- **القانون:** \`P·t = m·c·ΔT\` ← \`t = m·c·ΔT / P\`
- **الحل:** التغير في درجة الحرارة: \`ΔT = 100 − 23 = 77°C\` (التغير بالكلفن يساوي التغير بالمئوي، لذلك تصلح الوحدة \`J/kg·K\`)
- **الحل (البسط):** \`Q = 0.1 × 4187 × 77 = 418.7 × 77 = 32239.9 J\`
- **الحل (المقام):** \`P = 200 W\`
- **الحل:** \`t = 32239.9 / 200 = 161.2 s\`
- **النتيجة:** **\`t ≈ 161.2 s\`** (أي نحو دقيقتين و41 ثانية) ✓
### سؤال ١٢: اتجاه انتقال الحرارة تلقائيًا
- **العبارة:** الحرارة تنتقل تلقائيًا من الجسم البارد إلى الجسم الساخن.
- **الإجابة:** **خطأ**
- **التصحيح:** الحرارة تنتقل تلقائيًا من الجسم **الساخن** إلى الجسم **البارد** حتى يصلا إلى الاتزان الحراري.
### سؤال ١٣: الفرق بين كمية الحرارة ودرجة الحرارة
- **العبارة:** كمية الحرارة هي نفسها درجة الحرارة.
- **الإجابة:** **خطأ**
- **التصحيح:** كمية الحرارة طاقة منتقلة تقاس بالجول \`J\`، أما درجة الحرارة فمقياس لمتوسط طاقة حركة الجزيئات وتقاس بـ \`°C\` أو \`K\` أو \`°F\`.
### سؤال ١٤: المنطاد الهوائي وتيارات الحمل
- **العبارة:** المنطاد الهوائي من أمثلة نقل الحرارة بواسطة تيارات الحمل.
- **الإجابة:** **صح**
- **التفسير:** الهواء داخل المنطاد يُسخَّن فيتمدد وتقل كثافته فيرتفع، وهذا هو مبدأ تيارات الحمل.
### سؤال ١٥: الضوء الأصفر والحمل الحراري
- **العبارة:** يعتبر الضوء الأصفر مثالًا على الحمل الحراري.
- **الإجابة:** **خطأ**
- **التصحيح:** الضوء موجات كهرومغناطيسية، فهو مثال على **الإشعاع** الحراري لا الحمل.
### سؤال ١٦: النقطتان الثابتتان على المقياس المئوي
- **العبارة:** النقطتان الثابتتان على المقياس المئوي هما الصفر و \`100\`.
- **الإجابة:** **صح**
- **التفسير:** \`0°C\` درجة تجمد الماء و \`100°C\` درجة غليانه عند الضغط الجوي المعتاد.
### سؤال ١٧: الحالة التي يصل إليها خليط من الماء
- **العبارة:** تسمى الحالة الفيزيائية التي يصل إليها خليط من الماء (ساخن وبارد) الاتزان.
- **الإجابة:** **صح**
- **التفسير:** يفقد الماء الساخن حرارة ويكتسبها البارد حتى تتساوى درجتا حرارتهما، وتسمى هذه الحالة **الاتزان الحراري**.
### سؤال ١٨: تحول الثلج إلى ماء
- **العبارة:** اسم العملية التي يتحول من خلالها الثلج إلى ماء هي الانصهار.
- **الإجابة:** **صح**
- **التفسير:** تحول المادة من الحالة الصلبة إلى السائلة يسمى انصهارًا، ويحتاج إلى الحرارة الكامنة للانصهار \`Q = m·H\`.
### سؤال ١٩: الماء سائل مثالي للتبريد والتسخين
- **العبارة:** يعتبر الماء سائلًا مثاليًا للتبريد والتسخين.
- **الإجابة:** **صح**
- **التفسير:** حرارته النوعية كبيرة \`c ≈ 4180 J/kg·°C\`، فيمتص كمية كبيرة من الحرارة أو يطلقها مع تغير صغير في درجة حرارته، لذلك يُستخدم في مشعات السيارات وقِرَب الماء الساخن.
`,
ex:{q:`سخان \`200 W\` يسخن \`100 g\` ماء من \`23°C\` حتى الغليان (\`c = 4187\`). ما الزمن اللازم؟`,
st:[`\`ΔT = 100 − 23 = 77°C\``,`\`Q = 0.1 × 4187 × 77 ≈ 32240 J\``,`\`t = Q/P = 32240/200 ≈ 161.2 s\``],
a:`\`t ≈ 161 s\` (حوالي دقيقتين و 41 ثانية)`},
qz:[
{q:`انتقال الحرارة خلال مادة ما (صلبة) بالتلامس:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`التبخر`],a:0,w:`التوصيل.`},
{q:`المبدأ الذي يقوم عليه الترمومتر الزئبقي:`,o:[`تغير كتلة السائل`,`تمدد السائل بالحرارة`,`تمدد الغازات`,`تغير لون الزئبق`],a:1,w:`يتمدد الزئبق فيرتفع في الأنبوب.`},
{q:`النقطتان الثابتتان على المقياس المئوي:`,o:[`0 و 100`,`32 و 212`,`273 و 373`,`−40 و 40`],a:0,w:`تجمد الماء وغليانه.`},
{q:`تنتقل الحرارة تلقائيًا:`,o:[`من الجسم البارد إلى الساخن`,`من الجسم الساخن إلى البارد`,`من الجسم الأكبر كتلة إلى الأصغر`,`لا تنتقل إلا بوجود مضخة`],a:1,w:`من الدرجة الأعلى إلى الأقل حتى الاتزان.`},
{q:`الضوء الأصفر من مصباح مثال على انتقال الطاقة بـ:`,o:[`التوصيل`,`الحمل`,`الإشعاع`,`الانصهار`],a:2,w:`الضوء موجات كهرومغناطيسية، أي إشعاع.`},
{q:`\`42°C\` بالفهرنهايت:`,o:[`107.6°F`,`117°F`,`95°F`,`75.6°F`],a:0,w:`1.8 × 42 + 32 = 107.6°F.`},
{q:`\`300 K\` بالفهرنهايت تقريبًا:`,o:[`80.6°F`,`86°F`,`572°F`,`27°F`],a:0,w:`300 − 273 = 27°C ← 1.8 × 27 + 32 = 80.6°F.`}
]}
];
window.STUDY=window.STUDY||[];
window.STUDY[3]=[
/* 3-0 مقدمة */
{s:`### ما الكهرباء الساكنة؟
- شحنات كهربائية **مستقرة** على الأجسام (لا تتحرك في دائرة)، بعكس الكهرباء التيارية.
### المفاهيم الأساسية في الوحدة
- **الشحنة الكهربائية:** طبيعتها وأنواعها وكيف تنتقل.
- **القوة الكهروستاتيكية:** قانون كولوم.
- **المجال الكهربائي:** شدته وخطوطه.
- **الجهد الكهربائي** وفرق الجهد.
- **المكثفات:** السعة، التوصيل، الطاقة المختزنة.
### وحدات مهمة
- الشحنة: الكولوم \`C\` · القوة: \`N\` · المجال: \`N/C\` · الجهد: الفولت \`V\` · السعة: الفاراد \`F\``,
ex:{q:`حدّد وحدة كل كمية: الشحنة، المجال الكهربائي، الجهد، السعة.`,
st:[`الشحنة ← كولوم \`C\``,`المجال = قوة ÷ شحنة ← \`N/C\``,`الجهد = طاقة ÷ شحنة ← \`J/C = V\` (فولت)`,`السعة = شحنة ÷ جهد ← \`C/V = F\` (فاراد)`],
a:`\`C\`، \`N/C\`، \`V\`، \`F\``},
qz:[
{q:`تقاس الشحنة الكهربائية بوحدة:`,o:[`الكولوم`,`الفولت`,`الأمبير`,`الجول`],a:0,w:`الكولوم C.`},
{q:`وحدة السعة الكهربائية:`,o:[`الكولوم`,`الفاراد`,`الأوم`,`الفولت`],a:1,w:`F = C/V.`},
{q:`الكهرباء الساكنة تعني أن الشحنات:`,o:[`تتحرك في سلك`,`مستقرة على الأجسام`,`غير موجودة`,`تتحرك بسرعة الضوء`],a:1,w:`بعكس الكهرباء التيارية.`},
{q:`وحدة شدة المجال الكهربائي:`,o:[`N/C`,`C/N`,`J`,`A`],a:0,w:`E = F/q.`}
]},
/* 3-1 الشحنات وطرق الشحن */
{s:`### الشحنة الكهربائية
- المادة متعادلة طبيعيًا: عدد البروتونات (+) = عدد الإلكترونات (−).
- تُشحن المادة عندما **تفقد** إلكترونات (تصبح موجبة) أو **تكتسب** إلكترونات (تصبح سالبة).
- الشحنات المتشابهة **تتنافر**، والمختلفة **تتجاذب**.
### المواد حسب التوصيل
- **موصلة:** إلكتروناتها حرة الحركة (الحديد، النحاس، الألمنيوم).
- **عازلة:** إلكتروناتها مقيدة (الزجاج، البلاستيك، الخشب).
- **شبه موصلة:** بين الاثنين (السيليكون، الجرمانيوم).
### الشحن بالدلك
- تنتقل إلكترونات من مادة لأخرى: دلك البلاستيك بالصوف ← البلاستيك سالب، والصوف موجب.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: ماذا يحدث عند دلك البلاستيك بالصوف
- **الموقف/السؤال:** ماذا يحدث عند دلك قطعة من البلاستيك بقطعة من الصوف؟ وما نوع الشحنة التي يكتسبها كل منهما؟
- **الفكرة الأساسية:** كل مادة في حالتها الطبيعية **متعادلة** كهربائيًا، أي أن عدد البروتونات الموجبة في أنويتها يساوي عدد الإلكترونات السالبة التي تدور حولها، فلا تظهر عليها شحنة.
- **ما الذي يتحرك؟** البروتونات مقيدة داخل النواة ولا تنتقل بالدلك، أما **الإلكترونات** الخارجية فهي الأسهل انتقالًا، لذلك الشحن بالدلك يعني دائمًا انتقال **إلكترونات** من مادة إلى أخرى.
- **التفسير:** عند الدلك يحدث تلامس واحتكاك شديد بين السطحين، والبلاستيك يمسك بالإلكترونات أقوى من الصوف، فينتقل جزء من الإلكترونات السالبة **من الصوف إلى البلاستيك**.
- **التفسير على البلاستيك:** اكتسب إلكترونات إضافية، فأصبح عدد الشحنات السالبة عليه **أكبر** من عدد الشحنات الموجبة ← يصبح **سالب الشحنة**.
- **التفسير على الصوف:** فقد بعض إلكتروناته، فأصبح عدد الشحنات الموجبة عليه **أكبر** من عدد الشحنات السالبة ← يصبح **موجب الشحنة**.
- **حفظ الشحنة:** الشحنة لم تُخلق ولم تَفنَ، بل انتقلت فقط، لذلك مقدار الشحنة السالبة التي ظهرت على البلاستيك يساوي تمامًا مقدار الشحنة الموجبة التي ظهرت على الصوف، ومجموع الشحنتين يبقى صفرًا: \`q_بلاستيك + q_صوف = 0\`
- **نتيجة عملية:** بعد الدلك يصبح الجسمان مختلفي الشحنة، فإذا قُرِّب أحدهما من الآخر **تجاذبا**، لأن الشحنات المختلفة تتجاذب.
- **النتيجة:** تنتقل الإلكترونات من الصوف إلى البلاستيك، فيصبح **البلاستيك سالب الشحنة** و**الصوف موجب الشحنة** وبالمقدار نفسه ✓
`,
ex:{q:`دلكت مسطرة بلاستيكية بقطعة صوف، ثم قربتها من قصاصات ورق صغيرة فانجذبت. فسّر ما حدث.`,
st:[`أثناء الدلك انتقلت إلكترونات من الصوف إلى البلاستيك ← المسطرة سالبة.`,`عند التقريب تُعيد المسطرة ترتيب الشحنات في الورق: تتنافر الإلكترونات بعيدًا ويقترب الطرف الموجب.`,`الطرف الموجب الأقرب ينجذب أقوى من تنافر الطرف البعيد.`],
a:`الورق ينجذب بسبب الشحن بالدلك ثم الحث على الورق.`},
qz:[
{q:`الشحنات المختلفة:`,o:[`تتنافر`,`تتجاذب`,`لا تتأثر`,`تتلاشى`],a:1,w:`الموجب يجذب السالب.`},
{q:`عند دلك البلاستيك بالصوف يصبح البلاستيك:`,o:[`موجبًا`,`سالبًا`,`متعادلًا`,`موصلًا`],a:1,w:`يكتسب إلكترونات من الصوف.`},
{q:`أي مما يلي مادة عازلة؟`,o:[`النحاس`,`الألمنيوم`,`الزجاج`,`الحديد`],a:2,w:`الزجاج لا يسمح بانتقال الشحنة بسهولة.`},
{q:`السيليكون من المواد:`,o:[`الموصلة`,`العازلة`,`شبه الموصلة`,`المغناطيسية`],a:2,w:`أساس صناعة الرقائق الإلكترونية.`},
{q:`يصبح الجسم موجب الشحنة عندما:`,o:[`يكتسب إلكترونات`,`يفقد إلكترونات`,`يكتسب بروتونات من الهواء`,`يُبرَّد`],a:1,w:`الإلكترونات هي التي تنتقل عادة.`}
]},
/* 3-2 قانون كولوم (والشحن باللمس والحث) */
{s:`### الشحن باللمس والحث
- **باللمس (التوصيل):** موصل مشحون يلامس موصلًا متعادلًا فيتقاسمان الشحنة.
- **بالحث (التأثير):** شحن جسم متعادل **دون ملامسته** بتقريب جسم مشحون منه.
### قانون كولوم
- القوة بين شحنتين نقطيتين تتناسب طرديًا مع حاصل ضرب الشحنتين، وعكسيًا مع مربع المسافة بينهما.
\`F = k·q₁·q₂ / r²\`
[[fig:coulomb]]
- \`k = 9 × 10⁹ N·m²/C²\`
- الشحنات بالكولوم: \`µC = 10⁻⁶ C\` · \`nC = 10⁻⁹ C\`
- مضاعفة المسافة ← القوة تقل إلى **الربع**.
### أمثلة محلولة على قانون كولوم
### مثال ١: حساب القوة بين شحنتين مختلفتين
- **السؤال:** شحنتان \`q₁ = 3 µC\` و \`q₂ = −5 µC\` المسافة بينهما \`0.2 m\`، أوجد القوة بينهما ونوعها.
- **المعطيات:** \`q₁ = 3 µC = 3 × 10⁻⁶ C\` · \`q₂ = 5 × 10⁻⁶ C\` · \`r = 0.2 m\`
- **المطلوب:** القوة \`F\` ونوعها.
- **القانون:** \`F = k·q₁·q₂ / r²\`
- **الحل:** التعويض (بالقيم المطلقة للشحنات): \`F = (9 × 10⁹)(3 × 10⁻⁶)(5 × 10⁻⁶) / (0.2)²\`
- **الحل:** البسط: \`9 × 10⁹ × 15 × 10⁻¹² = 0.135\`
- **الحل:** المقام: \`(0.2)² = 0.04\`
- **الحل:** \`F = 0.135 ÷ 0.04 = 3.375 N\`
- **النتيجة:** \`F = 3.375 N\` قوة **تجاذب** لأن الشحنتين مختلفتان ✓
### مثال ٢: حساب القوة بين شحنتين متشابهتين
- **السؤال:** شحنتان متساويتان كل منهما \`2 nC\` والمسافة بينهما \`3 cm\`، أوجد القوة.
- **المعطيات:** \`q₁ = q₂ = 2 nC = 2 × 10⁻⁹ C\` · \`r = 3 cm = 0.03 m\`
- **المطلوب:** القوة \`F\`
- **القانون:** \`F = k·q₁·q₂ / r²\`
- **الحل:** \`F = (9 × 10⁹)(2 × 10⁻⁹)(2 × 10⁻⁹) / (0.03)²\`
- **الحل:** البسط: \`9 × 10⁹ × 4 × 10⁻¹⁸ = 3.6 × 10⁻⁸\`
- **الحل:** المقام: \`(0.03)² = 9 × 10⁻⁴\`
- **الحل:** \`F = 3.6 × 10⁻⁸ ÷ 9 × 10⁻⁴ = 4 × 10⁻⁵ N\`
- **النتيجة:** \`F = 4 × 10⁻⁵ N\` قوة **تنافر** لأن الشحنتين متشابهتان ✓
### مثال ٣: حساب المسافة بين شحنتين
- **السؤال:** شحنتان كل منهما \`1 µC\` والقوة بينهما \`0.9 N\`، أوجد المسافة بينهما.
- **المعطيات:** \`q₁ = q₂ = 1 × 10⁻⁶ C\` · \`F = 0.9 N\`
- **المطلوب:** المسافة \`r\`
- **القانون:** \`r = √(k·q₁·q₂ / F)\`
- **الحل:** \`r² = (9 × 10⁹)(1 × 10⁻⁶)(1 × 10⁻⁶) / 0.9\`
- **الحل:** \`r² = 9 × 10⁻³ ÷ 0.9 = 0.01 m²\`
- **الحل:** \`r = √0.01 = 0.1 m\`
- **النتيجة:** \`r = 0.1 m = 10 cm\` ✓
### مثال ٤: حساب مقدار الشحنة
- **السؤال:** شحنتان متساويتان المسافة بينهما \`0.3 m\` والقوة بينهما \`0.4 N\`، أوجد مقدار كل شحنة.
- **المعطيات:** \`q₁ = q₂ = q\` · \`r = 0.3 m\` · \`F = 0.4 N\`
- **المطلوب:** الشحنة \`q\`
- **القانون:** \`q = √(F·r² / k)\`
- **الحل:** \`q² = (0.4)(0.3)² / (9 × 10⁹)\`
- **الحل:** \`q² = 0.036 ÷ 9 × 10⁹ = 4 × 10⁻¹² C²\`
- **الحل:** \`q = √(4 × 10⁻¹²) = 2 × 10⁻⁶ C\`
- **النتيجة:** \`q = 2 µC\` ✓
### مثال ٥: أثر تغيير المسافة والشحنات على القوة
- **السؤال:** ماذا يحدث للقوة إذا قلّت المسافة إلى النصف؟ وإذا تضاعفت الشحنتان معًا؟
- **القانون:** القوة تتناسب عكسيًا مع مربع المسافة: \`F ∝ 1/r²\`، وطرديًا مع حاصل ضرب الشحنتين: \`F ∝ q₁·q₂\`
- **الحل:** المسافة إلى النصف: \`F₂ = F ÷ (½)² = 4F\`
- **الحل:** مضاعفة الشحنتين معًا: \`F₂ = (2)(2)F = 4F\`
- **النتيجة:** في الحالتين تصبح القوة **أربعة أضعاف** ✓
### مثال على ثلاث شحنات على خط واحد
- **الطريقة:** نحسب قوة كل شحنة على الشحنة المطلوبة وحدها، ونحدد اتجاهها (تجاذب أو تنافر)، ثم نجمع القوتين إذا كانتا في الاتجاه نفسه، ونطرحهما إذا كانتا متعاكستين.
### مثال ٦: القوة المؤثرة على الشحنة الوسطى
[[fig:c3a]]
- **السؤال:** ثلاث شحنات على خط واحد: \`q₁ = 4 µC\` ثم \`q₂ = −5 µC\` ثم \`q₃ = 6 µC\`، المسافة بين q₁ و q₂ تساوي \`2 m\` وبين q₂ و q₃ تساوي \`4 m\`. أوجد القوة المؤثرة على q₂.
- **المعطيات:** \`q₁ = 4 × 10⁻⁶ C\` · \`q₂ = 5 × 10⁻⁶ C\` · \`q₃ = 6 × 10⁻⁶ C\` · \`r₁₂ = 2 m\` · \`r₂₃ = 4 m\`
- **المطلوب:** القوة المحصلة على q₂.
- **القانون:** \`F = k·q₁·q₂ / r²\`
- **الحل:** قوة q₁ على q₂: \`F₁ = (9 × 10⁹)(4 × 10⁻⁶)(5 × 10⁻⁶) / (2)² = 0.045 N\`
- **الحل:** قوة q₃ على q₂: \`F₃ = (9 × 10⁹)(6 × 10⁻⁶)(5 × 10⁻⁶) / (4)² ≈ 0.017 N\`
- **تحديد اتجاه القوى لكل شحنتين:** ندرس كل زوج من الشحنات وحده، وننظر فقط إلى القوة الواقعة على الشحنة المطلوبة q₂.
- **الزوج الأول q₁ و q₂:** q₁ موجبة و q₂ سالبة، أي مختلفتان، فبينهما **تجاذب**. كل شحنة تسحب الأخرى نحوها، فالقوة F₁ على q₂ تتجه **نحو q₁**، أي **نحو اليسار**.
[[fig:c3p12]]
- **الزوج الثاني q₃ و q₂:** q₃ موجبة و q₂ سالبة، أي مختلفتان، فبينهما **تجاذب**. q₃ تسحب q₂ نحوها، فالقوة F₃ على q₂ تتجه **نحو q₃**، أي **نحو اليمين**.
[[fig:c3p32]]
- **قاعدة سريعة:** في التجاذب يتجه السهم على الشحنة **نحو** الشحنة الأخرى، وفي التنافر يتجه **بعيدًا** عنها.
- **مقارنة الاتجاهين:** F₁ نحو اليسار و F₃ نحو اليمين، أي أنهما **متعاكستان** على خط واحد، لذلك نطرح الصغرى من الكبرى (ولو كانتا في الاتجاه نفسه لجمعناهما).
- **الحل:** \`F_total = F₁ − F₃ = 0.045 − 0.017 = 0.028 N\`
- **تحديد اتجاه المحصلة:** المحصلة تكون دائمًا في اتجاه **القوة الأكبر**، وبما أن \`F₁ = 0.045 N\` أكبر من \`F₃ = 0.017 N\` فالمحصلة في اتجاه F₁، أي نحو اليسار باتجاه q₁.
- **النتيجة:** \`F_total ≈ 0.028 N\` نحو اليسار (باتجاه q₁) ✓
### أمثلة الحقيبة محلولة بالتفصيل
### مثال من الحقيبة: القوة الكهربائية بين شحنتين موجبتين
- **السؤال:** شحنتان \`q₁ = 2 × 10⁻⁶ C\` و \`q₂ = 3 × 10⁻⁶ C\` والمسافة بينهما \`1.5 m\`، أوجد القوة الكهربائية بينهما.
- **المعطيات:** \`q₁ = 2 × 10⁻⁶ C\` (أي \`2 µC\`) · \`q₂ = 3 × 10⁻⁶ C\` (أي \`3 µC\`) · \`r = 1.5 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **ملاحظة على الوحدات:** الشحنتان معطاتان أصلًا بالكولوم والمسافة بالمتر، وهي وحدات النظام الدولي التي يُبنى عليها الثابت k، لذلك لا نحتاج أي تحويل.
- **المطلوب:** مقدار القوة الكهربائية \`F\` ونوعها (تجاذب أم تنافر).
- **لماذا قانون كولوم؟** لدينا شحنتان نقطيتان معلومتا المقدار وتفصل بينهما مسافة معلومة، وقانون كولوم هو القانون الذي يربط القوة الكهربائية بين شحنتين بمقداريهما وبالمسافة بينهما.
- **القانون:** \`F = k·q₁·q₂ / r²\`
- **معنى الرموز:** \`F\` القوة الكهروستاتيكية بالنيوتن \`N\` · \`k\` ثابت كولوم ويساوي \`9 × 10⁹ N·m²/C²\` · \`q₁\` و \`q₂\` مقدارا الشحنتين بالكولوم \`C\` · \`r\` المسافة بين مركزي الشحنتين بالمتر \`m\`
- **فهم القانون:** القوة تزيد كلما زاد حاصل ضرب الشحنتين (علاقة طردية)، وتقل بسرعة كلما زادت المسافة لأن المسافة **مربعة** في المقام (علاقة عكسية مع مربع المسافة).
- **الحل:** التعويض: \`F = (9 × 10⁹)(2 × 10⁻⁶)(3 × 10⁻⁶) / (1.5)²\`
- **الحل:** البسط: نضرب الأعداد معًا \`9 × 2 × 3 = 54\`، ونجمع الأسس \`10⁹ × 10⁻⁶ × 10⁻⁶ = 10⁻³\`، فيكون البسط \`54 × 10⁻³ = 0.054 N·m²\`
- **الحل:** المقام: \`(1.5)² = 1.5 × 1.5 = 2.25 m²\`
- **الحل:** القسمة: \`F = 0.054 ÷ 2.25 = 0.024 N\`
- **التحقق من الوحدة:** \`(N·m²/C²)(C)(C) / m² = N\`، أي أن الناتج قوة بالنيوتن كما يجب.
- **تحديد نوع القوة:** الشحنتان كلتاهما **موجبتان** أي متشابهتان، والشحنات المتشابهة **تتنافر**، فكل شحنة تدفع الأخرى بعيدًا عنها على الخط الواصل بينهما.
- **تحديد الاتجاه:** القوة على q₂ تتجه **بعيدًا عن q₁**، والقوة على q₁ تتجه **بعيدًا عن q₂**، والقوتان متساويتان في المقدار \`0.024 N\` ومتعاكستان في الاتجاه (قانون نيوتن الثالث).
- **النتيجة:** \`F = 0.024 N\` قوة **تنافر** ✓
### ملخص القوانين
- القوة: \`F = k·q₁·q₂ / r²\`
- المسافة: \`r = √(k·q₁·q₂ / F)\`
- الشحنة (لشحنتين متساويتين): \`q = √(F·r² / k)\`
- الثابت: \`k = 9 × 10⁹ N·m²/C²\`
- التحويلات: \`1 µC = 10⁻⁶ C\` · \`1 nC = 10⁻⁹ C\` · \`1 cm = 10⁻² m\`
- الشحنات المتشابهة **تتنافر**، والمختلفة **تتجاذب**.
- لثلاث شحنات: القوتان في الاتجاه نفسه \`F_total = F₁ + F₂\`، ومتعاكستان \`F_total = F₁ − F₂\`.`,
ex:{q:`شحنتان \`q₁ = 4 µC\` و \`q₂ = 2 µC\` المسافة بينهما \`0.3 m\`. أوجد القوة الكهربائية.`,
st:[`\`F = (9 × 10⁹)(4 × 10⁻⁶)(2 × 10⁻⁶) / (0.3)²\``,`البسط: \`9 × 10⁹ × 8 × 10⁻¹² = 0.072\``,`المقام: \`0.09\``,`\`F = 0.072 / 0.09 = 0.8 N\` (تنافر لأنهما موجبتان)`],
a:`\`F = 0.8 N\` تنافر`},
qz:[
{q:`شحنتان \`2 µC\` و \`3 µC\` بينهما \`1.5 m\`، القوة:`,o:[`0.024 N`,`0.036 N`,`0.24 N`,`24 N`],a:0,w:`9×10⁹ × 6×10⁻¹² / 2.25 = 0.054/2.25 = 0.024 N.`},
{q:`إذا تضاعفت المسافة بين شحنتين فإن القوة:`,o:[`تتضاعف`,`تقل للنصف`,`تقل للربع`,`تبقى ثابتة`],a:2,w:`F ∝ 1/r² ← 1/2² = 1/4.`},
{q:`شحن جسم متعادل دون ملامسته يسمى الشحن بـ:`,o:[`الدلك`,`اللمس`,`الحث`,`التسخين`],a:2,w:`الحث (التأثير).`},
{q:`قيمة ثابت كولوم k:`,o:[`9 × 10⁹ N·m²/C²`,`8.85 × 10⁻¹²`,`1.6 × 10⁻¹⁹`,`6.67 × 10⁻¹¹`],a:0,w:`k = 9 × 10⁹.`}
]},
/* 3-3 المجال الكهربائي وخطوطه */
{s:`### المجال الكهربائي
- المنطقة المحيطة بالشحنة التي يظهر فيها تأثيرها.
- **شدته:** القوة المؤثرة على وحدة الشحنات الموجبة (شحنة اختبار).
- \`E = F / q\` · ومن شحنة نقطية: \`E = k·q / r²\` · الوحدة \`N/C\`
### خصائص خطوط المجال
- تخرج من الشحنة **الموجبة** وتدخل في **السالبة**.
- لا تتقاطع أبدًا.
- متقاربة حيث المجال قوي، ومتباعدة حيث المجال ضعيف.
### أنواع المجال
- **منتظم:** ثابت الشدة والاتجاه (بين لوحي مكثف).
- **غير منتظم:** يتغير مقداره أو اتجاهه (حول شحنة نقطية).
### القوة على شحنات متعددة
- احسب كل قوة على حدة بقانون كولوم، ثم اجمعها مع مراعاة الاتجاهات.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: شدة المجال على بعد من شحنة نقطية
- **السؤال:** أوجد شدة المجال الكهربائي على بعد \`0.3 m\` من شحنة كهربائية \`q = 5 × 10⁻⁹ C\`.
- **المعطيات:** \`q = 5 × 10⁻⁹ C\` (أي \`5 nC\`) · \`r = 0.3 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **ملاحظة على الوحدات:** الشحنة بالكولوم والمسافة بالمتر، فلا حاجة لتحويل.
- **المطلوب:** شدة المجال الكهربائي \`E\` عند تلك النقطة.
- **لماذا هذا القانون؟** المجال هنا ناشئ عن **شحنة نقطية واحدة** ولا توجد شحنة اختبار ولا قوة معطاة، لذلك نستخدم قانون المجال الناشئ عن شحنة نقطية، وهو مشتق من قانون كولوم بقسمة القوة على شحنة الاختبار.
- **القانون:** \`E = k·q / r²\`
- **معنى الرموز:** \`E\` شدة المجال الكهربائي بوحدة \`N/C\` · \`k\` ثابت كولوم · \`q\` الشحنة المولّدة للمجال بالكولوم · \`r\` بعد النقطة عن الشحنة بالمتر
- **الحل:** التعويض: \`E = (9 × 10⁹)(5 × 10⁻⁹) / (0.3)²\`
- **الحل:** البسط: \`9 × 5 = 45\` و \`10⁹ × 10⁻⁹ = 10⁰ = 1\`، فالبسط \`45 N·m²/C\`
- **الحل:** المقام: \`(0.3)² = 0.09 m²\`
- **الحل:** القسمة: \`E = 45 ÷ 0.09 = 500 N/C\`
- **تحديد الاتجاه:** الشحنة **موجبة**، وخطوط المجال تخرج من الشحنة الموجبة، لذلك يتجه المجال عند النقطة **بعيدًا عن الشحنة** على الخط الواصل بينها وبين النقطة.
- **معنى الناتج:** لو وُضعت شحنة مقدارها \`1 C\` عند هذه النقطة لأثرت فيها قوة مقدارها \`500 N\`.
- **النتيجة:** \`E = 500 N/C\` باتجاه بعيد عن الشحنة ✓
### مثال ٢: المجال من القوة المؤثرة على شحنة
- **السؤال:** شحنة كهربائية \`2 × 10⁻⁹ C\` وُضعت عند نقطة في مجال كهربائي فتأثرت بقوة \`4 × 10⁻⁶ N\`، ما مقدار المجال الكهربائي في تلك النقطة؟
- **المعطيات:** \`q = 2 × 10⁻⁹ C\` (شحنة الاختبار) · \`F = 4 × 10⁻⁶ N\`
- **المطلوب:** شدة المجال \`E\` عند النقطة.
- **لماذا هذا القانون؟** هنا لا نعرف الشحنة التي تولّد المجال ولا بعدها، لكننا نعرف **القوة** التي أثّر بها المجال على شحنة موضوعة فيه، فنستخدم **تعريف** شدة المجال: القوة المؤثرة على وحدة الشحنات.
- **القانون:** \`E = F / q\`
- **معنى الرموز:** \`E\` شدة المجال بوحدة \`N/C\` · \`F\` القوة الكهربائية المؤثرة على الشحنة بالنيوتن · \`q\` شحنة الاختبار الموضوعة في المجال بالكولوم
- **الحل:** التعويض: \`E = (4 × 10⁻⁶) / (2 × 10⁻⁹)\`
- **الحل:** نقسم الأعداد: \`4 ÷ 2 = 2\`
- **الحل:** نقسم قوى العشرة بطرح الأسس: \`10⁻⁶ ÷ 10⁻⁹ = 10⁻⁶⁺⁹ = 10³\`
- **الحل:** \`E = 2 × 10³ N/C = 2000 N/C\`
- **ملاحظة مهمة:** قيمة المجال صفة للنقطة نفسها، فلو وضعنا شحنة أكبر لزادت القوة بالنسبة نفسها وبقي ناتج القسمة \`E\` ثابتًا.
- **النتيجة:** \`E = 2 × 10³ N/C\` ✓
`,
ex:{q:`أوجد شدة المجال على بعد \`0.2 m\` من شحنة \`8 nC\`.`,
st:[`\`E = k·q / r²\``,`\`E = (9 × 10⁹)(8 × 10⁻⁹) / (0.2)²\``,`\`E = 72 / 0.04 = 1800 N/C\``],
a:`\`E = 1800 N/C\``},
qz:[
{q:`خطوط المجال الكهربائي تخرج من:`,o:[`الشحنة السالبة`,`الشحنة الموجبة`,`كلتيهما`,`لا تخرج`],a:1,w:`وتدخل في السالبة.`},
{q:`أي العبارات صحيحة عن خطوط المجال الكهربائي؟`,o:[`تتقاطع عند الشحنات القوية`,`لا تتقاطع أبدًا`,`تتقاطع في المجال المنتظم`,`تخرج من الشحنة السالبة`],a:1,w:`لا تتقاطع، لأن للمجال اتجاهًا واحدًا في كل نقطة.`},
{q:`شحنة \`2 nC\` تأثرت بقوة \`4 × 10⁻⁶ N\`، شدة المجال:`,o:[`2000 N/C`,`8 × 10⁻¹⁵ N/C`,`500 N/C`,`0.5 N/C`],a:0,w:`E = 4×10⁻⁶ / 2×10⁻⁹ = 2×10³ N/C.`},
{q:`شدة المجال على بعد \`0.3 m\` من شحنة \`5 nC\`:`,o:[`150 N/C`,`500 N/C`,`1500 N/C`,`45 N/C`],a:1,w:`9×10⁹ × 5×10⁻⁹ / 0.09 = 45/0.09 = 500 N/C.`},
{q:`المجال المنتظم:`,o:[`ثابت الشدة ومتغير الاتجاه`,`ثابت الشدة والاتجاه`,`متغير الشدة ثابت الاتجاه`,`صفر دائمًا`],a:1,w:`مثل المجال بين لوحي مكثف.`}
]},
/* 3-4 الجهد الكهربائي */
{s:`### الجهد الكهربائي V
- طاقة الوضع الكهربائية لكل وحدة شحنة. الوحدة: الفولت \`V = J/C\`.
### فرق الجهد بين نقطتين
- التغير في طاقة الوضع لكل وحدة شحنة، أو الشغل اللازم لنقل شحنة اختبار ÷ الشحنة:
\`ΔV = W / q\`
### قوانين مهمة
- جهد نقطة على بعد r من شحنة نقطية: \`V = k·q / r\`
- فرق الجهد في مجال منتظم: \`ΔV = E·d\`
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: فرق الجهد في مجال منتظم
- **السؤال:** أوجد فرق الجهد بين نقطتين في مجال كهربائي منتظم شدته \`10000 N/C\` والمسافة الفاصلة بينهما \`0.01 m\`.
- **المعطيات:** \`E = 10000 N/C = 1 × 10⁴ N/C\` · \`d = 0.01 m = 1 × 10⁻² m\` (أي \`1 cm\`)
- **المطلوب:** فرق الجهد \`ΔV\` بين النقطتين.
- **لماذا هذا القانون؟** المجال **منتظم** أي ثابت المقدار والاتجاه في كل النقاط، وفي هذه الحالة فقط يكون فرق الجهد بين نقطتين على امتداد خطوط المجال هو حاصل ضرب شدة المجال في المسافة بينهما.
- **القانون:** \`ΔV = E·d\`
- **معنى الرموز:** \`ΔV\` فرق الجهد بالفولت \`V\` · \`E\` شدة المجال المنتظم بوحدة \`N/C\` (وتكافئ \`V/m\`) · \`d\` المسافة بين النقطتين باتجاه خطوط المجال بالمتر
- **الحل:** التعويض: \`ΔV = (10000)(0.01)\`
- **الحل:** \`ΔV = 1 × 10⁴ × 1 × 10⁻² = 1 × 10² = 100 V\`
- **التحقق من الوحدة:** \`(N/C)(m) = N·m/C = J/C = V\`
- **معنى الناتج:** لنقل شحنة مقدارها \`1 C\` بين النقطتين يلزم شغل مقداره \`100 J\`.
- **النتيجة:** \`ΔV = 100 V\` ✓
### مثال ٢: الجهد على بعد من شحنة نقطية
- **السؤال:** أوجد الجهد على بعد \`0.1 m\` من شحنة نقطية \`2 × 10⁻⁶ C\`.
- **المعطيات:** \`q = 2 × 10⁻⁶ C\` (أي \`2 µC\`) · \`r = 0.1 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **المطلوب:** الجهد الكهربائي \`V\` عند النقطة.
- **لماذا هذا القانون؟** المطلوب جهد نقطة تقع في مجال **شحنة نقطية**، والمجال حولها غير منتظم فلا يصلح \`ΔV = E·d\`، بل نستخدم قانون جهد الشحنة النقطية.
- **القانون:** \`V = k·q / r\`
- **معنى الرموز:** \`V\` الجهد بالفولت · \`k\` ثابت كولوم · \`q\` الشحنة المولدة للمجال بالكولوم (مع إشارتها) · \`r\` بعد النقطة عن الشحنة بالمتر
- **انتبه للفرق:** في قانون الجهد تكون المسافة \`r\` **غير مربعة**، بخلاف قانوني القوة والمجال اللذين فيهما \`r²\`.
- **الحل:** التعويض: \`V = (9 × 10⁹)(2 × 10⁻⁶) / 0.1\`
- **الحل:** البسط: \`9 × 2 = 18\` و \`10⁹ × 10⁻⁶ = 10³\`، فالبسط \`18 × 10³ = 18000\`
- **الحل:** القسمة على المقام: \`V = 18000 ÷ 0.1 = 180000 V\`
- **الحل:** بالصيغة العلمية: \`V = 1.8 × 10⁵ V\`
- **إشارة الجهد:** الشحنة موجبة، لذلك الجهد عند النقطة **موجب**.
- **النتيجة:** \`V = 1.8 × 10⁵ V\` ✓
`,
ex:{q:`(أ) أوجد الجهد على بعد \`0.15 m\` من شحنة \`3 µC\`. (ب) أوجد فرق الجهد بين نقطتين تبعدان \`0.04 m\` في مجال منتظم \`500 N/C\`.`,
st:[`(أ) \`V = (9 × 10⁹)(3 × 10⁻⁶) / 0.15\``,`\`V = 27000 / 0.15 = 1.8 × 10⁵ V\``,`(ب) \`ΔV = E·d = 500 × 0.04 = 20 V\``],
a:`(أ) \`1.8 × 10⁵ V\` (ب) \`20 V\``},
qz:[
{q:`فرق الجهد في مجال منتظم \`10000 N/C\` لمسافة \`0.01 m\`:`,o:[`100 V`,`1000 V`,`10 V`,`10⁶ V`],a:0,w:`10000 × 0.01 = 100 V.`},
{q:`الجهد على بعد \`0.1 m\` من شحنة \`2 µC\`:`,o:[`1.8 × 10⁵ V`,`1.8 × 10⁶ V`,`1.8 × 10⁴ V`,`18 V`],a:0,w:`9×10⁹ × 2×10⁻⁶ / 0.1 = 18000/0.1 = 1.8×10⁵ V.`},
{q:`الفولت يساوي:`,o:[`J/C`,`C/J`,`N/C`,`J·C`],a:0,w:`الجهد طاقة لكل وحدة شحنة.`},
{q:`شغل \`6 J\` لنقل شحنة \`2 C\` بين نقطتين، فرق الجهد:`,o:[`12 V`,`3 V`,`8 V`,`4 V`],a:1,w:`ΔV = W/q = 6/2 = 3 V.`}
]},
/* 3-5 السعة والمكثفات */
{s:`### السعة الكهربائية C
- النسبة الثابتة بين شحنة المكثف وفرق الجهد بين لوحيه (الشحنة اللازمة لرفع الجهد 1 فولت).
- \`C = q / V\` ← \`q = C·V\` · الوحدة الفاراد \`F\` (ومنه µF و pF).
### المكثف ذو اللوحين المتوازيين
\`C = ε₀·A / d\` حيث \`ε₀ = 8.85 × 10⁻¹² F/m\`
- المجال بين اللوحين منتظم: \`V = E·d\`
### العوامل المؤثرة على السعة
- **مساحة اللوحين** (طرديًا) · **المسافة بينهما** (عكسيًا) · **الوسط العازل**.
### فوائد المكثفات
- تخزين الطاقة الكهربائية، إنتاج مجال كهربائي محدد، توليد الذبذبات وإزالة التشويش في الأجهزة اللاسلكية.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: حساب سعة مكثف من شحنته وجهده
- **السؤال:** أوجد السعة الكهربائية لمكثف يحمل شحنة \`4.5 × 10⁻⁴ C\` وفرق الجهد بين لوحيه \`150 V\`.
- **المعطيات:** \`q = 4.5 × 10⁻⁴ C\` · \`V = 150 V\`
- **المطلوب:** سعة المكثف \`C\`.
- **لماذا هذا القانون؟** السعة بتعريفها هي النسبة الثابتة بين الشحنة المختزنة على أحد لوحي المكثف وفرق الجهد بين لوحيه، ولدينا الشحنة والجهد مباشرة.
- **القانون:** \`C = q / V\`
- **معنى الرموز:** \`C\` السعة بالفاراد \`F\` · \`q\` الشحنة على أحد اللوحين بالكولوم · \`V\` فرق الجهد بين اللوحين بالفولت
- **الحل:** التعويض: \`C = (4.5 × 10⁻⁴) / 150\`
- **الحل:** نكتب المقام بالصيغة العلمية: \`150 = 1.5 × 10²\`
- **الحل:** نقسم الأعداد: \`4.5 ÷ 1.5 = 3\`، ونطرح الأسس: \`10⁻⁴ ÷ 10² = 10⁻⁶\`
- **الحل:** \`C = 3 × 10⁻⁶ F\`
- **التحويل لوحدة أنسب:** بما أن \`1 µF = 10⁻⁶ F\` فإن \`C = 3 µF\`
- **النتيجة:** \`C = 3 × 10⁻⁶ F = 3 µF\` ✓
### مثال ٢: حساب الشحنة المختزنة في مكثف
- **السؤال:** مكثف سعته \`27 × 10⁻⁶ F\` وفرق الجهد بين لوحيه \`45 V\`، أوجد الشحنة.
- **المعطيات:** \`C = 27 × 10⁻⁶ F\` (أي \`27 µF\`) · \`V = 45 V\`
- **المطلوب:** الشحنة \`q\`.
- **لماذا هذا القانون؟** نعيد ترتيب تعريف السعة \`C = q / V\` بضرب الطرفين في \`V\` لنحصل على الشحنة.
- **القانون:** \`q = C·V\`
- **معنى الرموز:** \`q\` الشحنة بالكولوم · \`C\` السعة بالفاراد · \`V\` فرق الجهد بالفولت
- **الحل:** التعويض: \`q = (27 × 10⁻⁶)(45)\`
- **الحل:** نضرب الأعداد: \`27 × 45 = 1215\`
- **الحل:** \`q = 1215 × 10⁻⁶ C\`
- **الحل:** بالصيغة العلمية: \`q = 1.215 × 10⁻³ C\`
- **التحقق من الوحدة:** \`F × V = (C/V) × V = C\`
- **النتيجة:** \`q = 1.215 × 10⁻³ C\` (أي \`1.215 mC\`) ✓
### مثال ٣: مكثف متوازي اللوحين سعته وشحنته ومجاله
- **السؤال:** مكثف متوازي اللوحين، المسافة بين لوحيه \`5 × 10⁻³ m\`، ومساحة سطح كل من لوحيه \`2 m²\`، وفرق الجهد بينهما \`10⁻⁴ V\`. أوجد: سعة المكثف، والشحنة على كل لوح، وشدة المجال الكهربائي بين لوحيه.
- **المعطيات:** \`d = 5 × 10⁻³ m\` (أي \`5 mm\`) · \`A = 2 m²\` · \`V = 1 × 10⁻⁴ V\` · \`ε₀ = 8.85 × 10⁻¹² F/m\`
- **المطلوب:** السعة \`C\` · الشحنة \`q\` · المجال \`E\`
- **أولًا لماذا هذا القانون للسعة؟** لا نعرف الشحنة بعد، لكننا نعرف **أبعاد** المكثف، وسعة المكثف متوازي اللوحين تتحدد بأبعاده الهندسية والوسط العازل بينهما.
- **القانون:** \`C = ε₀·A / d\`
- **معنى الرموز:** \`ε₀\` سماحية الفراغ وتساوي \`8.85 × 10⁻¹² F/m\` · \`A\` مساحة اللوح الواحد بوحدة \`m²\` · \`d\` المسافة بين اللوحين بالمتر
- **الحل:** التعويض: \`C = (8.85 × 10⁻¹²)(2) / (5 × 10⁻³)\`
- **الحل:** البسط: \`8.85 × 2 = 17.7\`، فالبسط \`17.7 × 10⁻¹²\`
- **الحل:** القسمة: \`17.7 ÷ 5 = 3.54\` و \`10⁻¹² ÷ 10⁻³ = 10⁻⁹\`
- **الحل:** \`C = 3.54 × 10⁻⁹ F\` (أي \`3.54 nF\`)
- **ثانيًا الشحنة:** بعد معرفة السعة والجهد نستخدم تعريف السعة: \`q = C·V\`
- **الحل:** التعويض: \`q = (3.54 × 10⁻⁹)(1 × 10⁻⁴)\`
- **الحل:** \`q = 3.54 × 10⁻¹³ C ≈ 3.5 × 10⁻¹³ C\`
- **معنى الشحنة على كل لوح:** أحد اللوحين يحمل \`+3.54 × 10⁻¹³ C\` والآخر يحمل \`−3.54 × 10⁻¹³ C\`.
- **ثالثًا المجال:** المجال بين لوحي المكثف **منتظم**، فنستخدم \`ΔV = E·d\` بعد إعادة ترتيبه.
- **القانون:** \`E = ΔV / d\`
- **الحل:** التعويض: \`E = (1 × 10⁻⁴) / (5 × 10⁻³)\`
- **الحل:** \`1 ÷ 5 = 0.2\` و \`10⁻⁴ ÷ 10⁻³ = 10⁻¹\`، فيكون \`E = 0.2 × 10⁻¹ = 0.02 N/C\`
- **تحديد الاتجاه:** يتجه المجال بين اللوحين من اللوح **الموجب** إلى اللوح **السالب**، عموديًا على اللوحين.
- **النتيجة:** \`C = 3.54 × 10⁻⁹ F\` · \`q ≈ 3.5 × 10⁻¹³ C\` · \`E = 0.02 N/C\` (تكافئ \`0.02 V/m\`) ✓
`,
ex:{q:`مكثف متوازي اللوحين مساحة كل لوح \`0.5 m²\` والمسافة بينهما \`1 mm\`، وصل بجهد \`100 V\`. أوجد سعته وشحنته.`,
st:[`\`d = 1 mm = 1 × 10⁻³ m\``,`\`C = (8.85 × 10⁻¹²)(0.5) / (1 × 10⁻³)\``,`\`C = 4.425 × 10⁻⁹ F ≈ 4.4 nF\``,`\`q = C·V = 4.425 × 10⁻⁹ × 100 = 4.4 × 10⁻⁷ C\``],
a:`\`C ≈ 4.4 × 10⁻⁹ F\` و \`q ≈ 4.4 × 10⁻⁷ C\``},
qz:[
{q:`مكثف شحنته \`4.5 × 10⁻⁴ C\` وجهده \`150 V\`، سعته:`,o:[`3 × 10⁻⁶ F`,`6.75 × 10⁻² F`,`3 × 10⁻⁴ F`,`3.3 × 10⁵ F`],a:0,w:`C = 4.5×10⁻⁴ / 150 = 3×10⁻⁶ F.`},
{q:`إذا زادت المسافة بين لوحي المكثف فإن سعته:`,o:[`تزداد`,`تقل`,`لا تتغير`,`تصبح صفرًا`],a:1,w:`C = ε₀A/d ← عكسيًا مع d.`},
{q:`مكثف سعته \`27 µF\` وجهده \`45 V\`، شحنته:`,o:[`1.215 × 10⁻³ C`,`6 × 10⁻⁷ C`,`1.67 C`,`1215 C`],a:0,w:`q = 27×10⁻⁶ × 45 = 1.215×10⁻³ C.`},
{q:`من فوائد المكثف:`,o:[`تخزين الطاقة الكهربائية`,`توليد الحرارة فقط`,`قياس الكتلة`,`زيادة المقاومة`],a:0,w:`وغيرها: الذبذبات، إزالة التشويش.`}
]},
/* 3-6 توصيل المكثفات */
{s:`### التوصيل على التوالي
- **الشحنة متساوية** على كل المكثفات، والجهود مختلفة.
- \`1/C_total = 1/C₁ + 1/C₂ + 1/C₃\`
- حالة خاصة لمكثفين فقط: \`C = C₁C₂ / (C₁ + C₂)\`
- \`V_total = V₁ + V₂ + V₃\` حيث \`V = q/C\`
- السعة المكافئة **أصغر** من أصغر سعة.
[[fig:capSeries]]
### التوصيل على التوازي
- **الجهد متساوٍ** على كل المكثفات، والشحنات مختلفة.
- \`C_total = C₁ + C₂ + C₃\`
- \`q_total = q₁ + q₂ + q₃\` حيث \`q = C·V\`
- السعة المكافئة **أكبر** من أكبر سعة.
[[fig:capParallel]]
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: مكثفان موصولان على التوازي
- **السؤال:** مكثفان سعة كل منهما \`200 × 10⁻¹² F\` و \`600 × 10⁻¹² F\` تم وصلهما على التوازي ثم شُحنا حتى صار فرق الجهد بينهما \`120 V\`. أوجد: السعة الكلية، والشحنة على كل مكثف، والشحنة الكلية.
- **المعطيات:** \`C₁ = 200 × 10⁻¹² F = 200 pF\` · \`C₂ = 600 × 10⁻¹² F = 600 pF\` · \`V = 120 V\` (حيث \`1 pF = 10⁻¹² F\`)
- **المطلوب:** \`C_total\` · \`q₁\` و \`q₂\` · \`q_total\`
- **فهم التوصيل على التوازي:** طرفا كل مكثف متصلان مباشرة بقطبي المصدر، لذلك **يتساوى فرق الجهد** على جميع المكثفات ويساوي جهد المصدر: \`V₁ = V₂ = V = 120 V\`، أما الشحنات فتختلف حسب سعة كل مكثف.
- **أولًا لماذا تُجمع السعات؟** التوصيل على التوازي يكافئ زيادة المساحة الكلية للألواح، والسعة تتناسب طرديًا مع المساحة، فتُجمع السعات مباشرة.
- **القانون:** \`C_total = C₁ + C₂\`
- **الحل:** \`C_total = 200 × 10⁻¹² + 600 × 10⁻¹²\`
- **الحل:** بما أن قوى العشرة متساوية نجمع الأعداد فقط: \`200 + 600 = 800\`
- **الحل:** \`C_total = 800 × 10⁻¹² F = 8 × 10⁻¹⁰ F = 800 pF\`
- **ثانيًا الشحنة على كل مكثف:** نطبق \`q = C·V\` على كل مكثف وحده بالجهد المشترك \`120 V\`.
- **الحل:** شحنة المكثف الأول: \`q₁ = C₁·V = (200 × 10⁻¹²)(120)\`
- **الحل:** \`200 × 120 = 24000\`، فيكون \`q₁ = 24000 × 10⁻¹² = 2.4 × 10⁻⁸ C\`
- **الحل:** شحنة المكثف الثاني: \`q₂ = C₂·V = (600 × 10⁻¹²)(120)\`
- **الحل:** \`600 × 120 = 72000\`، فيكون \`q₂ = 72000 × 10⁻¹² = 7.2 × 10⁻⁸ C\`
- **ملاحظة:** المكثف ذو السعة الأكبر يختزن شحنة أكبر لأن الجهد واحد على الاثنين.
- **ثالثًا الشحنة الكلية:** الشحنة التي سحبها المصدر هي مجموع شحنتي المكثفين.
- **القانون:** \`q_total = q₁ + q₂\`
- **الحل:** \`q_total = 2.4 × 10⁻⁸ + 7.2 × 10⁻⁸ = 9.6 × 10⁻⁸ C\`
- **التحقق بطريقة ثانية:** \`q_total = C_total·V = (800 × 10⁻¹²)(120) = 9.6 × 10⁻⁸ C\` وهو الناتج نفسه.
- **النتيجة:** \`C_total = 800 × 10⁻¹² F\` · \`q₁ = 2.4 × 10⁻⁸ C\` · \`q₂ = 7.2 × 10⁻⁸ C\` · \`q_total = 9.6 × 10⁻⁸ C\` ✓
### مثال ٢: مكثفان موصولان على التوالي
- **السؤال:** مكثفان سعة كل منهما \`3 × 10⁻¹² F\` و \`6 × 10⁻¹² F\` تم وصلهما على التوالي ثم وُصلت المجموعة بفرق جهد مقداره \`10 V\`. أوجد: السعة الكلية، والشحنة على كل لوح، والشحنة الكلية، وفرق الجهد عبر كل مكثف.
- **المعطيات:** \`C₁ = 3 × 10⁻¹² F = 3 pF\` · \`C₂ = 6 × 10⁻¹² F = 6 pF\` · \`V = 10 V\`
- **المطلوب:** \`C_total\` · \`q\` · \`V₁\` و \`V₂\`
- **فهم التوصيل على التوالي:** المكثفان على مسار واحد، والشحنة التي تُدفع إلى لوح الأول تحث شحنة مساوية على لوح الثاني، لذلك **تتساوى الشحنة** على جميع المكثفات: \`q₁ = q₂ = q\`، بينما **يتوزع** جهد المصدر عليهما: \`V = V₁ + V₂\`
- **أولًا لماذا هذا القانون للسعة؟** في التوالي تُجمع **مقلوبات** السعات \`1/C_total = 1/C₁ + 1/C₂\`، ولمكثفين فقط نختصرها إلى «حاصل الضرب على المجموع».
- **القانون:** \`C_total = C₁·C₂ / (C₁ + C₂)\`
- **الحل:** التعويض: \`C_total = (6 × 10⁻¹²)(3 × 10⁻¹²) / (6 × 10⁻¹² + 3 × 10⁻¹²)\`
- **الحل:** البسط: \`6 × 3 = 18\` و \`10⁻¹² × 10⁻¹² = 10⁻²⁴\`، فالبسط \`18 × 10⁻²⁴\`
- **الحل:** المقام: \`6 + 3 = 9\`، فالمقام \`9 × 10⁻¹²\`
- **الحل:** القسمة: \`18 ÷ 9 = 2\` و \`10⁻²⁴ ÷ 10⁻¹² = 10⁻¹²\`
- **الحل:** \`C_total = 2 × 10⁻¹² F = 2 pF\`
- **تحقق منطقي:** السعة المكافئة \`2 pF\` أصغر من أصغر سعة \`3 pF\` كما هو متوقع في التوالي.
- **ثانيًا الشحنة:** نطبق \`q = C·V\` على المجموعة كاملة بالسعة المكافئة وجهد المصدر.
- **الحل:** \`q = C_total·V = (2 × 10⁻¹²)(10) = 2 × 10⁻¹¹ C\`
- **الحل:** لأن التوصيل على التوالي: \`q₁ = q₂ = q = 2 × 10⁻¹¹ C\`، وهذه أيضًا هي الشحنة الكلية التي يزودها المصدر.
- **ثالثًا فرق الجهد عبر كل مكثف:** نعيد ترتيب تعريف السعة إلى \`V = q / C\` ونطبقه على كل مكثف بالشحنة المشتركة.
- **الحل:** المكثف الأول: \`V₁ = q / C₁ = (2 × 10⁻¹¹) / (3 × 10⁻¹²) = 6.67 V\`
- **الحل:** المكثف الثاني: \`V₂ = q / C₂ = (2 × 10⁻¹¹) / (6 × 10⁻¹²) = 3.33 V\`
- **ملاحظة:** المكثف ذو السعة **الأصغر** يأخذ الجهد **الأكبر** لأن الشحنة واحدة و \`V = q / C\`.
- **التحقق:** \`V₁ + V₂ = 6.67 + 3.33 = 10 V\` وهو جهد المصدر تمامًا.
- **النتيجة:** \`C_total = 2 × 10⁻¹² F\` · \`q = q₁ = q₂ = 2 × 10⁻¹¹ C\` · \`V₁ = 6.67 V\` · \`V₂ = 3.33 V\` ✓
`,
ex:{q:`مكثفان \`4 µF\` و \`12 µF\` وُصلا على التوالي مع \`12 V\`. أوجد السعة الكلية، والشحنة، وجهد كل مكثف. ثم أوجد السعة لو وُصلا على التوازي.`,
st:[`توالي: \`C = (4 × 12)/(4 + 12) = 48/16 = 3 µF\``,`\`q = C·V = 3 µF × 12 = 36 µC\` (نفسها على كل مكثف)`,`\`V₁ = 36/4 = 9 V\` و \`V₂ = 36/12 = 3 V\` (المجموع 12 ✓)`,`توازي: \`C = 4 + 12 = 16 µF\``],
a:`توالي: \`3 µF\`، \`36 µC\`، \`9 V\` و \`3 V\` · توازي: \`16 µF\``},
qz:[
{q:`في التوصيل على التوالي تكون متساوية على كل المكثفات:`,o:[`الجهود`,`الشحنات`,`السعات`,`الطاقات`],a:1,w:`q₁ = q₂ = q.`},
{q:`مكثفان \`200 pF\` و \`600 pF\` على التوازي، السعة الكلية:`,o:[`150 pF`,`400 pF`,`800 pF`,`1200 pF`],a:2,w:`200 + 600 = 800 pF.`},
{q:`مكثفان \`6 pF\` و \`3 pF\` على التوالي، السعة الكلية:`,o:[`9 pF`,`2 pF`,`18 pF`,`4.5 pF`],a:1,w:`(6 × 3)/(6 + 3) = 18/9 = 2 pF.`},
{q:`السعة المكافئة للمكثفات على التوالي تكون:`,o:[`أكبر من أكبر سعة`,`أصغر من أصغر سعة`,`تساوي متوسطها`,`تساوي مجموعها`],a:1,w:`لأن 1/C = مجموع المقلوبات.`},
{q:`مكثفان \`2 µF\` و \`4 µF\` على التوازي، السعة الكلية:`,o:[`1.33 µF`,`6 µF`,`8 µF`,`2 µF`],a:1,w:`2 + 4 = 6 µF.`}
]},
/* 3-7 الطاقة المختزنة */
{s:`### الطاقة المختزنة في المكثف
- \`E = ½·C·V²\`
- \`E = ½·q·V\`
- \`E = q² / (2C)\`
- اختر الصيغة حسب المعطيات. الوحدة: الجول \`J\`.
- ⚠️ ملاحظة: في المثال الثاني بالحقيبة الناتج الصحيح حسب \`E = ½qV\` هو \`½ × 2.4 × 200 = 240 J\`.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: الطاقة المختزنة من السعة والجهد
- **السؤال:** مكثف سعته \`2 × 10⁻⁶ F\` وُصل قطباه مع مصدر فرق جهد \`12 V\`، ما الطاقة المختزنة في المكثف؟
- **المعطيات:** \`C = 2 × 10⁻⁶ F\` (أي \`2 µF\`) · \`V = 12 V\`
- **المطلوب:** الطاقة المختزنة \`E\`.
- **لماذا هذه الصيغة؟** للطاقة المختزنة ثلاث صيغ متكافئة، ونختار الصيغة التي تحتوي المعطيات مباشرة، والمعطى هنا **السعة والجهد**.
- **القانون:** \`E = ½·C·V²\`
- **معنى الرموز:** \`E\` الطاقة المختزنة بالجول \`J\` · \`C\` السعة بالفاراد · \`V\` فرق الجهد بين اللوحين بالفولت
- **من أين جاء النصف؟** أثناء الشحن يرتفع جهد المكثف تدريجيًا من صفر إلى \`V\`، فمتوسط الجهد الذي نُقلت عنده الشحنة هو \`½V\`، لذلك الطاقة \`½·q·V\`، وبالتعويض \`q = C·V\` نحصل على \`½·C·V²\`.
- **الحل:** التعويض: \`E = ½ × (2 × 10⁻⁶) × (12)²\`
- **الحل:** نربع الجهد أولًا: \`(12)² = 144\`
- **الحل:** \`E = ½ × 2 × 10⁻⁶ × 144 = 144 × 10⁻⁶ J\`
- **الحل:** بالصيغة العلمية: \`E = 1.44 × 10⁻⁴ J\`
- **النتيجة:** \`E = 1.44 × 10⁻⁴ J\` ✓
### مثال ٢: الطاقة المختزنة من الشحنة والجهد
- **السؤال:** مكثف يحمل شحنة مقدارها \`2.4 C\` وُصل قطباه مع مصدر فرق جهد \`200 V\`، ما الطاقة المختزنة في المكثف؟
- **المعطيات:** \`q = 2.4 C\` · \`V = 200 V\`
- **المطلوب:** الطاقة المختزنة \`E\`.
- **لماذا هذه الصيغة؟** المعطى هنا **الشحنة والجهد** ولا نعرف السعة، فالصيغة الأنسب هي التي تربط الطاقة بهما مباشرة دون حاجة لحساب السعة.
- **القانون:** \`E = ½·q·V\`
- **معنى الرموز:** \`E\` الطاقة بالجول · \`q\` الشحنة على أحد اللوحين بالكولوم · \`V\` فرق الجهد بالفولت
- **الحل:** التعويض: \`E = ½ × 2.4 × 200\`
- **الحل:** \`2.4 × 200 = 480\`
- **الحل:** \`E = 480 ÷ 2 = 240 J\`
- **التحقق من الوحدة:** \`C × V = C × (J/C) = J\`
- **النتيجة:** \`E = 240 J\` ✓
`,
ex:{q:`مكثف سعته \`10 µF\` وُصل بجهد \`20 V\`. أوجد الطاقة المختزنة.`,
st:[`\`E = ½·C·V²\``,`\`E = ½ × (10 × 10⁻⁶) × 20²\``,`\`E = ½ × 10⁻⁵ × 400 = 2 × 10⁻³ J\``],
a:`\`E = 2 × 10⁻³ J = 2 mJ\``},
qz:[
{q:`مكثف \`2 µF\` على جهد \`12 V\`، الطاقة المختزنة:`,o:[`1.44 × 10⁻⁴ J`,`2.4 × 10⁻⁵ J`,`1.2 × 10⁻⁵ J`,`144 J`],a:0,w:`½ × 2×10⁻⁶ × 144 = 1.44×10⁻⁴ J.`},
{q:`إذا تضاعف الجهد على مكثف فإن طاقته:`,o:[`تتضاعف`,`تتضاعف أربع مرات`,`تقل للنصف`,`لا تتغير`],a:1,w:`E ∝ V².`},
{q:`مكثف شحنته \`2.4 C\` وجهده \`200 V\`، طاقته:`,o:[`480 J`,`240 J`,`83 J`,`0.012 J`],a:1,w:`½ × 2.4 × 200 = 240 J.`},
{q:`أي صيغة لا تصلح لحساب طاقة المكثف؟`,o:[`½CV²`,`½qV`,`q²/2C`,`CV/q`],a:3,w:`CV/q = 1 وليس طاقة.`}
]},
/* 3-8 ورقة عمل */
{s:`### ما تحتاجه لحل ورقة العمل
- كولوم: \`F = k·q₁q₂/r²\` (\`k = 9 × 10⁹\`)
- المجال: \`E = F/q\` · \`E = k·q/r²\`
- الجهد: \`V = k·q/r\` · \`ΔV = E·d\`
- السعة: \`C = q/V\` · \`C = ε₀A/d\` · \`V = E·d\` ← \`E = V/d\`
- التوازي: \`C = C₁ + C₂\` · التوالي: \`C = C₁C₂/(C₁ + C₂)\`
- الطاقة: \`E = ½CV²\`
- انتبه للبادئات: \`nC = 10⁻⁹\` · \`µC = 10⁻⁶\` · \`pF = 10⁻¹²\`

### حل ورقة العمل

### سؤال ١: اذكر نص قانون كولوم مع كتابة العلاقة الرياضية
- **نص القانون:** القوة الكهربائية المتبادلة بين شحنتين نقطيتين تتناسب طرديًّا مع حاصل ضرب مقداري الشحنتين، وعكسيًّا مع مربع المسافة بينهما، وتكون تجاذبًا إذا كانت الشحنتان مختلفتين وتنافرًا إذا كانتا متشابهتين.
- **القانون:** \`F = k · q₁ · q₂ ÷ r²\`
- **حيث:** \`F\` القوة بالنيوتن \`N\` · \`q₁ ، q₂\` الشحنتان بالكولوم \`C\` · \`r\` المسافة بينهما بالمتر \`m\` · \`k = 9 × 10⁹ N·m²/C²\` ثابت كولوم.

### سؤال ٢: عرّف كلًّا مما يلي
- **١ – شدة المجال الكهربائي:** القوة الكهربائية المؤثرة في وحدة الشحنات الموجبة الموضوعة عند تلك النقطة، وتعطى بالعلاقة \`E = F ÷ q\` ووحدتها \`N/C\`.
- **٢ – السعة الكهربائية:** النسبة بين مقدار الشحنة المختزنة على أحد لوحي المكثف وفرق الجهد بين لوحيه، وتعطى بالعلاقة \`C = Q ÷ V\` ووحدتها الفاراد \`F\`.

### سؤال ٣: (أ) العوامل المؤثرة على سعة المكثف، (ب) فوائد المكثف
- **أ – ١:** المساحة المشتركة للوحين \`A\` (تزداد السعة بزيادتها).
- **أ – ٢:** المسافة بين اللوحين \`d\` (تقل السعة بزيادتها).
- **أ – ٣:** نوع المادة العازلة بين اللوحين (ثابت العزل)، وتجمعها العلاقة \`C = ε₀ · εᵣ · A ÷ d\`.
- **ب – ١:** تخزين الشحنات والطاقة الكهربائية وتفريغها عند الحاجة (مثل فلاش الكاميرا).
- **ب – ٢:** تنعيم التيار في دوائر التقويم وإزالة التذبذبات.
- **ب – ٣:** الاستخدام في دوائر التوليف (الراديو) ودوائر التوقيت، وتحسين معامل القدرة في المحركات.

### سؤال ٤: شحنتان q₁ = 3 × 10⁻⁹ C و q₂ = −5 × 10⁻⁹ C والمسافة بينهما 2 m، أوجد القوة الكهربائية
- **المعطيات:** \`q₁ = 3 × 10⁻⁹ C\` · \`q₂ = −5 × 10⁻⁹ C\` · \`r = 2 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **المطلوب:** القوة الكهربائية \`F\`
- **القانون:** \`F = k · q₁ · q₂ ÷ r²\`
- **الحل:** \`F = 9 × 10⁹ × 3 × 10⁻⁹ × 5 × 10⁻⁹ ÷ 2²\`
- **الحل:** \`F = 135 × 10⁻⁹ ÷ 4\`
- **الحل:** \`F = 33.75 × 10⁻⁹ N = 3.375 × 10⁻⁸ N\`
- **النتيجة:** \`F = 3.375 × 10⁻⁸ N\` وهي قوة تجاذب لأن الشحنتين مختلفتان ✓

### سؤال ٥: شحنة 4 × 10⁻⁶ C في مجال كهربائي تأثرت بقوة 8 × 10⁻³ N، ما مقدار المجال؟
- **المعطيات:** \`q = 4 × 10⁻⁶ C\` · \`F = 8 × 10⁻³ N\`
- **المطلوب:** شدة المجال \`E\`
- **القانون:** \`E = F ÷ q\`
- **الحل:** \`E = 8 × 10⁻³ ÷ (4 × 10⁻⁶)\`
- **الحل:** \`E = 2 × 10³ N/C\`
- **النتيجة:** \`E = 2000 N/C\` ✓

### سؤال ٦: أوجد شدة المجال على بعد 0.25 m من شحنة 3 × 10⁻⁹ C
- **المعطيات:** \`q = 3 × 10⁻⁹ C\` · \`r = 0.25 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **المطلوب:** شدة المجال \`E\`
- **القانون:** \`E = k · q ÷ r²\`
- **الحل:** \`r² = 0.25² = 0.0625 m²\`
- **الحل:** \`E = 9 × 10⁹ × 3 × 10⁻⁹ ÷ 0.0625\`
- **الحل:** \`E = 27 ÷ 0.0625\`
- **الحل:** \`E = 432 N/C\`
- **النتيجة:** \`E = 432 N/C\` ✓

### سؤال ٧: فرق الجهد بين نقطتين في مجال منتظم شدته 1000 N/C والمسافة بينهما 0.02 m
- **المعطيات:** \`E = 1000 N/C\` · \`d = 0.02 m\`
- **المطلوب:** فرق الجهد \`V\`
- **القانون:** \`V = E · d\`
- **الحل:** \`V = 1000 × 0.02\`
- **الحل:** \`V = 20 V\`
- **النتيجة:** \`V = 20 V\` ✓

### سؤال ٨: أوجد الجهد على بعد 0.2 m من شحنة نقطية 4 × 10⁻⁶ C
- **المعطيات:** \`q = 4 × 10⁻⁶ C\` · \`r = 0.2 m\` · \`k = 9 × 10⁹ N·m²/C²\`
- **المطلوب:** الجهد \`V\`
- **القانون:** \`V = k · q ÷ r\`
- **الحل:** \`V = 9 × 10⁹ × 4 × 10⁻⁶ ÷ 0.2\`
- **الحل:** \`V = 36 × 10³ ÷ 0.2\`
- **الحل:** \`V = 1.8 × 10⁵ V\`
- **النتيجة:** \`V = 180000 V\` ✓

### سؤال ٩: سعة مكثف شحنته 4 × 10⁻⁴ C وفرق الجهد بين لوحيه 100 V
- **المعطيات:** \`Q = 4 × 10⁻⁴ C\` · \`V = 100 V\`
- **المطلوب:** السعة \`C\`
- **القانون:** \`C = Q ÷ V\`
- **الحل:** \`C = 4 × 10⁻⁴ ÷ 100\`
- **الحل:** \`C = 4 × 10⁻⁶ F\`
- **النتيجة:** \`C = 4 × 10⁻⁶ F = 4 µF\` ✓

### سؤال ١٠: مكثف سعته 4.5 × 10⁻¹² F متصل ببطارية 12 V، أوجد: ١) الشحنة ٢) الطاقة المختزنة
- **المعطيات:** \`C = 4.5 × 10⁻¹² F\` · \`V = 12 V\`
- **المطلوب:** ١) الشحنة \`Q\` ٢) الطاقة \`W\`
- **القانون:** \`Q = C · V\` · \`W = ½ · C · V²\`
- **الحل:** ١) \`Q = 4.5 × 10⁻¹² × 12\`
- **الحل:** \`Q = 54 × 10⁻¹² C = 5.4 × 10⁻¹¹ C\`
- **الحل:** ٢) \`W = ½ × 4.5 × 10⁻¹² × 12²\`
- **الحل:** \`W = 0.5 × 4.5 × 10⁻¹² × 144\`
- **الحل:** \`W = 324 × 10⁻¹² J = 3.24 × 10⁻¹⁰ J\`
- **النتيجة:** ١) \`Q = 5.4 × 10⁻¹¹ C\` على كل لوح (موجبة على أحدهما وسالبة على الآخر) ٢) \`W = 3.24 × 10⁻¹⁰ J\` ✓

### سؤال ١١: مكثف متوازي اللوحين، d = 1 × 10⁻³ m و C = 6 × 10⁻⁶ F وشحنته 6 × 10⁻⁶ C، أوجد: ١) فرق الجهد ٢) المجال داخله
- **المعطيات:** \`d = 1 × 10⁻³ m\` · \`C = 6 × 10⁻⁶ F\` · \`Q = 6 × 10⁻⁶ C\`
- **المطلوب:** ١) فرق الجهد \`V\` ٢) المجال \`E\`
- **القانون:** \`V = Q ÷ C\` · \`E = V ÷ d\`
- **الحل:** ١) \`V = 6 × 10⁻⁶ ÷ (6 × 10⁻⁶)\`
- **الحل:** \`V = 1 V\`
- **الحل:** ٢) \`E = 1 ÷ (1 × 10⁻³)\`
- **الحل:** \`E = 1 × 10³ V/m\`
- **النتيجة:** ١) \`V = 1 V\` ٢) \`E = 1000 V/m\` (أي \`1000 N/C\`) ✓

### سؤال ١٢: مكثفان 2 × 10⁻⁶ F و 4 × 10⁻⁶ F، أوجد السعة الكلية: ١) على التوالي ٢) على التوازي
- **المعطيات:** \`C₁ = 2 × 10⁻⁶ F\` · \`C₂ = 4 × 10⁻⁶ F\`
- **المطلوب:** السعة المكافئة في الحالتين
- **القانون:** توالي \`1 ÷ C = 1 ÷ C₁ + 1 ÷ C₂\` أو \`C = C₁ · C₂ ÷ (C₁ + C₂)\` · توازي \`C = C₁ + C₂\`
- **الحل:** ١) \`C = (2 × 10⁻⁶ × 4 × 10⁻⁶) ÷ (2 × 10⁻⁶ + 4 × 10⁻⁶)\`
- **الحل:** \`C = 8 × 10⁻¹² ÷ (6 × 10⁻⁶)\`
- **الحل:** \`C ≈ 1.33 × 10⁻⁶ F\`
- **الحل:** ٢) \`C = 2 × 10⁻⁶ + 4 × 10⁻⁶ = 6 × 10⁻⁶ F\`
- **النتيجة:** ١) التوالي \`C ≈ 1.33 × 10⁻⁶ F\` ٢) التوازي \`C = 6 × 10⁻⁶ F\` ✓

### سؤال ١٣: مكثفان C₁ = 4 × 10⁻⁹ F و C₂ = 2 × 10⁻⁹ F على التوالي، وفرق الجهد 12 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) فرق جهد كل مكثف
- **المعطيات:** \`C₁ = 4 × 10⁻⁹ F\` · \`C₂ = 2 × 10⁻⁹ F\` · \`V = 12 V\`
- **المطلوب:** \`C\` · \`Q₁ ، Q₂\` · \`V₁ ، V₂\`
- **القانون:** \`C = C₁ · C₂ ÷ (C₁ + C₂)\` · \`Q = C · V\` (الشحنة متساوية في التوالي) · \`V₁ = Q ÷ C₁\`
- **الحل:** ١) \`C = (4 × 10⁻⁹ × 2 × 10⁻⁹) ÷ (6 × 10⁻⁹)\`
- **الحل:** \`C = 8 × 10⁻⁹ ÷ 6 ≈ 1.33 × 10⁻⁹ F\`
- **الحل:** ٢) \`Q = C · V = (8 ÷ 6) × 10⁻⁹ × 12\`
- **الحل:** \`Q = 16 × 10⁻⁹ C = 1.6 × 10⁻⁸ C\` وهي نفسها على كل مكثف \`Q₁ = Q₂ = 1.6 × 10⁻⁸ C\`
- **الحل:** ٣) \`V₁ = Q ÷ C₁ = 16 × 10⁻⁹ ÷ (4 × 10⁻⁹) = 4 V\`
- **الحل:** \`V₂ = Q ÷ C₂ = 16 × 10⁻⁹ ÷ (2 × 10⁻⁹) = 8 V\`
- **الحل:** تحقق \`V₁ + V₂ = 4 + 8 = 12 V\`
- **النتيجة:** ١) \`C ≈ 1.33 × 10⁻⁹ F\` ٢) \`Q₁ = Q₂ = 1.6 × 10⁻⁸ C\` ٣) \`V₁ = 4 V\` و \`V₂ = 8 V\` ✓

### سؤال ١٤: مكثفان C₁ = 400 × 10⁻⁹ F و C₂ = 100 × 10⁻⁹ F على التوازي، وفرق الجهد 110 V، أوجد: ١) السعة الكلية ٢) شحنة كل مكثف ٣) الشحنة الكلية
- **المعطيات:** \`C₁ = 400 × 10⁻⁹ F\` · \`C₂ = 100 × 10⁻⁹ F\` · \`V = 110 V\`
- **المطلوب:** \`C\` · \`Q₁ ، Q₂\` · \`Q\`
- **القانون:** \`C = C₁ + C₂\` · \`Q = C · V\` (فرق الجهد متساوٍ في التوازي) · \`Q = Q₁ + Q₂\`
- **الحل:** ١) \`C = 400 × 10⁻⁹ + 100 × 10⁻⁹ = 500 × 10⁻⁹ F = 5 × 10⁻⁷ F\`
- **الحل:** ٢) \`Q₁ = C₁ · V = 400 × 10⁻⁹ × 110 = 4.4 × 10⁻⁵ C\`
- **الحل:** \`Q₂ = C₂ · V = 100 × 10⁻⁹ × 110 = 1.1 × 10⁻⁵ C\`
- **الحل:** ٣) \`Q = Q₁ + Q₂ = 4.4 × 10⁻⁵ + 1.1 × 10⁻⁵ = 5.5 × 10⁻⁵ C\`
- **الحل:** تحقق \`Q = C · V = 5 × 10⁻⁷ × 110 = 5.5 × 10⁻⁵ C\`
- **النتيجة:** ١) \`C = 5 × 10⁻⁷ F\` ٢) \`Q₁ = 4.4 × 10⁻⁵ C\` و \`Q₂ = 1.1 × 10⁻⁵ C\` ٣) \`Q = 5.5 × 10⁻⁵ C\` ✓
`,
ex:{q:`(مثال مشابه) مكثف سعته \`5 µF\` شحنته \`10 µC\` والمسافة بين لوحيه \`2 mm\`. أوجد فرق الجهد والمجال بين اللوحين.`,
st:[`\`V = q/C = (10 × 10⁻⁶)/(5 × 10⁻⁶) = 2 V\``,`\`E = V/d = 2 / (2 × 10⁻³)\``,`\`E = 1000 N/C\``],
a:`\`V = 2 V\` و \`E = 1000 N/C\``},
qz:[
{q:`شحنتان \`3 nC\` و \`−5 nC\` بينهما \`2 m\`، القوة:`,o:[`3.375 × 10⁻⁸ N تجاذب`,`3.375 × 10⁻⁸ N تنافر`,`6.75 × 10⁻⁸ N تجاذب`,`1.35 × 10⁻⁷ N تنافر`],a:0,w:`9×10⁹ × 15×10⁻¹⁸ / 4 = 3.375×10⁻⁸ N، وتجاذب لاختلاف الإشارتين.`},
{q:`شحنة \`4 µC\` تأثرت بقوة \`8 × 10⁻³ N\`، المجال:`,o:[`2000 N/C`,`500 N/C`,`3.2 × 10⁻⁸ N/C`,`2 N/C`],a:0,w:`8×10⁻³ / 4×10⁻⁶ = 2×10³ N/C.`},
{q:`مكثف شحنته \`4 × 10⁻⁴ C\` وجهده \`100 V\`، سعته:`,o:[`4 × 10⁻⁶ F`,`4 × 10⁻² F`,`2.5 × 10⁵ F`,`4 × 10⁻⁴ F`],a:0,w:`4×10⁻⁴ / 100 = 4×10⁻⁶ F.`},
{q:`مكثفان \`2 µF\` و \`4 µF\` على التوالي، السعة الكلية:`,o:[`6 µF`,`1.33 µF`,`8 µF`,`0.75 µF`],a:1,w:`(2 × 4)/(2 + 4) = 8/6 ≈ 1.33 µF.`}
]},
/* 3-9 تمارين الوحدة */
{s:`### مراجعة الوحدة الرابعة
- **الشحنات:** المتشابهة تتنافر، المختلفة تتجاذب · وحدتها الكولوم.
- **طرق الشحن:** الدلك، اللمس، الحث (دون ملامسة).
- **كولوم:** \`F = kq₁q₂/r²\`
- **المجال:** \`E = F/q = kq/r²\` · خطوطه من الموجب للسالب، لا تتقاطع، تتقارب حيث المجال قوي.
- **الجهد:** \`V = kq/r\` · \`ΔV = Ed\` · \`ΔV = W/q\`
- **المكثف:** \`C = q/V = ε₀A/d\` · تقل السعة بزيادة المسافة.
- **التوصيل:** توازي (جهد واحد، \`C = ΣC\`) · توالي (شحنة واحدة، \`V = ΣV\`، السعة أصغر من أصغرها).
- **الطاقة:** \`E = ½CV²\`
### تمارين الوحدة محلولة
### سؤال ١: المعادلة التي تحدد مقدار الشحنة
- **السؤال:** يمكن قياس مقدار الشحنة الكهربائية من خلال المعادلة التالية: \`C = εᵣ·ε₀·A / d\` أم \`1 F = 1 C / 1 V\` أم \`q ∝ V\`؟
- **الإجابة:** \`q ∝ V\`
- **السبب:** الشحنة على المكثف تتناسب طرديًا مع فرق الجهد بين لوحيه، وثابت التناسب هو السعة، أي \`q = C·V\`، فبمعرفة الجهد والسعة نحسب مقدار الشحنة، أما المعادلة الأولى فتحسب **السعة** من الأبعاد، والثانية تعرّف **وحدة** الفاراد فقط.
### سؤال ٢: المكثف في دارات المذياع
- **السؤال:** يعد المكثف من العناصر الفرعية في تركيب غالبية الدارات الإلكترونية والكهربائية مثل دارات الإرسال والاستقبال في المذياع، والخيارات: \`107.6 f\` · \`117 f\` · \`95 f\`
- **الإجابة:** العبارة نفسها **صحيحة**، فالمكثف عنصر أساسي في دارات الإرسال والاستقبال، ويُستخدم مع الملف في دارة الضبط لاختيار تردد المحطة.
- **ملاحظة:** نص السؤال كما ورد ناقص، والخيارات قيم ترددات لا تتعلق بالعبارة ولا يمكن ترجيح أحدها، فإن قُصد بها ترددات محطات بالميغاهرتز فإن \`95\` و \`107.6\` تقعان ضمن نطاق البث الإذاعي FM (تقريبًا من \`88\` إلى \`108 MHz\`) بينما \`117\` خارجه.
### سؤال ٣: قانون التوصيل على التوازي
- **الإجابة:** \`C_eq = C₁ + C₂ + … + Cₙ\`
- **السبب:** في التوازي يتساوى الجهد على المكثفات وتُجمع الشحنات، فتُجمع السعات مباشرة، أما \`1/C_eq = 1/C₁ + 1/C₂ + …\` فهو قانون **التوالي**، لذلك «جميع ما سبق» خطأ.
### سؤال ٤: قوانين التوصيل على التوالي
- **السؤال:** يمكن التعبير عن قانون السعة المكافئة والشحنة المكافئة بالقانون التالي: \`q = q₁ = q₂ = q₃\` أم \`1/C_eq = 1/C₁ + 1/C₂ + 1/C₃\` أم جميع ما سبق؟
- **الإجابة:** جميع ما سبق
- **السبب:** العلاقتان معًا تصفان التوصيل على **التوالي**: الشحنة متساوية على جميع المكثفات، والسعة المكافئة تُحسب بجمع المقلوبات.
### سؤال ٥: وحدة قياس الشحنة
- **الإجابة:** الكولوم \`C\`
- **السبب:** الكولوم هي وحدة الشحنة في النظام الدولي، أما المتر فوحدة طول، والجول وحدة طاقة.
### سؤال ٦: المواد التي لا تسمح بمرور الشحنات
- **الإجابة:** المواد العازلة
- **السبب:** إلكتروناتها مقيدة وغير حرة الحركة، مثل الزجاج والخشب والبلاستيك، أما الشغل والقدرة فكميات فيزيائية وليست أنواعًا من المواد.
### سؤال ٧: تدفق الشحنات عند تطبيق فرق جهد
- **الإجابة:** التيار الكهربائي
- **السبب:** التيار هو معدل تدفق الشحنات عبر مقطع الموصل بتأثير فرق الجهد، \`I = q / t\`.
### سؤال ٨: سريان التيار في السلك بين طرفي المصدر
- **العبارة:** أنّ التيار الكهربائي قد سرى في السلك الناقل حينما ربطنا مصدر الجهد الكهربائي بين طرفيه، وهذا هو شكل أولي مصغر للدائرة الكهربائية.
- **الإجابة:** صحيحة ✓
- **التوضيح:** مصدر جهد وسلك موصل يغلق المسار بين قطبيه يكوّنان أبسط دائرة كهربائية مغلقة يسري فيها التيار.
### سؤال ٩: تفاعل الشحنات المختلفة
- **العبارة:** الشحنات المختلفة تتنافر.
- **الإجابة:** خاطئة ✗
- **التصحيح:** الشحنات المختلفة **تتجاذب**، والمتشابهة هي التي تتنافر.
### سؤال ١٠: تعريف الشحن بالدلك
- **العبارة:** الشحن بالدلك هو عملية شحن جسم متعادل دون ملامسة ويتم ذلك بتقريب جسم مشحون.
- **الإجابة:** خاطئة ✗
- **التصحيح:** هذا تعريف الشحن **بالحث (التأثير)**، أما الشحن بالدلك فهو انتقال بعض الإلكترونات من مادة إلى أخرى عند دلكهما معًا.
### سؤال ١١: وحدة السعة الكهربائية
- **العبارة:** وحدة السعة الكهربائية هي الكولوم.
- **الإجابة:** خاطئة ✗
- **التصحيح:** وحدة السعة هي **الفاراد** \`F = C/V\`، أما الكولوم فوحدة الشحنة.
### سؤال ١٢: اتجاه خطوط المجال حول الشحنة السالبة
- **العبارة:** خطوط المجال الكهربائي تكون إلى الخارج من الشحنة السالبة.
- **الإجابة:** خاطئة ✗
- **التصحيح:** خطوط المجال تخرج من الشحنة **الموجبة**، وتتجه إلى **الداخل** نحو الشحنة السالبة.
### سؤال ١٣: تقاطع خطوط المجال
- **العبارة:** خطوط المجال الكهربائي تتقاطع مع بعضها البعض.
- **الإجابة:** خاطئة ✗
- **التصحيح:** خطوط المجال **لا تتقاطع أبدًا**، لأن للمجال عند كل نقطة اتجاهًا واحدًا فقط، ولو تقاطع خطان لكان للنقطة اتجاهان.
### سؤال ١٤: تقارب خطوط المجال وشدته
- **العبارة:** كلما كانت خطوط المجال الكهربائي متقاربة كان المجال الكهربائي قويًا.
- **الإجابة:** صحيحة ✓
- **التوضيح:** كثافة الخطوط تعبر عن شدة المجال، فتتقارب قرب الشحنة حيث المجال قوي وتتباعد بعيدًا عنها.
### سؤال ١٥: صفة المجال المنتظم
- **العبارة:** المجال الكهربائي المنتظم ثابت الشدة ومتغير الاتجاه.
- **الإجابة:** خاطئة ✗
- **التصحيح:** المجال المنتظم **ثابت الشدة والاتجاه** عند جميع النقاط، مثل المجال بين لوحي مكثف.
### سؤال ١٦: علاقة الشحنة بالجهد في المكثف
- **العبارة:** مقدار الشحنة الكهربائية في المكثف لا يتناسب مع فرق الجهد بين طرفي المكثف.
- **الإجابة:** خاطئة ✗
- **التصحيح:** الشحنة **تتناسب طرديًا** مع فرق الجهد: \`q = C·V\`، أي \`q ∝ V\`.
### سؤال ١٧: تفاعل الشحنات المتشابهة
- **العبارة:** الشحنات المتشابهة تتنافر فيما بينها.
- **الإجابة:** صحيحة ✓
### سؤال ١٨: تعريف المواد الموصلة
- **العبارة:** المواد الناقلة (الموصلة) هي المواد التي تمتلك أعدادًا هائلة من الإلكترونات الحرة في درجة حرارة الغرفة، مما يجعلها ناقلة جيدة للكهرباء، مثل الحديد والنحاس والألومنيوم.
- **الإجابة:** صحيحة ✓
- **ملاحظة:** الاسم الإنجليزي الصحيح للنحاس هو copper.
### سؤال ١٩: نص قانون كولوم
- **العبارة:** القوى المتبادلة بين أي شحنتين نقطيتين تتناسب طرديًا مع حاصل ضرب مقدار كل منهما، وعكسيًا مع مربع المسافة بينهما.
- **الإجابة:** صحيحة ✓
- **التوضيح:** وهذا ما تعبر عنه الصيغة \`F = k·q₁·q₂ / r²\`.
### سؤال ٢٠: المجال حقل من المتجهات
- **العبارة:** المجال الكهربائي هو حيز مكون من مجموعة من المتجهات أو حقل من المتجهات بمعدل متجه واحد لكل نقطة حول الشحنة الكهربائية.
- **الإجابة:** صحيحة ✓
- **التوضيح:** لكل نقطة في المجال متجه واحد له مقدار واتجاه.
### سؤال ٢١: صيغة مجال الشحنة النقطية
- **العبارة:** المجال الكهربائي الناشئ عن شحنة نقطية مقدارها q عند نقطة تبعد عنها مسافة r هو \`E = (1 / 4πε₀)·q / r²\` في اتجاه متجه الوحدة \`r̂\`.
- **الإجابة:** صحيحة ✓
- **التوضيح:** المقدار \`1 / 4πε₀\` يساوي ثابت كولوم \`k ≈ 9 × 10⁹ N·m²/C²\`، فالصيغة هي نفسها \`E = k·q / r²\`.
### سؤال ٢٢: تناسب الشحنة مع الجهد
- **العبارة:** مقدار الشحنة الكهربائية يتناسب طردًا مع فرق الجهد بين طرفي المكثف الكهربائي، ويمكن أن نعبر عن ذلك رياضيًا على النحو الآتي: \`q ∝ V\`
- **الإجابة:** صحيحة ✓
### سؤال ٢٣: السعة في الفراغ والهواء
- **العبارة:** مقدار سعة المكثف في حالة إذا كان الفراغ هو الوسط العازل يساوي تقريبًا مقدار السعة في حالة إذا كان الهواء هو الوسط العازل.
- **الإجابة:** صحيحة ✓
- **التوضيح:** ثابت العزل للهواء يساوي تقريبًا \`1.0006\`، أي قريب جدًا من ثابت الفراغ \`1\`.
### سؤال ٢٤: تعريف سعة المكثف
- **العبارة:** سعة المكثف الكهربائي هي النسبة الثابتة بين شحنة المكثف إلى فرق الجهد بين طرفيه.
- **الإجابة:** صحيحة ✓
- **التوضيح:** \`C = q / V\`.
### سؤال ٢٥: التوصيل المركب
- **العبارة:** التوصيل المركب هو خليط من التوصيل على التوازي وعلى التوالي.
- **الإجابة:** صحيحة ✓
### سؤال ٢٦: الجهد في التوصيل على التوالي
- **العبارة:** فرق الجهد بين طرفي المكثفات على التوالي يساوي مجموع فرق الجهد لكل مكثف على حدة أي أن: \`V = V₁ + V₂ + V₃\`
- **الإجابة:** صحيحة ✓
### سؤال ٢٧: السعة المكافئة في التوالي
- **العبارة:** السعة المكافئة تكون أصغر من أصغر سعة في المكثفات المتصلة على التوالي أي أن: \`1/C_eq = 1/C₁ + 1/C₂ + 1/C₃\`
- **الإجابة:** صحيحة ✓
- **التوضيح:** لأن \`1/C_eq\` أكبر من أي مقلوب منفرد، فتكون \`C_eq\` أصغر من أي سعة منفردة.
### سؤال ٢٨: استخدام المكثف في تخزين الطاقة
- **العبارة:** يستخدم المكثف في تخزين الطاقة الكهربائية.
- **الإجابة:** صحيحة ✓
- **التوضيح:** الطاقة المختزنة \`E = ½·C·V²\`.
### سؤال ٢٩: أثر المسافة بين الألواح على السعة
- **العبارة:** تقل السعة الكهربائية عندما تزداد المسافة بين ألواح المكثف.
- **الإجابة:** صحيحة ✓
- **التوضيح:** من \`C = ε₀·A / d\` السعة تتناسب عكسيًا مع المسافة \`d\`.
`,
ex:{q:`ثلاثة مكثفات كل منها \`6 µF\`. أوجد السعة المكافئة إذا وُصلت (أ) توازيًا (ب) توالي.`,
st:[`(أ) \`C = 6 + 6 + 6 = 18 µF\``,`(ب) \`1/C = 1/6 + 1/6 + 1/6 = 3/6 = 1/2\``,`\`C = 2 µF\``],
a:`(أ) \`18 µF\` (ب) \`2 µF\``},
qz:[
{q:`عند تقريب شحنة موجبة من شحنة سالبة فإنهما:`,o:[`تتنافران`,`تتجاذبان`,`لا تتأثران`,`تتحولان إلى شحنتين موجبتين`],a:1,w:`الشحنات المختلفة تتجاذب.`},
{q:`وحدة السعة الكهربائية هي:`,o:[`الكولوم`,`الفاراد`,`الفولت`,`الأوم`],a:1,w:`الفاراد F = C/V.`},
{q:`اتجاه خطوط المجال حول الشحنة السالبة:`,o:[`إلى الخارج منها`,`إلى الداخل نحوها`,`دائرية حولها`,`لا توجد خطوط حولها`],a:1,w:`الخطوط تدخل في الشحنة السالبة.`},
{q:`كلما كانت خطوط المجال متقاربة كان المجال:`,o:[`ضعيفًا`,`قويًا`,`منعدمًا`,`منتظمًا دائمًا`],a:1,w:`كثافة الخطوط تدل على الشدة.`},
{q:`في توصيل المكثفات على التوالي يكون الجهد الكلي:`,o:[`V = V₁ = V₂ = V₃`,`V = V₁ + V₂ + V₃`,`V = V₁ × V₂ × V₃`,`1/V = 1/V₁ + 1/V₂`],a:1,w:`الجهد الكلي مجموع الجهود، والشحنة واحدة.`},
{q:`مقدار الشحنة على المكثف يتناسب مع فرق الجهد بين طرفيه:`,o:[`طرديًا`,`عكسيًا`,`لا يتناسب`,`مع مربعه`],a:0,w:`q = CV.`},
{q:`مواد لا تسمح بمرور الشحنات كالزجاج والخشب:`,o:[`الموصلة`,`العازلة`,`شبه الموصلة`,`فائقة التوصيل`],a:1,w:`العوازل.`}
]}
];
window.STUDY=window.STUDY||[];
window.STUDY[4]=[
/* 4-0 مقدمة */
{s:`### موضوع الوحدة
- مفهوم **التيار الكهربائي** في الدائرة وعلاقته بالمقاومة.
- **كثافة التيار** و**سرعة الانجراف**.
- **المقاومة** و**المقاومة النوعية** وأثر درجة الحرارة.
- **قانون أوم** وحدود صلاحيته.
- **القدرة الكهربائية** وتوصيل المقاومات.
### وحدات مهمة
- التيار: الأمبير \`A\` · الجهد: الفولت \`V\` · المقاومة: الأوم \`Ω\` · القدرة: الواط \`W\` · المقاومة النوعية: \`Ω·m\``,
ex:{q:`اكتب وحدة كل من: التيار، الجهد، المقاومة، القدرة، كثافة التيار.`,
st:[`التيار ← أمبير \`A = C/s\``,`الجهد ← فولت \`V = J/C\``,`المقاومة ← أوم \`Ω = V/A\``,`القدرة ← واط \`W = J/s\``,`كثافة التيار ← \`A/m²\``],
a:`\`A\`، \`V\`، \`Ω\`، \`W\`، \`A/m²\``},
qz:[
{q:`وحدة قياس التيار الكهربائي:`,o:[`الفولت`,`الأمبير`,`الأوم`,`الواط`],a:1,w:`الأمبير = كولوم/ثانية.`},
{q:`وحدة قياس المقاومة:`,o:[`الأوم`,`الفاراد`,`الكولوم`,`الجول`],a:0,w:`Ω = V/A.`},
{q:`الجهاز المستخدم لقياس شدة التيار:`,o:[`الفولتميتر`,`الأميتر`,`الترمومتر`,`الميكرومتر`],a:1,w:`الأميتر يوصل على التوالي.`},
{q:`الجهاز المستخدم لقياس فرق الجهد:`,o:[`الفولتميتر`,`الأميتر`,`الأوميتر فقط`,`البارومتر`],a:0,w:`الفولتميتر يوصل على التوازي.`}
]},
/* 4-1 التيار الكهربائي */
{s:`### التيار الكهربائي
- سيل من الشحنات يتحرك بانتظام في اتجاه معين.
### شدة التيار
- معدل مرور الشحنة عبر مقطع الموصل:
\`I = q / t\` ← الوحدة الأمبير \`A = C/s\`
### الشحنة وعدد الإلكترونات
\`q = n·e\` حيث \`e = 1.6 × 10⁻¹⁹ C\`
- عدد الإلكترونات: \`n = q / e\`
### اتجاه التيار
- **الاصطلاحي:** اتجاه حركة الشحنات الموجبة (من + إلى − خارج المصدر).
- **الحقيقي:** حركة الإلكترونات من السالب إلى الموجب.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: حساب شدة التيار من الشحنة والزمن
- **السؤال:** شحنة مقدارها \`q = 10 C\` تمر في سلك وذلك لمدة \`t = 60 s\`. أوجد التيار الكهربائي.
- **المعطيات:** \`q = 10 C\` (كمية الشحنة التي عبرت مقطع السلك) · \`t = 60 s\` (الزمن الذي استغرقه مرورها، وهو بالثانية أصلًا فلا يحتاج إلى تحويل).
- **المطلوب:** شدة التيار \`I\` بوحدة الأمبير.
- **لماذا هذا القانون؟** شدة التيار تعرَّف بأنها معدل مرور الشحنة عبر مقطع الموصل، أي كمية الشحنة التي تعبر المقطع في كل ثانية؛ وبما أن السؤال يعطينا الشحنة والزمن مباشرة فهذا التعريف هو الطريق الأقصر.
- **القانون:** \`I = q / t\`
- **معنى الرموز:** \`I\` شدة التيار بالأمبير \`A\` · \`q\` الشحنة المارة بالكولوم \`C\` · \`t\` الزمن بالثانية \`s\`. ووحدة الأمبير تساوي \`1 A = 1 C/s\`.
- **الحل:** نعوض بالقيم: \`I = 10 C / 60 s\`
- **الحل:** نقسم البسط على المقام: \`I = 0.1667 C/s\`
- **الحل:** وبما أن \`C/s = A\` فإن: \`I ≈ 0.17 A\`
- **تفسير النتيجة:** معنى ذلك أن نحو \`0.17 C\` من الشحنة يعبر مقطع السلك في كل ثانية، وعلى مدى \`60 s\` يتجمع المجموع \`0.1667 × 60 = 10 C\` وهو ما يطابق المعطى.
- **النتيجة:** شدة التيار \`I ≈ 0.17 A\` ✓
- **ملاحظة:** القيمة المطبوعة في الحل الأصلي \`0.16 A\` ناتجة عن قطع الكسر بدل تقريبه؛ فالقيمة الدقيقة \`10 ÷ 60 = 0.1667 A\`، وتقريبها الصحيح لمنزلتين عشريتين هو \`0.17 A\`.
`,
ex:{q:`يمر تيار \`0.5 A\` في سلك لمدة دقيقة. أوجد الشحنة المارة وعدد الإلكترونات.`,
st:[`\`t = 60 s\``,`\`q = I·t = 0.5 × 60 = 30 C\``,`\`n = q/e = 30 / (1.6 × 10⁻¹⁹)\``,`\`n ≈ 1.875 × 10²⁰\` إلكترون`],
a:`\`q = 30 C\` و \`n ≈ 1.9 × 10²⁰\` إلكترون`},
qz:[
{q:`شحنة \`10 C\` تمر في سلك خلال \`60 s\`، التيار:`,o:[`600 A`,`0.17 A`,`6 A`,`70 A`],a:1,w:`10/60 ≈ 0.17 A.`},
{q:`شحنة الإلكترون:`,o:[`1.6 × 10⁻¹⁹ C`,`9 × 10⁹ C`,`1.6 × 10¹⁹ C`,`8.85 × 10⁻¹² C`],a:0,w:`الشحنة الأولية e.`},
{q:`الاتجاه الحقيقي لحركة الإلكترونات داخل الدائرة:`,o:[`من الموجب إلى السالب`,`من السالب إلى الموجب`,`لا اتجاه لها`,`عمودي على السلك`],a:1,w:`أما الاتجاه الاصطلاحي للتيار فمن الموجب للسالب.`},
{q:`عدد الإلكترونات المارة في \`4 s\` إذا كان التيار \`2 A\`:`,o:[`8`,`5 × 10¹⁹`,`1.28 × 10⁻¹⁸`,`3.2 × 10¹⁹`],a:1,w:`q = 8 C ← n = 8/1.6×10⁻¹⁹ = 5×10¹⁹.`}
]},
/* 4-2 كثافة التيار */
{s:`### كثافة التيار J
- شدة التيار المار لكل وحدة مساحة من مقطع الموصل.
\`J = I / A\` ← الوحدة \`A/m²\`
- كمية **متجهة** في اتجاه التيار.
### تحويل المساحة (مهم جدًا)
- \`1 mm² = 10⁻⁶ m²\` · \`1 cm² = 10⁻⁴ m²\`
- مساحة مقطع دائري: \`A = π·r²\`
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: كثافة التيار في موصل دائري المقطع
- **السؤال:** موصل مساحة مقطعه الدائري \`A = 0.785 × 10⁻⁶ m²\` ويحمل تيارًا مقداره \`I = 1 A\`. أوجد كثافة التيار.
- **المعطيات:** \`I = 1 A\` · \`A = 0.785 × 10⁻⁶ m²\` (المساحة معطاة بالمتر المربع مباشرة، وهي تساوي \`0.785 mm²\` لأن \`1 mm² = 10⁻⁶ m²\`).
- **المطلوب:** كثافة التيار \`J\`.
- **لماذا هذا القانون؟** كثافة التيار تصف مدى «ازدحام» التيار داخل الموصل، أي مقدار التيار الذي يمر عبر كل متر مربع من مساحة المقطع؛ لذلك نقسم التيار على المساحة.
- **القانون:** \`J = I / A\`
- **معنى الرموز:** \`J\` كثافة التيار بوحدة \`A/m²\` وهي كمية متجهة اتجاهها اتجاه التيار · \`I\` شدة التيار بالأمبير · \`A\` مساحة المقطع العمودي على اتجاه التيار بالمتر المربع.
- **الحل:** نعوض: \`J = 1 / (0.785 × 10⁻⁶)\`
- **الحل:** نقسم العددين أولًا: \`1 ÷ 0.785 = 1.274\`
- **الحل:** ثم ننقل القوة العشرية من المقام إلى البسط فتصبح موجبة: \`1 / 10⁻⁶ = 10⁶\`
- **الحل:** إذن: \`J = 1.274 × 10⁶ A/m²\`
- **تحديد الاتجاه:** كثافة التيار متجهة، واتجاهها هو اتجاه التيار الاصطلاحي داخل الموصل (اتجاه حركة الشحنات الموجبة).
- **تفسير النتيجة:** المساحة \`0.785 mm²\` توافق سلكًا نصف قطره \`r = 0.5 mm\` لأن \`π × (0.5 × 10⁻³)² = 0.785 × 10⁻⁶ m²\`؛ ولأن المساحة صغيرة جدًا تكون الكثافة كبيرة رغم أن التيار \`1 A\` فقط.
- **النتيجة:** \`J ≈ 1.274 × 10⁶ A/m²\` ✓
### مثال ٢: حساب التيار ثم كثافته من الشحنة والزمن
- **السؤال:** إذا كان مقدار الشحنة التي تمر على مقطع موصل في زمن قدره \`t = 4 s\` يساوي \`q = 5 C\`، أوجد كلًّا من: التيار الكهربائي، وكثافة التيار علمًا بأن مساحة مقطع الموصل \`A = 2.5 mm²\`.
- **المعطيات:** \`q = 5 C\` · \`t = 4 s\` · \`A = 2.5 mm² = 2.5 × 10⁻⁶ m²\`
- **تحويل الوحدة:** بما أن \`1 mm = 10⁻³ m\` فإن \`1 mm² = (10⁻³ m)² = 10⁻⁶ m²\`، ولذلك \`2.5 mm² = 2.5 × 10⁻⁶ m²\`. هذا التحويل ضروري لأن وحدة الكثافة في النظام الدولي هي \`A/m²\`.
- **المطلوب:** أولًا التيار \`I\`، ثانيًا كثافة التيار \`J\`.
- **خطة الحل:** لا نستطيع حساب الكثافة مباشرة لأنها تحتاج التيار، فنحسب التيار أولًا من تعريفه ثم نستخدمه في قانون الكثافة.
- **القانون:** أولًا \`I = q / t\` · ثانيًا \`J = I / A\`
- **الحل:** أولًا نعوض في قانون التيار: \`I = 5 C / 4 s\`
- **الحل:** \`I = 1.25 A\`
- **الحل:** ثانيًا نعوض بالتيار الناتج والمساحة بعد التحويل: \`J = 1.25 / (2.5 × 10⁻⁶)\`
- **الحل:** نقسم العددين: \`1.25 ÷ 2.5 = 0.5\`، ونقلب القوة: \`1 / 10⁻⁶ = 10⁶\`
- **الحل:** \`J = 0.5 × 10⁶ = 5 × 10⁵ A/m²\`
- **تحديد الاتجاه:** اتجاه \`J\` هو اتجاه التيار الاصطلاحي على طول الموصل.
- **النتيجة:** \`I = 1.25 A\` و \`J = 5 × 10⁵ A/m²\` ✓
`,
ex:{q:`سلك مساحة مقطعه \`1.5 mm²\` يمر فيه تيار \`3 A\`. أوجد كثافة التيار.`,
st:[`\`A = 1.5 mm² = 1.5 × 10⁻⁶ m²\``,`\`J = I/A = 3 / (1.5 × 10⁻⁶)\``,`\`J = 2 × 10⁶ A/m²\``],
a:`\`J = 2 × 10⁶ A/m²\``},
qz:[
{q:`وحدة كثافة التيار:`,o:[`A·m²`,`A/m²`,`A/m`,`C/m²`],a:1,w:`أمبير لكل متر مربع.`},
{q:`موصل مساحة مقطعه \`0.785 × 10⁻⁶ m²\` وتياره \`1 A\`، كثافة التيار:`,o:[`1.274 × 10⁶ A/m²`,`7.85 × 10⁻⁷ A/m²`,`1.274 A/m²`,`0.785 A/m²`],a:0,w:`1 / 0.785×10⁻⁶ ≈ 1.274×10⁶ A/m².`},
{q:`\`2.5 mm²\` تساوي:`,o:[`2.5 × 10⁻³ m²`,`2.5 × 10⁻⁶ m²`,`2.5 × 10⁻⁴ m²`,`250 m²`],a:1,w:`1 mm² = 10⁻⁶ m².`},
{q:`كثافة التيار كمية:`,o:[`قياسية`,`متجهة`,`بلا وحدة`,`أساسية`],a:1,w:`كما ورد في الحقيبة.`}
]},
/* 4-3 سرعة الانجراف */
{s:`### سرعة الانجراف v_d
- السرعة المتوسطة لحركة الإلكترونات بتأثير المجال الكهربائي داخل الموصل.
- صغيرة جدًا (أجزاء من المليمتر في الثانية) بسبب التصادمات المتكررة مع ذرات الموصل.
\`v_d = J / (n·e)\`
- \`n\`: عدد الإلكترونات الحرة لكل متر مكعب · \`e = 1.6 × 10⁻¹⁹ C\`
### لماذا يضيء المصباح فورًا إذن؟
- لأن المجال الكهربائي ينتشر في السلك بسرعة قريبة من سرعة الضوء، فتبدأ كل الإلكترونات بالانجراف في الوقت نفسه تقريبًا.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: كثافة التيار وسرعة الانجراف في سلك فضة
- **السؤال:** موصل من مادة الفضة مساحة مقطعه الدائري \`A = 0.785 mm²\` ويحمل تيارًا \`I = 1 A\`، وعدد الإلكترونات الحرة لوحدة الحجم \`n = 5.8 × 10²⁸ electron/m³\`. احسب كثافة التيار وسرعة الإلكترونات المتحركة داخل الموصل.
- **المعطيات:** \`I = 1 A\` · \`A = 0.785 mm² = 0.785 × 10⁻⁶ m²\` · \`n = 5.8 × 10²⁸ m⁻³\` · \`e = 1.6 × 10⁻¹⁹ C\`
- **تحويل الوحدة:** \`1 mm² = 10⁻⁶ m²\` ولذلك \`0.785 mm² = 0.785 × 10⁻⁶ m²\`.
- **المطلوب:** كثافة التيار \`J\` ثم سرعة الانجراف \`v_d\`.
- **لماذا هذان القانونان؟** سرعة الانجراف تعتمد على كثافة التيار: كلما زاد التيار المار في كل متر مربع زادت سرعة الإلكترونات، وكلما زاد عدد الإلكترونات الحرة \`n\` قلّت السرعة اللازمة لنقل التيار نفسه؛ لذلك نحسب \`J\` أولًا ثم نقسمها على \`n·e\`.
- **القانون:** \`J = I / A\` ثم \`v_d = J / (n·e)\`
- **معنى الرموز:** \`v_d\` سرعة الانجراف بوحدة \`m/s\` · \`n\` عدد الإلكترونات الحرة في كل متر مكعب من الموصل · \`e\` شحنة الإلكترون الواحد بالكولوم · \`n·e\` مقدار الشحنة الحرة في كل متر مكعب بوحدة \`C/m³\`.
- **الحل:** الخطوة الأولى (الكثافة): \`J = 1 / (0.785 × 10⁻⁶)\`
- **الحل:** \`J = 1.274 × 10⁶ A/m²\`
- **الحل:** الخطوة الثانية (المقام): \`n·e = 5.8 × 10²⁸ × 1.6 × 10⁻¹⁹\`
- **الحل:** نضرب العددين \`5.8 × 1.6 = 9.28\` ونجمع الأسس \`28 + (−19) = 9\`، إذن \`n·e = 9.28 × 10⁹ C/m³\`
- **الحل:** الخطوة الثالثة (القسمة): \`v_d = 1.274 × 10⁶ / (9.28 × 10⁹)\`
- **الحل:** نقسم العددين \`1.274 ÷ 9.28 = 0.1373\` ونطرح الأسس \`6 − 9 = −3\`، إذن \`v_d = 0.1373 × 10⁻³ m/s\`
- **الحل:** وبالصيغة العلمية: \`v_d ≈ 1.37 × 10⁻⁴ m/s\`
- **التحقق من الوحدات:** \`(A/m²) ÷ (C/m³) = (C/s·m²) × (m³/C) = m/s\` ✓
- **تحديد الاتجاه:** الإلكترونات سالبة الشحنة، لذلك تنجرف في عكس اتجاه التيار الاصطلاحي وعكس اتجاه المجال الكهربائي داخل السلك.
- **تفسير النتيجة:** \`1.37 × 10⁻⁴ m/s\` تعادل نحو \`0.14 mm\` في الثانية فقط، وهذا يؤكد أن سرعة الانجراف صغيرة جدًا بسبب التصادمات المتكررة مع ذرات الموصل.
- **النتيجة:** \`J ≈ 1.274 × 10⁶ A/m²\` و \`v_d ≈ 1.37 × 10⁻⁴ m/s\` ✓
`,
ex:{q:`(مثال الحقيبة) سلك فضة مقطعه \`0.785 mm²\` يحمل \`1 A\`، و \`n = 5.8 × 10²⁸ إلكترون/m³\`. أوجد كثافة التيار وسرعة الانجراف.`,
st:[`\`J = 1 / (0.785 × 10⁻⁶) ≈ 1.274 × 10⁶ A/m²\``,`\`n·e = 5.8 × 10²⁸ × 1.6 × 10⁻¹⁹ = 9.28 × 10⁹\``,`\`v_d = 1.274 × 10⁶ / 9.28 × 10⁹\``,`\`v_d ≈ 1.37 × 10⁻⁴ m/s\``],
a:`\`J ≈ 1.27 × 10⁶ A/m²\` و \`v_d ≈ 1.4 × 10⁻⁴ m/s\` (حوالي 0.14 mm/s)`},
qz:[
{q:`سرعة الانجراف للإلكترونات في الموصلات:`,o:[`كبيرة جدًا تقارب سرعة الضوء`,`صغيرة جدًا`,`صفر دائمًا`,`لا نهائية`],a:1,w:`بسبب التصادمات المتكررة.`},
{q:`قانون سرعة الانجراف:`,o:[`v_d = J·n·e`,`v_d = J/(n·e)`,`v_d = n·e/J`,`v_d = I·A`],a:1,w:`v_d = J/(ne).`},
{q:`سبب صغر سرعة الانجراف:`,o:[`قلة الإلكترونات`,`التصادمات مع ذرات الموصل`,`ضعف المصدر`,`كبر شحنة الإلكترون`],a:1,w:`كما ورد في الحقيبة.`},
{q:`إذا زادت كثافة التيار في نفس الموصل فإن سرعة الانجراف:`,o:[`تزداد`,`تقل`,`لا تتغير`,`تنعدم`],a:0,w:`v_d ∝ J.`}
]},
/* 4-4 أنواع التيارات */
{s:`### التيار المستمر DC
- يسري دائمًا في **اتجاه واحد**.
- أمثلة: البطاريات، شواحن الجوال من جهة الجهاز، الخلايا الشمسية.
### التيار المتردد AC
- يتغير اتجاهه **دوريًا مع الزمن**.
- أمثلة: كهرباء المنازل (في السعودية: \`220 V\` تقريبًا وتردد \`60 Hz\`، أي يغير اتجاهه 120 مرة في الثانية).
### لماذا AC في الشبكات؟
- يسهل رفع جهده وخفضه بالمحولات، فينقل لمسافات بعيدة بفقد أقل.`,
ex:{q:`صنّف مصدر التيار: (أ) بطارية سيارة، (ب) مقبس الجدار، (ج) لوح شمسي.`,
st:[`(أ) قطبان ثابتان + و − ← مستمر DC.`,`(ب) الشبكة الكهربائية ← متردد AC.`,`(ج) الخلية الشمسية تنتج جهدًا ثابت الإشارة ← مستمر DC (ويُحول لاحقًا بعاكس إلى AC).`],
a:`(أ) DC، (ب) AC، (ج) DC`},
qz:[
{q:`التيار الذي يتغير اتجاهه مع الزمن:`,o:[`المستمر`,`المتردد`,`الساكن`,`المنتظم`],a:1,w:`AC.`},
{q:`تيار البطارية:`,o:[`مستمر`,`متردد`,`لا يعد تيارًا`,`متغير الاتجاه`],a:0,w:`DC.`},
{q:`الرمز DC يعني:`,o:[`التيار المتردد`,`التيار المستمر`,`فرق الجهد`,`المقاومة`],a:1,w:`Direct Current.`},
{q:`يتميز التيار المستمر DC بأنه:`,o:[`يغير اتجاهه 60 مرة في الثانية`,`يسري في اتجاه واحد`,`لا يحمل طاقة`,`لا يوجد إلا في المنازل`],a:1,w:`مثل تيار البطارية.`}
]},
/* 4-5 المقاومة وقانون أوم */
{s:`### المقاومة R
- ممانعة الموصل لمرور التيار، وينتج عنها ارتفاع في درجة حرارته.
- الوحدة: الأوم \`Ω = V/A\`.
- فائدتها: التحكم في شدة التيار وحماية الدوائر الإلكترونية.
### قانون أوم
- عند ثبوت درجة الحرارة يتناسب التيار المار في موصل طرديًا مع فرق الجهد بين طرفيه:
\`V = I·R\` ← \`I = V/R\` ← \`R = V/I\`
- منحنى (V مقابل I) خط مستقيم ميله يساوي المقاومة.`,
ex:{q:`مصباح سيارة يعمل على \`12 V\` ومقاومته \`4 Ω\`. أوجد التيار. ثم أوجد المقاومة إذا مر \`2 A\` تحت \`230 V\`.`,
st:[`\`I = V/R = 12/4 = 3 A\``,`\`R = V/I = 230/2 = 115 Ω\``],
a:`\`I = 3 A\` و \`R = 115 Ω\``},
qz:[
{q:`سخان على \`120 V\` يمر فيه \`8 A\`، مقاومته:`,o:[`960 Ω`,`15 Ω`,`0.067 Ω`,`128 Ω`],a:1,w:`120/8 = 15 Ω.`},
{q:`مقاومة \`10 Ω\` على \`220 V\`، التيار:`,o:[`2200 A`,`22 A`,`0.045 A`,`210 A`],a:1,w:`220/10 = 22 A.`},
{q:`كلما زاد الجهد بين طرفي موصل (بثبات المقاومة) فإن التيار:`,o:[`يزداد`,`يقل`,`لا يتغير`,`ينعكس`],a:0,w:`I = V/R.`},
{q:`وحدة المقاومة في SI:`,o:[`V·A`,`V/A`,`A/V`,`J/s`],a:1,w:`الأوم = فولت/أمبير.`}
]},
/* 4-6 المقاومة النوعية وأثر الحرارة */
{s:`### العوامل المؤثرة في المقاومة
- نوع المادة، الطول (طرديًا)، مساحة المقطع (عكسيًا)، درجة الحرارة.
\`R = ρ·L / A\`
- \`ρ\` المقاومة النوعية (المقاومية) ووحدتها \`Ω·m\` وتعتمد على نوع المادة فقط.
- **الموصلية** \`σ = 1/ρ\` ووحدتها \`(Ω·m)⁻¹\`.
### أثر درجة الحرارة (للموصلات)
\`R = R₀·(1 + α·(T − T₀))\`
- \`α\` المعامل الحراري للمقاومة بوحدة \`°C⁻¹\`. المقاومة تزيد بارتفاع الحرارة.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: مقاومة سخان كهربائي بقانون أوم
- **السؤال:** فرق الجهد بين طرفي سخان كهربائي \`V = 120 V\` وكانت شدة التيار المار فيه \`I = 8 A\`. احسب مقاومة السخان.
- **المعطيات:** \`V = 120 V\` · \`I = 8 A\`
- **المطلوب:** مقاومة السخان \`R\`.
- **لماذا هذا القانون؟** قانون أوم يربط الكميات الثلاث (الجهد والتيار والمقاومة) عند ثبوت درجة الحرارة؛ ولدينا اثنتان منها فنستخرج الثالثة.
- **القانون:** \`V = I·R\` ومنه \`R = V / I\`
- **معنى الرموز:** \`V\` فرق الجهد بين طرفي العنصر بالفولت · \`I\` التيار المار فيه بالأمبير · \`R\` مقاومته بالأوم \`Ω = V/A\`.
- **الحل:** نعوض: \`R = 120 V / 8 A\`
- **الحل:** \`R = 15 V/A = 15 Ω\`
- **التحقق:** \`I·R = 8 × 15 = 120 V\` وهو الجهد المعطى.
- **النتيجة:** مقاومة السخان \`R = 15 Ω\` ✓
### مثال ٢: شدة التيار في مقاومة بقانون أوم
- **السؤال:** أوجد شدة التيار المار في مقاومة \`R = 10 Ω\` وفرق الجهد بين طرفيها \`V = 220 V\`.
- **المعطيات:** \`R = 10 Ω\` · \`V = 220 V\`
- **المطلوب:** شدة التيار \`I\`.
- **لماذا هذا القانون؟** التيار يتناسب طرديًا مع الجهد وعكسيًا مع المقاومة، وهذا هو مضمون قانون أوم بعد إعادة ترتيبه لعزل \`I\`.
- **القانون:** \`I = V / R\`
- **الحل:** نعوض: \`I = 220 V / 10 Ω\`
- **الحل:** \`I = 22 A\`
- **تفسير النتيجة:** مقاومة صغيرة على جهد المنزل \`220 V\` تسحب تيارًا كبيرًا، ولهذا تُصمَّم أجهزة التسخين بأسلاك وقواطع تتحمل تيارات عالية.
- **النتيجة:** \`I = 22 A\` ✓
### مثال ٣: مقاومة سلك نحاس من أبعاده
- **السؤال:** أوجد مقاومة سلك من النحاس يمر به تيار مقداره \`1 A\` إذا كان طوله \`L = 1 m\` ومساحة مقطعه \`A = 1.96 × 10⁻⁵ m²\` ومقاومية النحاس \`ρ = 1.77 × 10⁻⁸ Ω·m\`.
- **المعطيات:** \`L = 1 m\` · \`A = 1.96 × 10⁻⁵ m²\` · \`ρ = 1.77 × 10⁻⁸ Ω·m\` · \`I = 1 A\` (قيمة التيار لا تدخل في الحساب لأن المقاومة خاصية للموصل نفسه).
- **المطلوب:** مقاومة السلك \`R\`.
- **لماذا هذا القانون؟** لا نعرف الجهد، لكننا نعرف نوع المادة وأبعاد السلك؛ والمقاومة تتناسب طرديًا مع الطول وعكسيًا مع مساحة المقطع، وثابت التناسب هو المقاومية.
- **القانون:** \`R = ρ·L / A\`
- **معنى الرموز:** \`ρ\` المقاومة النوعية (المقاومية) وتعتمد على نوع المادة فقط · \`L\` طول الموصل بالمتر · \`A\` مساحة مقطعه بالمتر المربع.
- **الحل:** البسط: \`ρ·L = 1.77 × 10⁻⁸ × 1 = 1.77 × 10⁻⁸ Ω·m²\`
- **الحل:** القسمة على المقام: \`R = 1.77 × 10⁻⁸ / (1.96 × 10⁻⁵)\`
- **الحل:** نقسم العددين \`1.77 ÷ 1.96 = 0.903\` ونطرح الأسس \`−8 − (−5) = −3\`
- **الحل:** \`R = 0.903 × 10⁻³ = 9.03 × 10⁻⁴ Ω\`
- **تفسير النتيجة:** المقاومة صغيرة جدًا (أقل من واحد من الألف من الأوم)؛ لأن النحاس موصل ممتاز والسلك قصير ومقطعه كبير نسبيًا، ولهذا يستخدم النحاس في أسلاك التوصيل.
- **النتيجة:** \`R ≈ 9.03 × 10⁻⁴ Ω\` ✓
### مثال ٤: أثر ارتفاع درجة الحرارة على مقاومة سلك نحاس
- **السؤال:** كانت مقاومة سلك من النحاس عند \`20 °C\` تساوي \`18 Ω\`، فما هي مقاومة السلك عند \`60 °C\` علمًا بأن المعامل الحراري يساوي \`α = 3.9 × 10⁻³ °C⁻¹\`؟
- **المعطيات:** \`R₀ = 18 Ω\` عند \`T₀ = 20 °C\` · \`T = 60 °C\` · \`α = 3.9 × 10⁻³ °C⁻¹\`
- **المطلوب:** المقاومة \`R\` عند \`60 °C\`.
- **لماذا هذا القانون؟** في الموصلات تزداد اهتزازات الذرات بارتفاع الحرارة فتكثر تصادمات الإلكترونات وتزيد المقاومة زيادة خطية تقريبًا مع فرق الحرارة.
- **القانون:** \`R = R₀·(1 + α·(T − T₀))\`
- **معنى الرموز:** \`R₀\` المقاومة عند درجة الحرارة المرجعية \`T₀\` · \`R\` المقاومة عند درجة الحرارة الجديدة \`T\` · \`α\` المعامل الحراري للمقاومة ويعني الزيادة النسبية في المقاومة لكل درجة مئوية.
- **الحل:** فرق درجات الحرارة: \`ΔT = T − T₀ = 60 − 20 = 40 °C\`
- **الحل:** الزيادة النسبية: \`α·ΔT = 3.9 × 10⁻³ × 40 = 0.156\`
- **الحل:** ما بين القوسين: \`1 + 0.156 = 1.156\`
- **الحل:** \`R = 18 × 1.156 = 20.808 Ω\`
- **تفسير النتيجة:** زادت المقاومة بمقدار \`18 × 0.156 = 2.808 Ω\` أي بنسبة \`15.6 %\` بسبب ارتفاع الحرارة \`40 °C\`.
- **النتيجة:** \`R ≈ 20.81 Ω\` ✓
`,
ex:{q:`(أ) سلك نحاس طوله \`10 m\` ومقطعه \`1 mm²\` (\`ρ = 1.7 × 10⁻⁸ Ω·m\`). أوجد مقاومته. (ب) مقاومة \`50 Ω\` عند \`20°C\` و \`α = 4 × 10⁻³ °C⁻¹\`. أوجد مقاومتها عند \`70°C\`.`,
st:[`(أ) \`R = (1.7 × 10⁻⁸)(10) / (1 × 10⁻⁶)\``,`\`R = 1.7 × 10⁻⁷ / 10⁻⁶ = 0.17 Ω\``,`(ب) \`R = 50(1 + 4 × 10⁻³ × 50)\``,`\`R = 50(1 + 0.2) = 60 Ω\``],
a:`(أ) \`0.17 Ω\` (ب) \`60 Ω\``},
qz:[
{q:`تقل مقاومة الموصل بزيادة:`,o:[`طوله`,`مساحة مقطعه`,`درجة حرارته`,`مقاوميته`],a:1,w:`R ∝ 1/A.`},
{q:`وحدة المقاومة النوعية:`,o:[`Ω`,`Ω·m`,`Ω/m`,`m/Ω`],a:1,w:`ρ = R·A/L ← Ω·m²/m = Ω·m.`},
{q:`سلك نحاس مقاومته \`18 Ω\` عند \`20°C\`، و \`α = 3.9 × 10⁻³\`، مقاومته عند \`60°C\`:`,o:[`20.81 Ω`,`18.16 Ω`,`22.21 Ω`,`15.19 Ω`],a:0,w:`18(1 + 0.0039 × 40) = 18 × 1.156 = 20.81 Ω.`},
{q:`إذا تضاعف طول السلك (بنفس المقطع) فإن مقاومته:`,o:[`تتضاعف`,`تقل للنصف`,`تتضاعف أربع مرات`,`لا تتغير`],a:0,w:`R ∝ L.`},
{q:`مقلوب المقاومية يسمى:`,o:[`الموصلية`,`السعة`,`المعاوقة`,`المقاومة الكلية`],a:0,w:`σ = 1/ρ.`}
]},
/* 4-7 القدرة الكهربائية */
{s:`### القدرة الكهربائية P
- الطاقة المستهلكة في وحدة الزمن: \`P = E / t\` ← الوحدة الواط \`W = J/s\`
### صيغ القدرة
- \`P = I·V\`
- \`P = I²·R\` (باستخدام V = IR)
- \`P = V² / R\`
### الطاقة المستهلكة وفاتورة الكهرباء
- \`E = P·t\` وتقاس تجاريًا بالكيلوواط·ساعة \`kWh\`.
- \`1 kWh = 3.6 × 10⁶ J\`
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: تيار مصباح وقدرته الكهربائية
- **السؤال:** مصباح كهربائي مقاومته \`R = 20 Ω\` ويعمل على فرق جهد مقداره \`V = 10 V\`. احسب: شدة التيار المار فيه، والقدرة الكهربائية.
- **المعطيات:** \`R = 20 Ω\` · \`V = 10 V\`
- **المطلوب:** أولًا التيار \`I\`، ثانيًا القدرة \`P\`.
- **خطة الحل:** نحسب التيار بقانون أوم، ثم نستخدمه مع الجهد في قانون القدرة.
- **القانون:** أولًا \`I = V / R\` · ثانيًا \`P = I·V\`
- **معنى الرموز:** \`P\` القدرة الكهربائية، أي الطاقة المستهلكة في كل ثانية، ووحدتها الواط \`W = J/s\` · \`I\` التيار بالأمبير · \`V\` الجهد بالفولت.
- **الحل:** أولًا: \`I = 10 V / 20 Ω = 0.5 A\`
- **الحل:** ثانيًا: \`P = 0.5 A × 10 V = 5 W\`
- **التحقق بالصيغتين الأخريين:** \`P = I²·R = (0.5)² × 20 = 0.25 × 20 = 5 W\` و \`P = V²/R = 10² / 20 = 100 / 20 = 5 W\`، فالصيغ الثلاث تعطي النتيجة نفسها لأنها مشتقة جميعًا من \`P = I·V\` مع قانون أوم.
- **تفسير النتيجة:** المصباح يحوّل \`5 J\` من الطاقة الكهربائية إلى ضوء وحرارة في كل ثانية.
- **النتيجة:** \`I = 0.5 A\` و \`P = 5 W\` ✓
`,
ex:{q:`سخان ماء قدرته \`1100 W\` يعمل على \`220 V\`. أوجد التيار والمقاومة، والطاقة المستهلكة في \`2 h\`.`,
st:[`\`I = P/V = 1100/220 = 5 A\``,`\`R = V/I = 220/5 = 44 Ω\``,`\`E = P·t = 1.1 kW × 2 h = 2.2 kWh\``],
a:`\`I = 5 A\`، \`R = 44 Ω\`، \`E = 2.2 kWh\``},
qz:[
{q:`مصباح مقاومته \`20 Ω\` على \`10 V\`، قدرته:`,o:[`200 W`,`5 W`,`2 W`,`0.5 W`],a:1,w:`P = V²/R = 100/20 = 5 W.`},
{q:`وحدة القدرة:`,o:[`الجول`,`الواط`,`الأمبير`,`الكيلوواط·ساعة`],a:1,w:`الواط = جول/ثانية. (kWh وحدة طاقة)`},
{q:`مقاومة \`10 Ω\` يمر فيها \`2 A\`، القدرة المستهلكة:`,o:[`20 W`,`40 W`,`5 W`,`12 W`],a:1,w:`P = I²R = 4 × 10 = 40 W.`},
{q:`مكيف \`2 kW\` يعمل \`5 h\`، الطاقة المستهلكة:`,o:[`10 kWh`,`2.5 kWh`,`7 kWh`,`0.4 kWh`],a:0,w:`2 × 5 = 10 kWh.`}
]},
/* 4-8 توصيل المقاومات */
{s:`### التوصيل على التوالي
- **التيار واحد** في كل المقاومات: \`I = I₁ = I₂ = I₃\`
- الجهد يتجزأ: \`V = V₁ + V₂ + V₃\` حيث \`V = I·R\`
- \`R_total = R₁ + R₂ + R₃\`
[[fig:cirSeries]]
### التوصيل على التوازي
- **الجهد واحد** على كل المقاومات: \`V = V₁ = V₂ = V₃\`
- التيار يتوزع: \`I = I₁ + I₂ + I₃\` حيث \`I = V/R\`
- \`1/R_total = 1/R₁ + 1/R₂ + 1/R₃\`
- حالة خاصة لمقاومتين فقط: \`R = R₁R₂/(R₁ + R₂)\`
- المقاومة المكافئة **أصغر** من أصغر مقاومة.
[[fig:cirParallel]]
### تذكّر
- أجهزة المنزل توصل على التوازي لتعمل كلها على \`220 V\` ولا تتأثر بإطفاء أحدها.
### أمثلة الحقيبة محلولة بالتفصيل
### مثال ١: مقاومتان على التوالي
- **السؤال:** مقاومتان مقدارهما \`5 Ω\` و \`9 Ω\` وصلتا على التوالي، إذا كان يمر فيهما تيار \`I = 2 A\` أوجد: المقاومة الكلية، وفرق الجهد عبر كل مقاومة، وفرق الجهد الكلي.
- **المعطيات:** \`R₁ = 9 Ω\` · \`R₂ = 5 Ω\` · \`I = 2 A\` (لا توجد مقاومة ثالثة، أي \`R₃ = 0\`).
- **المطلوب:** \`R_total\` · \`V₁\` · \`V₂\` · \`V\`
- **لماذا هذه القوانين؟** في التوالي يوجد مسار واحد فقط للشحنات، فيمر **التيار نفسه** في كل المقاومات \`I = I₁ = I₂ = I₃\`، بينما يتوزع جهد المصدر عليها، وتجمع المقاومات جمعًا مباشرًا لأن الشحنة تعبرها جميعًا الواحدة تلو الأخرى.
- **القانون:** \`R_total = R₁ + R₂ + R₃\` · \`V₁ = I·R₁\` · \`V₂ = I·R₂\` · \`V = V₁ + V₂ + V₃\`
- **الحل:** أولًا المقاومة الكلية (مع \`R₃ = 0\`): \`R_total = 9 + 5 = 14 Ω\`
- **الحل:** ثانيًا جهد المقاومة الأولى: \`V₁ = 2 A × 9 Ω = 18 V\`
- **الحل:** جهد المقاومة الثانية: \`V₂ = 2 A × 5 Ω = 10 V\`
- **الحل:** ثالثًا الجهد الكلي: \`V = 18 + 10 = 28 V\`
- **التحقق:** بقانون أوم على الدائرة كلها: \`V = I·R_total = 2 × 14 = 28 V\` ✓ وهو يطابق مجموع الجهود.
- **تفسير النتيجة:** المقاومة الأكبر \`9 Ω\` أخذت الجزء الأكبر من الجهد؛ لأن التيار واحد، فالجهد يتناسب طرديًا مع المقاومة في التوالي.
- **النتيجة:** \`R_total = 14 Ω\` · \`V₁ = 18 V\` · \`V₂ = 10 V\` · \`V = 28 V\` ✓
### مثال ٢: مقاومتان على التوازي
- **السؤال:** مقاومتان \`6 Ω\` و \`3 Ω\` ربطتا على التوازي ثم وصل بين طرفيهما المشتركين فرق جهد \`V = 12 V\`. أوجد: المقاومة الكلية، وشدة التيار الرئيسي، وشدة التيار المار في كل مقاومة.
- **المعطيات:** \`R₁ = 6 Ω\` · \`R₂ = 3 Ω\` · \`V = 12 V\` (لا توجد مقاومة ثالثة، أي يُحذف الحد \`1/R₃\`).
- **المطلوب:** \`R_total\` · \`I\` · \`I₁\` · \`I₂\`
- **لماذا هذه القوانين؟** في التوازي كل مقاومة موصولة مباشرة بين النقطتين نفسيهما، فيكون **الجهد نفسه** على كل منها \`V = V₁ = V₂ = V₃\`، بينما ينقسم التيار الرئيسي بين الفروع \`I = I₁ + I₂ + I₃\`؛ وكل فرع جديد يفتح مسارًا إضافيًا فتقل المقاومة الكلية.
- **القانون:** \`1/R_total = 1/R₁ + 1/R₂ + 1/R₃\`، وفي حالة مقاومتين فقط يصبح: \`R_total = R₁·R₂ / (R₁ + R₂)\`
- **الحل:** أولًا بالقانون العام: \`1/R_total = 1/6 + 1/3 = 1/6 + 2/6 = 3/6 = 1/2\`، إذن \`R_total = 2 Ω\`
- **الحل:** وبقانون الحالة الخاصة للتحقق: البسط \`6 × 3 = 18\` والمقام \`6 + 3 = 9\`، إذن \`R_total = 18 / 9 = 2 Ω\`
- **الحل:** ثانيًا التيار الرئيسي: \`I = V / R_total = 12 / 2 = 6 A\`
- **الحل:** ثالثًا تيار المقاومة الأولى: \`I₁ = V / R₁ = 12 / 6 = 2 A\`
- **الحل:** تيار المقاومة الثانية: \`I₂ = V / R₂ = 12 / 3 = 4 A\`
- **التحقق:** \`I₁ + I₂ = 2 + 4 = 6 A\` وهو يساوي التيار الرئيسي ✓
- **تفسير النتيجة:** المقاومة الكلية \`2 Ω\` أصغر من أصغر مقاومة \`3 Ω\`، والمقاومة الأصغر \`3 Ω\` سحبت التيار الأكبر \`4 A\`؛ لأن الجهد واحد، فالتيار يتناسب عكسيًا مع المقاومة في التوازي.
- **النتيجة:** \`R_total = 2 Ω\` · \`I = 6 A\` · \`I₁ = 2 A\` · \`I₂ = 4 A\` ✓
`,
ex:{q:`مقاومتان \`4 Ω\` و \`12 Ω\` على التوازي مع \`12 V\`. أوجد المقاومة الكلية، والتيار الرئيسي، وتيار كل مقاومة.`,
st:[`\`R = (4 × 12)/(4 + 12) = 48/16 = 3 Ω\``,`\`I = V/R = 12/3 = 4 A\``,`\`I₁ = 12/4 = 3 A\` و \`I₂ = 12/12 = 1 A\``,`تحقق: \`3 + 1 = 4 A\` ✓`],
a:`\`R = 3 Ω\`، \`I = 4 A\`، \`I₁ = 3 A\`، \`I₂ = 1 A\``},
qz:[
{q:`مقاومتان \`9 Ω\` و \`5 Ω\` على التوالي، المقاومة الكلية:`,o:[`14 Ω`,`3.2 Ω`,`4 Ω`,`45 Ω`],a:0,w:`9 + 5 = 14 Ω.`},
{q:`مقاومتان \`6 Ω\` و \`3 Ω\` على التوازي، المقاومة الكلية:`,o:[`9 Ω`,`2 Ω`,`18 Ω`,`4.5 Ω`],a:1,w:`18/9 = 2 Ω.`},
{q:`في التوصيل على التوالي يكون متساويًا في كل المقاومات:`,o:[`الجهد`,`التيار`,`القدرة`,`المقاومة`],a:1,w:`I واحد.`},
{q:`مقاومتان \`9 Ω\` و \`5 Ω\` على التوالي يمر فيهما \`2 A\`، الجهد الكلي:`,o:[`14 V`,`28 V`,`7 V`,`18 V`],a:1,w:`V = I·R = 2 × 14 = 28 V.`},
{q:`المقاومة المكافئة لمقاومات على التوازي:`,o:[`تساوي مجموعها`,`مقلوبها يساوي مجموع مقلوبات المقاومات`,`تساوي حاصل ضربها`,`تساوي أكبر مقاومة`],a:1,w:`1/R = 1/R₁ + 1/R₂ + …`}
]},
/* 4-9 ورقة عمل */
{s:`### ما تحتاجه لحل ورقة العمل
- \`I = q/t\` · \`n = q/e\` · \`J = I/A\`
- أوم: \`V = IR\` · المقاومة: \`R = ρL/A\` · الحرارة: \`R = R₀(1 + αΔT)\`
- القدرة: \`P = IV = I²R = V²/R\` ← للمصباح: \`R = V²/P\` و \`I = P/V\`
- التوالي: \`R = R₁ + R₂\` · التوازي: \`R = R₁R₂/(R₁ + R₂)\`
- **مقاومة مجهولة على التوازي:** \`1/R_x = 1/R_total − 1/R_known\`

### حل ورقة العمل
### سؤال ١: عرّف كلًّا مما يلي
1. **شدة التيار الكهربائي:** هي كمية الشحنة الكهربائية التي تعبر مقطع الموصل في وحدة الزمن (الثانية الواحدة)، وتُعطى بالعلاقة \`I = q ÷ t\` ووحدتها الأمبير \`A\`.
2. **كثافة التيار:** هي شدة التيار المار عبر وحدة المساحات من مقطع الموصل العمودي على اتجاه التيار، وتُعطى بالعلاقة \`J = I ÷ A\` ووحدتها \`A/m²\`.
3. **المقاومة:** هي الممانعة التي يبديها الموصل لمرور التيار الكهربائي فيه، وتساوي النسبة بين فرق الجهد بين طرفي الموصل وشدة التيار المار فيه \`R = V ÷ I\` ووحدتها الأوم \`Ω\`.
4. **القدرة الكهربائية:** هي الطاقة الكهربائية المستهلكة (أو المنقولة) في وحدة الزمن، وتُعطى بالعلاقة \`P = W ÷ t = I · V\` ووحدتها الواط \`W\`.

### سؤال ٢: اذكر نص قانون أوم مع كتابة العلاقة الرياضية
- **نص القانون:** تتناسب شدة التيار الكهربائي المار في موصل فلزي تناسبًا طرديًا مع فرق الجهد بين طرفيه عند ثبوت درجة حرارته.
- **العلاقة الرياضية:** \`V = I · R\` أو \`I = V ÷ R\`
- **حيث:** \`V\` فرق الجهد بالفولت \`V\`، و\`I\` شدة التيار بالأمبير \`A\`، و\`R\` المقاومة بالأوم \`Ω\` وهي ثابت التناسب.

### سؤال ٣: احسب عدد الإلكترونات التي تمر في موصل خلال 4 s إذا كانت شدة التيار 2 A
- **المعطيات:** \`t = 4 s\` · \`I = 2 A\` · \`e = 1.6 × 10⁻¹⁹ C\`
- **المطلوب:** عدد الإلكترونات \`n\`
- **القانون:** \`q = I · t\` و \`q = n · e\` ومنه \`n = (I · t) ÷ e\`
- **الحل:** \`q = 2 × 4 = 8 C\`
- **الحل:** \`n = 8 ÷ (1.6 × 10⁻¹⁹) = 5 × 10¹⁹ إلكترون\`
- **النتيجة:** عدد الإلكترونات \`n = 5 × 10¹⁹\` إلكترون ✓

### سؤال ٤: موصل مساحة مقطعه الدائري 8 × 10⁻⁷ m² يمر فيه تيار 5.2 × 10⁻³ A، أوجد كثافة التيار
- **المعطيات:** \`A = 8 × 10⁻⁷ m²\` · \`I = 5.2 × 10⁻³ A\`
- **المطلوب:** كثافة التيار \`J\`
- **القانون:** \`J = I ÷ A\`
- **الحل:** \`J = (5.2 × 10⁻³) ÷ (8 × 10⁻⁷)\`
- **الحل:** \`J = 0.65 × 10⁴ = 6500 A/m²\`
- **النتيجة:** كثافة التيار \`J = 6.5 × 10³ A/m²\` ✓

### سؤال ٥: ما مقاومة سلك عند 500°C إذا كانت مقاومته عند 20°C هي 1 × 10⁻⁴ Ω والمعامل الحراري لمادته 6.5 × 10⁻³ °C⁻¹
- **المعطيات:** \`R₀ = 1 × 10⁻⁴ Ω\` · \`T₀ = 20 °C\` · \`T = 500 °C\` · \`α = 6.5 × 10⁻³ °C⁻¹\`
- **المطلوب:** المقاومة \`R\` عند \`500 °C\`
- **القانون:** \`R = R₀ · (1 + α · ΔT)\`
- **الحل:** \`ΔT = T − T₀ = 500 − 20 = 480 °C\`
- **الحل:** \`α · ΔT = 6.5 × 10⁻³ × 480 = 3.12\`
- **الحل:** \`R = 1 × 10⁻⁴ × (1 + 3.12) = 1 × 10⁻⁴ × 4.12\`
- **النتيجة:** \`R = 4.12 × 10⁻⁴ Ω\` ✓

### سؤال ٦: موصل من النحاس طوله 2 m ومساحة مقطعه 5.03 × 10⁻⁵ m² ومقاومته النوعية 1.756 × 10⁻⁸ Ω·m، أوجد مقاومته
- **المعطيات:** \`L = 2 m\` · \`A = 5.03 × 10⁻⁵ m²\` · \`ρ = 1.756 × 10⁻⁸ Ω·m\`
- **المطلوب:** مقاومة الموصل \`R\`
- **القانون:** \`R = ρ · L ÷ A\`
- **الحل:** \`R = (1.756 × 10⁻⁸ × 2) ÷ (5.03 × 10⁻⁵)\`
- **الحل:** \`R = (3.512 × 10⁻⁸) ÷ (5.03 × 10⁻⁵) = 0.698 × 10⁻³ Ω\`
- **النتيجة:** \`R ≈ 6.98 × 10⁻⁴ Ω\` ✓

### سؤال ٧: مصباح قدرته 60 W يعمل على جهد 127 V، احسب مقاومته وشدة التيار المار فيه
- **المعطيات:** \`P = 60 W\` · \`V = 127 V\`
- **المطلوب:** المقاومة \`R\` وشدة التيار \`I\`
- **القانون:** \`P = V² ÷ R\` ومنه \`R = V² ÷ P\` و \`P = I · V\` ومنه \`I = P ÷ V\`
- **الحل:** \`R = (127)² ÷ 60 = 16129 ÷ 60 ≈ 268.8 Ω\`
- **الحل:** \`I = 60 ÷ 127 ≈ 0.472 A\`
- **الحل:** للتحقق \`V = I · R = 0.472 × 268.8 ≈ 127 V\`
- **النتيجة:** مقاومة المصباح \`R ≈ 268.8 Ω\` وشدة التيار \`I ≈ 0.47 A\` ✓

### سؤال ٨: مقاومتان 9 Ω و 6 Ω على التوازي وُصل طرفاهما بفرق جهد 18 V
- **المعطيات:** \`R₁ = 9 Ω\` · \`R₂ = 6 Ω\` · \`V = 18 V\` (التوصيل على التوازي)
- **المطلوب:** المقاومة الكلية، والتيار الرئيسي، والتيار في كل مقاومة
- **القانون:** \`1 ÷ Rₜ = 1 ÷ R₁ + 1 ÷ R₂\` و \`I = V ÷ R\`
- **الحل (١) المقاومة الكلية:** \`1 ÷ Rₜ = 1 ÷ 9 + 1 ÷ 6 = 2 ÷ 18 + 3 ÷ 18 = 5 ÷ 18\`
- **الحل:** \`Rₜ = 18 ÷ 5 = 3.6 Ω\` (أو \`Rₜ = (R₁ · R₂) ÷ (R₁ + R₂) = 54 ÷ 15 = 3.6 Ω\`)
- **الحل (٢) التيار الرئيسي:** \`I = V ÷ Rₜ = 18 ÷ 3.6 = 5 A\`
- **الحل (٣) التيار في كل مقاومة:** الجهد متساوٍ على المقاومتين \`18 V\`
- **الحل:** \`I₁ = V ÷ R₁ = 18 ÷ 9 = 2 A\`
- **الحل:** \`I₂ = V ÷ R₂ = 18 ÷ 6 = 3 A\`
- **الحل:** للتحقق \`I₁ + I₂ = 2 + 3 = 5 A = I\`
- **النتيجة:** \`Rₜ = 3.6 Ω\` و \`I = 5 A\` و \`I₁ = 2 A\` و \`I₂ = 3 A\` ✓

### سؤال ٩: مقاومتان 1 Ω و 4 Ω على التوالي وُصل طرفاهما بفرق جهد 10 V
- **المعطيات:** \`R₁ = 1 Ω\` · \`R₂ = 4 Ω\` · \`V = 10 V\` (التوصيل على التوالي)
- **المطلوب:** المقاومة الكلية، والتيار الكهربائي، وفرق الجهد عبر كل مقاومة
- **القانون:** \`Rₜ = R₁ + R₂\` و \`I = V ÷ Rₜ\` و \`V = I · R\`
- **الحل (١) المقاومة الكلية:** \`Rₜ = 1 + 4 = 5 Ω\`
- **الحل (٢) التيار الكهربائي:** \`I = 10 ÷ 5 = 2 A\` (التيار نفسه يمر في المقاومتين)
- **الحل (٣) فرق الجهد عبر كل مقاومة:** \`V₁ = I · R₁ = 2 × 1 = 2 V\`
- **الحل:** \`V₂ = I · R₂ = 2 × 4 = 8 V\`
- **الحل:** للتحقق \`V₁ + V₂ = 2 + 8 = 10 V = V\`
- **النتيجة:** \`Rₜ = 5 Ω\` و \`I = 2 A\` و \`V₁ = 2 V\` و \`V₂ = 8 V\` ✓

### سؤال ١٠: ما قيمة المقاومة التي إذا وُصلت على التوازي مع مقاومة 300 Ω تصبح المقاومة الكلية 75 Ω
- **المعطيات:** \`R₁ = 300 Ω\` · \`Rₜ = 75 Ω\` (التوصيل على التوازي)
- **المطلوب:** المقاومة المجهولة \`R₂\`
- **القانون:** \`1 ÷ Rₜ = 1 ÷ R₁ + 1 ÷ R₂\` ومنه \`1 ÷ R₂ = 1 ÷ Rₜ − 1 ÷ R₁\`
- **الحل:** \`1 ÷ R₂ = 1 ÷ 75 − 1 ÷ 300 = 4 ÷ 300 − 1 ÷ 300 = 3 ÷ 300 = 1 ÷ 100\`
- **الحل:** \`R₂ = 100 Ω\`
- **الحل:** للتحقق \`Rₜ = (300 × 100) ÷ (300 + 100) = 30000 ÷ 400 = 75 Ω\`
- **النتيجة:** \`R₂ = 100 Ω\` ✓
`,
ex:{q:`(مثال مشابه) ما المقاومة التي إذا وُصلت على التوازي مع \`60 Ω\` تصبح المقاومة الكلية \`20 Ω\`؟`,
st:[`\`1/R_x = 1/20 − 1/60\``,`\`1/R_x = 3/60 − 1/60 = 2/60\``,`\`R_x = 60/2 = 30 Ω\``,`تحقق: \`(60 × 30)/(60 + 30) = 1800/90 = 20 Ω\` ✓`],
a:`\`R_x = 30 Ω\``},
qz:[
{q:`مقاومتان \`9 Ω\` و \`6 Ω\` على التوازي، المقاومة الكلية:`,o:[`15 Ω`,`3.6 Ω`,`54 Ω`,`1.5 Ω`],a:1,w:`54/15 = 3.6 Ω.`},
{q:`مقاومتان \`1 Ω\` و \`4 Ω\` على التوالي مع \`10 V\`، التيار:`,o:[`2 A`,`10 A`,`50 A`,`0.5 A`],a:0,w:`R = 5 Ω ← I = 10/5 = 2 A.`},
{q:`مصباح \`100 W\` يعمل على \`220 V\`، مقاومته تقريبًا:`,o:[`484 Ω`,`2.2 Ω`,`22000 Ω`,`0.45 Ω`],a:0,w:`R = V²/P = 48400/100 = 484 Ω.`},
{q:`سلك نحاس \`2 m\` ومقطعه \`5 × 10⁻⁵ m²\` و \`ρ = 1.75 × 10⁻⁸\`، مقاومته:`,o:[`7 × 10⁻⁴ Ω`,`1.75 × 10⁻⁸ Ω`,`7 × 10⁻⁸ Ω`,`3.5 Ω`],a:0,w:`1.75×10⁻⁸ × 2 / 5×10⁻⁵ = 3.5×10⁻⁸/5×10⁻⁵ = 7×10⁻⁴ Ω.`}
]},
/* 4-10 تمارين الوحدة */
{s:`### مراجعة الوحدة الخامسة
- **التيار:** \`I = q/t\` (أمبير = كولوم في **الثانية** الواحدة) · \`q = ne\`
- **كثافة التيار:** \`J = I/A\` (\`A/m²\`) · **الانجراف:** \`v_d = J/(ne)\`
- **أوم:** \`V = IR\` عند ثبوت الحرارة · \`Ω = V/A\`
- **المقاومة:** \`R = ρL/A\` · تقل بزيادة المقطع، وتزيد بالطول والحرارة.
- **القدرة:** \`P = IV = I²R = V²/R\`
- **التوالي:** تيار واحد، \`R = ΣR\` لتجزئة الجهد · **التوازي:** جهد واحد، \`1/R = Σ(1/R)\` للحفاظ على الجهد.
- **الاتجاه:** الاصطلاحي من + إلى −، والحقيقي للإلكترونات من − إلى +.
### تصحيح شائع
- التوصيل المركب = خليط من التوالي والتوازي، وليس التوازي وحده.
### تمارين الوحدة محلولة
### سؤال ١: حركة الإلكترونات الحرة في المعادن
- **السؤال:** تعد المعادن مواد موصلة للكهرباء، وذلك بسبب امتلاكها أعدادًا هائلة من الإلكترونات الحرة القادرة على التحرك من مكان إلى آخر داخل المادة، ولكن حركة هذه الإلكترونات حركة عشوائية في اتجاهات مختلفة.
- **الإجابة:** صحيحة ✓
- **التفسير:** في غياب فرق جهد تتحرك الإلكترونات الحرة عشوائيًا فيكون محصلة انتقالها في أي اتجاه صفرًا، ولا ينشأ تيار إلا عند تطبيق مجال كهربائي يضيف إليها حركة انجراف منتظمة.
### سؤال ٢: تعريف شدة التيار
- **السؤال:** شدة التيار الكهربائي هي كمية الشحنة \`q\` التي تعبر مقطعًا من الموصل في الثانية الواحدة، وتحسب بالعلاقة \`I = q / t\`.
- **الإجابة:** صحيحة ✓
- **التفسير:** قسمة الشحنة على الزمن تعطي الشحنة المارة في كل ثانية، وهذا هو تعريف شدة التيار.
### سؤال ٣: تعريف الأمبير
- **السؤال:** الأمبير هو مقدار شدة التيار الكهربائي الناتج عن حركة شحنة مقدارها \`1 C\` تعبر مقطعًا من الموصل في الدقيقة الواحدة.
- **الإجابة:** خاطئة ✗
- **التصحيح:** الأمبير هو شدة التيار الناتج عن عبور شحنة \`1 C\` مقطع الموصل في **الثانية** الواحدة، أي \`1 A = 1 C/s\`. أما \`1 C\` في الدقيقة فتعطي \`1/60 ≈ 0.017 A\` فقط.
### سؤال ٤: تعريف فرق الجهد
- **السؤال:** فرق الجهد بين نقطتين هو التغير في الطاقة الكامنة الكهربائية مقسومًا على كمية الشحنة المنقولة، ويحسب بالعلاقة \`V = U / q\`.
- **الإجابة:** صحيحة ✓
- **التفسير:** \`U\` هو التغير في الطاقة الكامنة بالجول و \`q\` الشحنة بالكولوم، فيكون الفولت \`1 V = 1 J/C\`.
### سؤال ٥: المقاومة المكافئة في التوازي
- **السؤال:** مقلوب المقاومة الكلية المكافئة للمقاومات الموصولة على التوازي يساوي مجموع مقلوب المقاومات المنفصلة.
- **الإجابة:** صحيحة ✓
- **التفسير:** وهو القانون \`1/R_total = 1/R₁ + 1/R₂ + 1/R₃\`، فنحسب مقلوب كل مقاومة ثم نجمعها، والمجموع يساوي مقلوب المكافئة.
### سؤال ٦: المقاومة المكافئة في التوالي
- **السؤال:** المقاومة الكلية المكافئة للمقاومات الموصولة على التوالي تساوي مجموع هذه المقاومات.
- **الإجابة:** صحيحة ✓
- **التفسير:** \`R_total = R₁ + R₂ + R₃\` لأن التيار نفسه يعبر جميع المقاومات بالتتابع.
### سؤال ٧: جمع المقاومات في التوازي
- **السؤال:** المقاومة الكلية المكافئة للمقاومات الموصولة على التوازي تساوي مجموع هذه المقاومات.
- **الإجابة:** خاطئة ✗
- **التصحيح:** في التوازي يُجمع **المقلوب**: \`1/R_total = 1/R₁ + 1/R₂ + 1/R₃\`، وتكون المكافئة أصغر من أصغر مقاومة. الجمع المباشر خاص بالتوالي.
### سؤال ٨: تعريف التوصيل المركب
- **السؤال:** التوصيل المركب هو التوصيل على التوازي.
- **الإجابة:** خاطئة ✗
- **التصحيح:** التوصيل المركب هو دائرة تجمع بين التوصيل على التوالي والتوصيل على التوازي معًا، وليس التوازي وحده.
### سؤال ٩: الهدف من أنواع التوصيل
- **السؤال:** غالبًا ما نجد في الدوائر الكهربائية مجموعة من المقاومات يتم وصل بعضها ببعض إما على التوالي لتجزئة الجهد، وإما على التوازي للحفاظ على الجهد، وأحيانًا على الشكلين معًا.
- **الإجابة:** صحيحة ✓
- **التفسير:** في التوالي يتوزع الجهد \`V = V₁ + V₂ + V₃\`، وفي التوازي يبقى الجهد نفسه على كل فرع \`V = V₁ = V₂ = V₃\`.
### سؤال ١٠: شدة التيار كمعدل
- **السؤال:** شدة التيار الكهربائي هي معدل مقدار الشحنة الكهربائية الذي يعبر مقطعًا محددًا في الموصل خلال فترة زمنية.
- **الإجابة:** صحيحة ✓
- **التفسير:** «المعدل» يعني القسمة على الزمن، أي \`I = q / t\`.
### سؤال ١١: الاتجاه الحقيقي للتيار
- **السؤال:** الاتجاه الحقيقي للتيار داخل الدائرة الكهربائية من السالب إلى الموجب.
- **الإجابة:** صحيحة ✓
- **التفسير:** الاتجاه الحقيقي هو اتجاه حركة الإلكترونات السالبة، وهي تخرج من القطب السالب للمصدر وتتجه عبر الدائرة الخارجية نحو القطب الموجب، عكس الاتجاه الاصطلاحي.
### سؤال ١٢: علاقة الجهد بالتيار
- **السؤال:** كلما زاد الجهد بين طرفي الموصل زاد التيار الكهربائي.
- **الإجابة:** صحيحة ✓
- **التفسير:** حسب قانون أوم \`I = V / R\`، فعند ثبوت المقاومة ودرجة الحرارة يتناسب التيار طرديًا مع الجهد.
### سؤال ١٣: وحدة كثافة التيار
- **السؤال:** وحدة كثافة التيار أمبير لكل متر مربع.
- **الإجابة:** صحيحة ✓
- **التفسير:** من \`J = I / A\` تكون الوحدة \`A/m²\`.
### سؤال ١٤: أثر مساحة المقطع على المقاومة
- **السؤال:** تقل مقاومة الموصل للتيار الكهربائي بزيادة مساحة المقطع.
- **الإجابة:** صحيحة ✓
- **التفسير:** من \`R = ρ·L / A\` تتناسب المقاومة عكسيًا مع المساحة \`A\`، فالمقطع الأوسع يتيح مسارات أكثر للإلكترونات.
### سؤال ١٥: صفة التيار المستمر
- **السؤال:** التيار الكهربائي المستمر ثابت الاتجاه وثابت الشدة.
- **الإجابة:** صحيحة ✓
- **التفسير:** التيار المستمر (مثل تيار البطارية) يسري في اتجاه واحد دائمًا، ومنحناه مع الزمن خط أفقي يدل على ثبات شدته. والصفة الأساسية المميزة له هي ثبات الاتجاه.
### سؤال ١٦: وحدة المقاومة
- **السؤال:** إن وحدة قياس المقاومة في النظام الدولي هي \`V/A\` ويطلق عليها اسم ohm نسبة إلى العالم جورج سيمون أوم، ورمزها \`Ω\` وتقرأ أوميغا.
- **الإجابة:** صحيحة ✓
- **التفسير:** من \`R = V / I\` تكون الوحدة \`1 Ω = 1 V/A\`.
- **ملاحظة:** التاريخ المكتوب بجوار اسم العالم \`1870\` غير دقيق؛ فجورج سيمون أوم عاش بين \`1789\` و \`1854\`، ونشر قانونه عام \`1827\`. هذا لا يغير صحة العبارة من حيث الوحدة.
### سؤال ١٧: تعريف المقاومة النوعية
- **السؤال:** المقاومة النوعية هي مقدار مقاومة جزء من المادة طوله متر واحد ومساحة مقطعه متر مربع واحد.
- **الإجابة:** صحيحة ✓
- **التفسير:** بوضع \`L = 1 m\` و \`A = 1 m²\` في \`R = ρ·L / A\` نحصل على \`R = ρ\` عدديًا.
### سؤال ١٨: تعريف الأوم
- **السؤال:** الأوم هو مقدار المقاومة التي يكون التيار الكهربائي المار فيها أمبيرًا واحدًا، إذا تم تسليط فرق جهد بين طرفيها مقداره فولت واحد.
- **الإجابة:** صحيحة ✓
- **التفسير:** \`R = V / I = 1 V / 1 A = 1 Ω\`.
### سؤال ١٩: المقاومة المكافئة في التوالي مرة أخرى
- **السؤال:** المقاومة الكلية المكافئة لمجموع المقاومات الموصولة على التوالي تساوي مجموع هذه المقاومات.
- **الإجابة:** صحيحة ✓
- **التفسير:** \`R_total = R₁ + R₂ + R₃\` (العبارة نفسها في السؤال السادس).
### سؤال ٢٠: المقاومة والتوصيل
- **السؤال:** كلما قلت مقاومة المادة زاد توصيلها للتيار الكهربائي.
- **الإجابة:** صحيحة ✓
- **التفسير:** الموصلية مقلوب المقاومية \`σ = 1/ρ\`، فكلما قلت الممانعة سهل مرور التيار.
### سؤال ٢١: المقاومة الكلية في التوالي
- **السؤال:** في توصيل المقاومات على التوالي فإن المقاومة الكلية تزداد وتكون أكبر من أكبر مقاومة.
- **الإجابة:** صحيحة ✓
- **التفسير:** بما أن \`R_total = R₁ + R₂ + R₃\` وكل المقاومات موجبة، فالمجموع أكبر من أي حد فيه.
### سؤال ٢٢: المقاومة الكلية في التوازي
- **السؤال:** في توصيل المقاومات على التوازي فإن المقاومة الكلية تقل وتكون أصغر من أصغر مقاومة.
- **الإجابة:** صحيحة ✓
- **التفسير:** \`1/R_total\` أكبر من مقلوب أي مقاومة منفردة، فتكون \`R_total\` أصغر من أصغرها؛ مثلًا \`6 Ω\` مع \`3 Ω\` تعطيان \`2 Ω\`.
### سؤال ٢٣: توصيل سوائل الجسم والماء المالح
- **السؤال:** موائع الجسم البشري والماء المالح جيدة التوصيل للتيار الكهربائي.
- **الإجابة:** صحيحة ✓
- **التفسير:** تحتوي على أيونات ذائبة (مثل أيونات الصوديوم والكلور) تتحرك وتنقل الشحنة، ولهذا تكون الكهرباء خطرة على الإنسان خاصة مع وجود الماء.
### سؤال ٢٤: احتراق مصباح في دائرة توالٍ
- **السؤال:** عند احتراق أحد المصابيح أو إزالة أحدها من مكانه في التوصيل على التوالي فإن بقية المصابيح تنطفئ.
- **الإجابة:** صحيحة ✓
- **التفسير:** في التوالي مسار واحد للتيار، فإذا انقطع عند أي مصباح أصبحت الدائرة مفتوحة وتوقف التيار في الجميع.
### سؤال ٢٥: احتراق مصباح في دائرة توازٍ
- **السؤال:** عند احتراق أحد المصابيح أو إزالة أحدها من مكانه في التوصيل على التوازي لا يتأثر سطوع بقية المصابيح.
- **الإجابة:** صحيحة ✓
- **التفسير:** كل مصباح على فرع مستقل متصل مباشرة بالمصدر وجهده \`V\` نفسه، فانقطاع فرع لا يغيّر جهد الفروع الأخرى ولا تيارها، ولهذا توصل أجهزة المنزل على التوازي.
### سؤال ٢٦: دائرة مركبة المقاومة الكلية والتيار الكلي
- **السؤال:** من الشكل: مقاومتان \`R₁ = 6 Ω\` و \`R₂ = 6 Ω\` موصولتان على التوازي، ومجموعتهما موصولة على التوالي مع \`R₃ = 9 Ω\` وبطارية جهدها \`V = 6 V\`. أوجد: المقاومة الكلية (\`10 Ω\` · \`11 Ω\` · \`12 Ω\`)، والتيار الكلي (\`0.5 A\` · \`1 A\` · \`1.5 A\`).
- **المعطيات:** \`R₁ = 6 Ω\` · \`R₂ = 6 Ω\` · \`R₃ = 9 Ω\` · \`V = 6 V\`
- **المطلوب:** \`R_total\` و \`I\`
- **تحليل الدائرة:** هذه دائرة مركبة؛ نبدأ بالجزء المتوازي فنستبدله بمقاومة مكافئة واحدة، ثم نجمعها مع \`R₃\` على التوالي لأن التيار الكلي كله يمر فيها.
- **القانون:** \`1/R₁₂ = 1/R₁ + 1/R₂\` (الحالة الخاصة: \`R₁₂ = R₁·R₂ / (R₁ + R₂)\`) ثم \`R_total = R₁₂ + R₃\` ثم \`I = V / R_total\`
- **الحل:** مكافئة الجزء المتوازي: البسط \`6 × 6 = 36\` والمقام \`6 + 6 = 12\`، إذن \`R₁₂ = 36 / 12 = 3 Ω\`
- **الحل:** المقاومة الكلية: \`R_total = 3 + 9 = 12 Ω\`
- **الحل:** التيار الكلي: \`I = 6 V / 12 Ω = 0.5 A\`
- **التحقق:** جهد \`R₃\`: \`0.5 × 9 = 4.5 V\`، وجهد الجزء المتوازي: \`0.5 × 3 = 1.5 V\`، ومجموعهما \`6 V\` ✓ ويمر في كل من \`R₁\` و \`R₂\` نصف التيار \`0.25 A\` لأنهما متساويتان.
- **النتيجة:** المقاومة الكلية \`12 Ω\` والتيار الكلي \`0.5 A\` ✓
### سؤال ٢٧: نوع الشحنة المكونة للتيار في الموصل
- **السؤال:** الشحنة التي تشكل التيار الكهربائي المار عبر الموصل هي: الإلكترونات · البروتونات · النيوترونات.
- **الإجابة:** الإلكترونات ✓
- **التفسير:** في الموصلات المعدنية تبقى البروتونات ثابتة داخل الأنوية، والنيوترونات متعادلة لا شحنة لها، أما الإلكترونات الحرة فهي التي تتحرك وتنقل الشحنة.
`,
ex:{q:`دائرة مركبة: مقاومة \`2 Ω\` على التوالي مع مجموعة توازي (\`6 Ω\` و \`3 Ω\`)، والمصدر \`12 V\`. أوجد المقاومة الكلية والتيار الرئيسي.`,
st:[`التوازي أولًا: \`(6 × 3)/(6 + 3) = 2 Ω\``,`ثم التوالي: \`R = 2 + 2 = 4 Ω\``,`\`I = 12/4 = 3 A\``],
a:`\`R = 4 Ω\` و \`I = 3 A\``},
qz:[
{q:`الأمبير هو تيار ناتج عن مرور \`1 C\` في:`,o:[`الدقيقة`,`الثانية`,`الساعة`,`الميلي ثانية`],a:1,w:`A = C/s (العبارة في الحقيبة بالدقيقة خاطئة).`},
{q:`الاتجاه الحقيقي لحركة الإلكترونات في الدائرة الخارجية:`,o:[`من القطب الموجب إلى السالب`,`من القطب السالب إلى الموجب`,`لا تتحرك`,`عشوائي دائمًا بلا اتجاه`],a:1,w:`الإلكترونات من − إلى +، والاتجاه الاصطلاحي عكسه.`},
{q:`وحدة قياس كثافة التيار:`,o:[`A·m²`,`A/m²`,`C/m`,`V/m`],a:1,w:`J = I/A.`},
{q:`ماذا يحدث لمقاومة موصل عند زيادة مساحة مقطعه؟`,o:[`تزداد`,`تقل`,`لا تتغير`,`تصبح صفرًا`],a:1,w:`R = ρL/A.`},
{q:`التوصيل المركب هو:`,o:[`توصيل على التوازي فقط`,`توصيل على التوالي فقط`,`خليط من التوصيل على التوالي والتوازي`,`توصيل بدون مصدر`],a:2,w:`يجمع بين التوالي والتوازي في دائرة واحدة.`},
{q:`توصل المقاومات على التوالي بهدف:`,o:[`تجزئة الجهد`,`الحفاظ على الجهد`,`زيادة التيار`,`تقليل المقاومة`],a:0,w:`وعلى التوازي للحفاظ على الجهد.`},
{q:`وحدة المقاومة \`volt/ampere\` وتسمى:`,o:[`الواط`,`الأوم`,`الفاراد`,`الكولوم`],a:1,w:`الأوم Ω.`}
]}
];
